INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca78594-17b3-4873-95d3-5e4fe01bdda0', '五松驛', '五松驛', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["獨下長亭念過秦，五松不見見輿薪。","只應既斬斯高後，尋被樵人用斧斤。"]', '["独下长亭念過秦，五松不见见輿薪。","只應既斬斯高後，尋被樵人用斧斤。"]', '诗', 'shi', '', NULL, '五松驛 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('679d385c-da9a-45a5-b415-56cae6f635a8', '灞岸', '灞岸', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["山東今歲點行頻，幾處冤魂哭虜塵。","灞水橋邊倚華表，平時二月有東巡。"]', '["山东今歲点行頻，幾处冤魂哭虜塵。","灞水橋邊倚华表，平时二月有东巡。"]', '诗', 'shi', '', NULL, '灞岸 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca1f6f35-b075-48c5-8419-dedc291da4d3', '送臻師二首 一', '送臻師二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昔去靈山非拂席，今來滄海欲求珠。","楞伽頂上清涼池，善眼仙人憶我無。"]', '["昔去靈山非拂席，今来滄海欲求珠。","楞伽頂上清涼池，善眼仙人憶我無。"]', '诗', 'shi', '', NULL, '送臻師二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60cb7f6e-8832-4e13-9571-4099f2db9a66', '送臻師二首 二', '送臻師二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["苦海迷途去未因，東方過此幾微塵。","何當百億蓮花上，一一蓮花見佛身。"]', '["苦海迷途去未因，东方過此幾微塵。","何當百億蓮花上，一一蓮花见佛身。"]', '诗', 'shi', '', NULL, '送臻師二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91489186-6dbb-4bb5-a120-ac3fa7403e42', '七夕', '七夕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鸞扇斜分鳳幄開，星橋橫過鵲飛迴。","爭將世上無期別，換得年年一度來。"]', '["鸾扇斜分鳳幄开，星橋橫過鵲飞迴。","爭將世上無期別，換得年年一度来。"]', '诗', 'shi', '', NULL, '七夕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5361c2f5-ccc3-4eae-9c40-1b137e5fd475', '謝先輩防記念拙詩甚多異日偶有此寄', '謝先輩防記念拙诗甚多異日偶有此寄', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["曉用雲添句，寒將雪命篇。","良辰多自感，作者豈皆然。","熟寢初同鶴，含嘶欲並蟬。","題詩長不展，得處定應偏。","南浦無窮樹，西樓不住煙。","改成人寂寂，寄與路綿綿。","星勢寒垂地，河聲曉上天。","夫君自有恨，聊借此中傳。"]', '["晓用云添句，寒將雪命篇。","良辰多自感，作者豈皆然。","熟寢初同鹤，含嘶欲並蟬。","題诗长不展，得处定應偏。","南浦無窮樹，西楼不住煙。","改成人寂寂，寄與路綿綿。","星勢寒垂地，河声晓上天。","夫君自有恨，聊借此中傳。"]', '诗', 'shi', '', NULL, '謝先輩防記念拙詩甚多異日偶有此寄 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c5d1dd9-3209-4697-9a64-99a55d5e24f2', '馬嵬二首 一', '马嵬二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["冀馬燕犀動地來，自埋紅粉自成灰。","君王若道能傾國，玉輦何由過馬嵬。"]', '["冀马燕犀动地来，自埋紅粉自成灰。","君王若道能傾国，玉輦何由過马嵬。"]', '诗', 'shi', '', NULL, '馬嵬二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb485152-2e04-4d29-a43a-842210b44203', '馬嵬二首 二', '马嵬二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["海外徒聞更九州，他生未卜此生休。","空聞虎旅傳宵柝，無復雞人報曉籌。","此日六軍同駐馬，當時七夕笑牽牛。","如何四紀爲天子，不及盧家有莫愁。"]', '["海外徒闻更九州，他生未卜此生休。","空闻虎旅傳宵柝，無复雞人報晓籌。","此日六軍同駐马，當时七夕笑牽牛。","如何四紀爲天子，不及盧家有莫愁。"]', '诗', 'shi', '', NULL, '馬嵬二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f3e05a-fdcd-4592-952f-0cddcc4d04ba', '可歎', '可歎', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["幸會東城宴未迴，年華憂共水相催。","梁家宅裏秦宮入，趙后樓中赤鳳來。","冰簟且眠金鏤枕，瓊筵不醉玉交杯。","宓妃愁坐芝田館，用盡陳王八斗才。"]', '["幸會东城宴未迴，年华憂共水相催。","梁家宅裏秦宮入，趙后楼中赤鳳来。","冰簟且眠金鏤枕，瓊筵不醉玉交杯。","宓妃愁坐芝田館，用尽陳王八斗才。"]', '诗', 'shi', '', NULL, '可歎 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa6eaa7-302d-4639-ab43-1f008853d38d', '望喜驛別嘉陵江水二絕 一', '望喜驛別嘉陵江水二絕 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["嘉陵江水此東流，望喜樓中憶閬州。","若到閬中還赴海，閬州應更有高樓。"]', '["嘉陵江水此东流，望喜楼中憶閬州。","若到閬中還赴海，閬州應更有高楼。"]', '诗', 'shi', '', NULL, '望喜驛別嘉陵江水二絕 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2938ba1-a4b2-4b78-9068-42274058808f', '望喜驛別嘉陵江水二絕 二', '望喜驛別嘉陵江水二絕 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["千里嘉陵江水色，含煙帶月碧於藍。","今朝相送東流後，猶自驅車更向南。"]', '["千里嘉陵江水色，含煙带月碧於藍。","今朝相送东流後，猶自驱车更向南。"]', '诗', 'shi', '', NULL, '望喜驛別嘉陵江水二絕 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e556e770-7e3a-4061-8c3e-8bcd9ee4fb48', '別薛嵒賓', '別薛嵒賓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["曙爽行將拂，晨清坐欲凌。","別離真不那，風物正相仍。","漫水任誰照，衰花淺自矜。","還將兩袖淚，同向一窗燈。","桂樹乖真隱，芸香是小懲。","清規無以況，且用玉壺冰。"]', '["曙爽行將拂，晨清坐欲凌。","別離真不那，风物正相仍。","漫水任誰照，衰花淺自矜。","還將兩袖泪，同向一窗灯。","桂樹乖真隐，芸香是小懲。","清規無以況，且用玉壺冰。"]', '诗', 'shi', '', NULL, '別薛嵒賓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a50539b-3413-4202-b9e8-030f8147e53a', '富平少侯', '富平少侯', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["七國三邊未到憂，十三身襲富平候。","不收金彈拋林外，却惜銀牀在井頭。","綵樹轉燈珠錯落，繡檀迴枕玉雕鎪。","當關不報侵晨客，新得佳人字莫愁。"]', '["七国三邊未到憂，十三身襲富平候。","不收金彈拋林外，却惜銀牀在井头。","綵樹轉灯珠錯落，繡檀迴枕玉雕鎪。","當关不報侵晨客，新得佳人字莫愁。"]', '诗', 'shi', '', NULL, '富平少侯 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416f5819-44ca-416d-ab50-193ae2c237cb', '腸', '腸', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["有懷非惜恨，不奈寸腸何。","即席迴彌久，前時斷固多。","熱應翻急燒，冷欲徹微波。","隔樹澌澌雨，通池點點荷。","倦程山向背，望國闕嵯峨。","故念飛書及，新懽借夢過。","染筠休伴淚，繞雪莫追歌。","擬問陽臺事，年深楚語訛。"]', '["有懷非惜恨，不奈寸腸何。","即席迴彌久，前时斷固多。","熱應翻急燒，冷欲徹微波。","隔樹澌澌雨，通池点点荷。","倦程山向背，望国闕嵯峨。","故念飞书及，新懽借梦過。","染筠休伴泪，繞雪莫追歌。","擬问陽台事，年深楚語訛。"]', '诗', 'shi', '', NULL, '腸 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61209a6-77c3-4793-8bc5-c1b476791e2d', '贈宇文中丞', '贈宇文中丞', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["欲構中天正急材，自緣煙水戀平臺。","人間只有嵇延祖，最望山公啓事來。"]', '["欲構中天正急材，自緣煙水戀平台。","人间只有嵇延祖，最望山公啓事来。"]', '诗', 'shi', '', NULL, '贈宇文中丞 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3213aad6-a6a1-4398-9798-5722e36db868', '曉起', '晓起', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["擬杯當曉起，呵鏡可微寒。","隔箔山櫻熟，褰帷桂燭殘。","書長爲報晚，夢好更尋難。","影響輸雙蝶，偏過舊畹蘭。"]', '["擬杯當晓起，呵镜可微寒。","隔箔山櫻熟，褰帷桂燭殘。","书长爲報晚，梦好更尋难。","影响輸雙蝶，偏過旧畹蘭。"]', '诗', 'shi', '', NULL, '曉起 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fde46a2-ddcf-46ed-8a36-6e980c7c7e57', '閨情', '閨情', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紅露花房白蜜脾，黃蜂紫蝶兩參差。","春窗一覺風流夢，却是同袍不得知。"]', '["紅露花房白蜜脾，黄蜂紫蝶兩參差。","春窗一覺风流梦，却是同袍不得知。"]', '诗', 'shi', '', NULL, '閨情 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2628ac9d-9580-4bbd-bbbb-f18d88111367', '月夕', '月夕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["草下陰蟲葉上霜，朱欄迢遰壓湖光。","兔寒蟾冷桂花白，此夜姮娥應斷腸。"]', '["草下陰蟲葉上霜，朱欄迢遰壓湖光。","兔寒蟾冷桂花白，此夜姮娥應斷腸。"]', '诗', 'shi', '', NULL, '月夕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8960b02a-c182-4559-820f-ff5de87fe7af', '杏花', '杏花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["上國昔相值，亭亭如欲言。","異鄉今暫賞，眽眽豈無恩。","援少風多力，墻高月有痕。","爲含無限意，遂對不勝繁。","仙子玉京路，主人金谷園。","幾時辭碧落，誰伴過黃昏。","鏡拂鉛華膩，爐藏桂燼溫。","終應催竹葉，先擬詠桃根。","莫學啼成血，從教夢寄魂。","吳王採香徑，失路入煙村。"]', '["上国昔相值，亭亭如欲言。","異乡今暫賞，眽眽豈無恩。","援少风多力，墻高月有痕。","爲含無限意，遂对不勝繁。","仙子玉京路，主人金谷园。","幾时辞碧落，誰伴過黄昏。","镜拂鉛华膩，爐藏桂燼溫。","終應催竹葉，先擬詠桃根。","莫学啼成血，從教梦寄魂。","吳王採香徑，失路入煙村。"]', '诗', 'shi', '', NULL, '杏花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039da037-7d76-4ada-9506-457d36bdcc9b', '燈', '灯', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["皎潔終無倦，煎熬亦自求。","花時隨酒遠，雨後背窗休。","冷暗黃茅驛，暄明紫桂樓。","錦囊名畫揜，玉局敗碁收。","何處無佳夢，誰人不隱憂。","影隨簾押轉，光信簟文流。","客自勝潘岳，儂今定莫愁。","固應留半燄，廻照下幃羞。"]', '["皎潔終無倦，煎熬亦自求。","花时隨酒远，雨後背窗休。","冷暗黄茅驛，暄明紫桂楼。","錦囊名畫揜，玉局敗碁收。","何处無佳梦，誰人不隐憂。","影隨簾押轉，光信簟文流。","客自勝潘岳，儂今定莫愁。","固應留半燄，廻照下幃羞。"]', '诗', 'shi', '', NULL, '燈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc78c4f-f31c-42db-a185-ee62444ba3c8', '清河', '清河', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["舟小迴仍數，樓危凭亦頻。","燕來從及社，蝶舞太侵晨。","絳雪除煩後，霜梅取味新。","年華無一事，只是自傷春。"]', '["舟小迴仍數，楼危凭亦頻。","燕来從及社，蝶舞太侵晨。","絳雪除煩後，霜梅取味新。","年华無一事，只是自傷春。"]', '诗', 'shi', '', NULL, '清河 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e1d9d3-c1a9-43ca-a688-4a31348db4d4', '韈', '韈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["嘗聞宓妃韈，渡水欲生塵。","好借常娥著，清秋踏月輪。"]', '["嘗闻宓妃韈，渡水欲生塵。","好借常娥著，清秋踏月輪。"]', '诗', 'shi', '', NULL, '韈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503fd3f8-0607-410d-849a-859887ed55b1', '追代盧家人嘲堂內', '追代盧家人嘲堂內', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["道却橫波字，人前莫謾羞。","只應同楚水，長短入淮流。"]', '["道却橫波字，人前莫謾羞。","只應同楚水，长短入淮流。"]', '诗', 'shi', '', NULL, '追代盧家人嘲堂內 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23436570-7e46-47a8-ac49-80f23ed0a704', '代應', '代應', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["本來銀漢是紅墻，隔得盧家白玉堂。","誰與王昌報消息，盡知三十六鴛鴦。"]', '["本来銀漢是紅墻，隔得盧家白玉堂。","誰與王昌報消息，尽知三十六鴛鴦。"]', '诗', 'shi', '', NULL, '代應 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f74f106-fbf2-40f7-aa71-d3e108bc6c23', '離亭賦得折楊柳二首 一', '離亭賦得折楊柳二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["暫憑樽酒送無憀，莫損愁眉與細腰。","人世死前惟有別，春風爭擬惜長條。"]', '["暫憑樽酒送無憀，莫損愁眉與細腰。","人世死前惟有別，春风爭擬惜长條。"]', '诗', 'shi', '', NULL, '離亭賦得折楊柳二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff15f45a-2833-422f-bb24-5353d22f5547', '離亭賦得折楊柳二首 二', '離亭賦得折楊柳二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["含煙惹霧每依依，萬緒千條拂落暉。","爲報行人休盡折，半留相送半迎歸。"]', '["含煙惹霧每依依，万緒千條拂落暉。","爲報行人休尽折，半留相送半迎归。"]', '诗', 'shi', '', NULL, '離亭賦得折楊柳二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9910f88-11a2-424c-bfc2-88c386f476b5', '寄永道士', '寄永道士', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["共上雲山獨下遲，陽臺白道細如絲。","君今併倚三珠樹，不記人間落葉時。"]', '["共上云山独下遲，陽台白道細如絲。","君今併倚三珠樹，不記人间落葉时。"]', '诗', 'shi', '', NULL, '寄永道士 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de022e2-321e-4983-b4f6-c94e07c2f299', '華州周大夫宴席', '华州周大夫宴席', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["郡齋何用酒如泉，飲德先時已醉眠。","若共門人推禮分，戴崇爭得及彭宣。"]', '["郡斋何用酒如泉，饮德先时已醉眠。","若共门人推禮分，戴崇爭得及彭宣。"]', '诗', 'shi', '', NULL, '華州周大夫宴席 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa48daca-5999-4ed4-9f70-61209c5b0bc4', '荆山', '荆山', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["壓河連華勢孱顏，鳥沒雲歸一望間。","楊僕移關三百里，可能全是爲荆山。"]', '["壓河連华勢孱顏，鸟沒云归一望间。","楊僕移关三百里，可能全是爲荆山。"]', '诗', 'shi', '', NULL, '荆山 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1b3f06-88c8-4313-ae2b-644908adcff9', '次陝州先寄源從事', '次陝州先寄源從事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["離思羈愁日欲晡，東周西雍此分塗。","迴鑾佛寺高多少，望盡黃河一曲無。"]', '["離思羈愁日欲晡，东周西雍此分塗。","迴鑾佛寺高多少，望尽黄河一曲無。"]', '诗', 'shi', '', NULL, '次陝州先寄源從事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfce5f03-6022-43e0-af8b-e8bef9b87524', '過鄭廣文舊居', '過鄭廣文旧居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["宋玉平生恨有餘，遠循三楚弔三閭。","可憐留著臨江宅，異代應教庾信居。"]', '["宋玉平生恨有餘，远循三楚弔三閭。","可怜留著臨江宅，異代應教庾信居。"]', '诗', 'shi', '', NULL, '過鄭廣文舊居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc92d2c-5bba-4cf8-a369-1557fe556342', '東下三旬苦于風土馬上戲作', '东下三旬苦于风土马上戲作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["路遶函關東復東，身騎征馬逐驚蓬。","天池遼闊誰相待，日日虛乘九萬風。"]', '["路遶函关东复东，身騎征马逐驚蓬。","天池遼闊誰相待，日日虛乘九万风。"]', '诗', 'shi', '', NULL, '東下三旬苦于風土馬上戲作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1e816b7-c6bf-4bf2-8158-d060202159ea', '莫愁', '莫愁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雪中梅下與誰期，梅雪相兼一萬枝。","若是石城無艇子，莫愁還自有愁時。"]', '["雪中梅下與誰期，梅雪相兼一万枝。","若是石城無艇子，莫愁還自有愁时。"]', '诗', 'shi', '', NULL, '莫愁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f224ed41-9d7f-4875-8823-781e34046348', '夢令狐學士', '梦令狐学士', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["山驛荒涼白竹扉，殘燈向曉夢清暉。","右銀臺路雪三尺，鳳詔裁成當直歸。"]', '["山驛荒涼白竹扉，殘灯向晓梦清暉。","右銀台路雪三尺，鳳詔裁成當直归。"]', '诗', 'shi', '', NULL, '夢令狐學士 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008d34f0-4019-42f0-9134-d86aed22d6a8', '涉洛川', '涉洛川', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["通谷陽林不見人，我來遺恨古時春。","宓妃漫結無窮恨，不爲君王殺灌均。"]', '["通谷陽林不见人，我来遺恨古时春。","宓妃漫結無窮恨，不爲君王殺灌均。"]', '诗', 'shi', '', NULL, '涉洛川 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('167b14c9-a053-43a6-bbbf-da8a86ae688c', '有感', '有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["中路因循我所長，古來才命兩相妨。","勸君莫強安蛇足，一醆芳醪不得嘗。"]', '["中路因循我所长，古来才命兩相妨。","勸君莫強安蛇足，一醆芳醪不得嘗。"]', '诗', 'shi', '', NULL, '有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0218871b-e34d-419a-a72d-589772fd04cd', '宮妓', '宮妓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["珠箔輕明拂玉墀，披香新殿鬬腰支。","不須看盡魚龍戲，終遣君王怒偃師。"]', '["珠箔轻明拂玉墀，披香新殿鬬腰支。","不須看尽鱼龙戲，終遣君王怒偃師。"]', '诗', 'shi', '', NULL, '宮妓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b35bd3-eec3-43c5-852e-00f5910caca7', '宮辭', '宮辞', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["君恩如水向東流，得寵憂移失寵愁。","莫向尊前奏花落，涼風只在殿西頭。"]', '["君恩如水向东流，得寵憂移失寵愁。","莫向尊前奏花落，涼风只在殿西头。"]', '诗', 'shi', '', NULL, '宮辭 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f79086-d6ad-44d5-9380-6648cabaa331', '代贈二首 一', '代贈二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["樓上黃昏欲望休，玉梯橫絕月中鉤。","芭蕉不展丁香結，同向春風各自愁。"]', '["楼上黄昏欲望休，玉梯橫絕月中鉤。","芭蕉不展丁香結，同向春风各自愁。"]', '诗', 'shi', '', NULL, '代贈二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51f2bb0f-3b09-4b4d-9c4f-a416190e8ae6', '代贈二首 二', '代贈二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東南日出照高樓，樓上離人唱石州。","總把春山掃眉黛，不知供得幾多愁。"]', '["东南日出照高楼，楼上離人唱石州。","總把春山掃眉黛，不知供得幾多愁。"]', '诗', 'shi', '', NULL, '代贈二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f6bf355-ab52-4a0a-a42f-8d99bc7b63a4', '楚吟', '楚吟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["山上離宮宮上樓，樓前宮畔暮江流。","楚天長短黃昏雨，宋玉無愁亦自愁。"]', '["山上離宮宮上楼，楼前宮畔暮江流。","楚天长短黄昏雨，宋玉無愁亦自愁。"]', '诗', 'shi', '', NULL, '楚吟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2161a569-6250-4886-9500-2168821b62be', '瑤池', '瑤池', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["瑤池阿母綺窗開，黃竹歌聲動地哀。","八駿日行三萬里，穆王何事不重來。"]', '["瑤池阿母綺窗开，黄竹歌声动地哀。","八駿日行三万里，穆王何事不重来。"]', '诗', 'shi', '', NULL, '瑤池 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b90f8b9a-5601-4c98-8462-1ea656ab2340', '柳', '柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["爲有橋邊拂面香，何曾自敢占流光。","後庭玉樹承恩澤，不信年華有斷腸。"]', '["爲有橋邊拂面香，何曾自敢占流光。","後庭玉樹承恩澤，不信年华有斷腸。"]', '诗', 'shi', '', NULL, '柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dcd9b4a-7516-43e3-82a6-cc47ce7dfe94', '寄在朝鄭曹獨孤李四同年', '寄在朝鄭曹独孤李四同年', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昔歲陪遊舊跡多，風光今日兩蹉跎。","不因醉本蘭亭在，兼忘當年舊永和。"]', '["昔歲陪游旧跡多，风光今日兩蹉跎。","不因醉本蘭亭在，兼忘當年旧永和。"]', '诗', 'shi', '', NULL, '寄在朝鄭曹獨孤李四同年 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7cf50f2-f8d9-4620-83c7-723857af815e', '南朝', '南朝', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["地險悠悠天險長，金陵王氣應瑤光。","休誇此地分天下，只得徐妃半面妝。"]', '["地險悠悠天險长，金陵王氣應瑤光。","休誇此地分天下，只得徐妃半面妝。"]', '诗', 'shi', '', NULL, '南朝 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8849cd61-b181-4847-885d-8aea2e5165ca', '題漢祖廟', '題漢祖廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["乘運應須宅八荒，男兒安在戀池隍。","君王自起新豐後，項羽何曾在故鄉。"]', '["乘運應須宅八荒，男兒安在戀池隍。","君王自起新豐後，項羽何曾在故乡。"]', '诗', 'shi', '', NULL, '題漢祖廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607cacdd-9888-4281-b43b-071bd9085ec1', '韓冬郎即席爲詩相送一座盡驚他日余方追吟連宵侍坐裴回久之句有老成之風因成二絕寄酬兼呈畏之員外 一', '韓冬郎即席爲诗相送一座尽驚他日余方追吟連宵侍坐裴回久之句有老成之风因成二絕寄酬兼呈畏之員外 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十歲裁詩走馬成，冷灰殘燭動離情。","桐花萬里丹山路，雛鳳清於老鳳聲。"]', '["十歲裁诗走马成，冷灰殘燭动離情。","桐花万里丹山路，雛鳳清於老鳳声。"]', '诗', 'shi', '', NULL, '韓冬郎即席爲詩相送一座盡驚他日余方追吟連宵侍坐裴回久之句有老成之風因成二絕寄酬兼呈畏之員外 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a194afaa-dde6-4cf5-809b-c82206f19989', '韓冬郎即席爲詩相送一座盡驚他日余方追吟連宵侍坐裴回久之句有老成之風因成二絕寄酬兼呈畏之員外 二', '韓冬郎即席爲诗相送一座尽驚他日余方追吟連宵侍坐裴回久之句有老成之风因成二絕寄酬兼呈畏之員外 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["劒棧風檣各苦辛，別時冰雪到時春。","爲憑何遜休聯句，瘦盡東陽姓沈人。"]', '["劒棧风檣各苦辛，別时冰雪到时春。","爲憑何遜休聯句，瘦尽东陽姓沈人。"]', '诗', 'shi', '', NULL, '韓冬郎即席爲詩相送一座盡驚他日余方追吟連宵侍坐裴回久之句有老成之風因成二絕寄酬兼呈畏之員外 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a964c1-09a8-462f-9432-f6138e4391be', '評事翁寄賜餳粥走筆爲答', '評事翁寄賜餳粥走笔爲答', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["粥香餳白杏花天，省對流鸎坐綺筵。","今日寄來春已老，鳳樓迢遞憶鞦韆。"]', '["粥香餳白杏花天，省对流鸎坐綺筵。","今日寄来春已老，鳳楼迢遞憶鞦韆。"]', '诗', 'shi', '', NULL, '評事翁寄賜餳粥走筆爲答 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7a0c41-e77b-4b71-b57c-367b2021f941', '東阿王', '东阿王', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["國事分明屬灌均，西陵魂斷夜來人。","君王不得爲天子，半爲當時賦洛神。"]', '["国事分明屬灌均，西陵魂斷夜来人。","君王不得爲天子，半爲當时賦洛神。"]', '诗', 'shi', '', NULL, '東阿王 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6665561f-223d-440e-88f2-428f3f252899', '聖女祠', '聖女祠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["松篁臺殿蕙香幃，龍護瑤窗鳳掩扉。","無質易迷三里霧，不寒長著五銖衣。","人間定有崔羅什，天上應無劉武威。","寄問釵頭雙白燕，每朝珠館幾時歸。"]', '["松篁台殿蕙香幃，龙護瑤窗鳳掩扉。","無質易迷三里霧，不寒长著五銖衣。","人间定有崔羅什，天上應無劉武威。","寄问釵头雙白燕，每朝珠館幾时归。"]', '诗', 'shi', '', NULL, '聖女祠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc12e85-7dfc-40a5-a3a2-1ab451c8c388', '獨居有懷', '独居有懷', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["麝重愁風逼，羅疎畏月侵。","怨魂迷恐斷，嬌喘細疑沈。","數急芙蓉帶，頻抽翡翠簪。","柔情終不遠，遙妬已先深。","浦冷鴛鴦去，園空蛺蝶尋。","蠟花長遞淚，箏柱鎮移心。","覓使嵩雲暮，回頭灞岸陰。","只聞涼葉院，露井近寒砧。"]', '["麝重愁风逼，羅疎畏月侵。","怨魂迷恐斷，嬌喘細疑沈。","數急芙蓉带，頻抽翡翠簪。","柔情終不远，遙妬已先深。","浦冷鴛鴦去，园空蛺蝶尋。","蠟花长遞泪，箏柱鎮移心。","覓使嵩云暮，回头灞岸陰。","只闻涼葉院，露井近寒砧。"]', '诗', 'shi', '', NULL, '獨居有懷 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875539c2-cf3b-4697-8216-9512aa6a15eb', '過景陵', '過景陵', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["武皇精魄久仙昇，帳殿淒涼煙霧凝。","俱是蒼生留不得，鼎湖何異魏西陵。"]', '["武皇精魄久仙昇，帳殿淒涼煙霧凝。","俱是蒼生留不得，鼎湖何異魏西陵。"]', '诗', 'shi', '', NULL, '過景陵 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5773a5b-1124-49b5-8154-1dbd684b1d62', '臨發崇讓宅紫薇', '臨發崇讓宅紫薇', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一樹濃姿獨看來，秋庭暮雨類輕埃。","不先搖落應爲有，已欲別離休更開。","桃綬含情依露井，柳綿相憶隔章臺。","天涯地角同榮謝，豈要移根上苑栽。"]', '["一樹濃姿独看来，秋庭暮雨類轻埃。","不先搖落應爲有，已欲別離休更开。","桃綬含情依露井，柳綿相憶隔章台。","天涯地角同榮謝，豈要移根上苑栽。"]', '诗', 'shi', '', NULL, '臨發崇讓宅紫薇 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54da7f86-44e4-4057-a4f0-b2db15b336d6', '及第東歸次灞上却寄同年', '及第东归次灞上却寄同年', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["芳桂當年各一枝，行期未分壓春期。","江魚朔雁長相憶，秦樹嵩雲自不知。","下苑經過勞想像，東門送餞又差池。","灞陵柳色無離恨，莫枉長條贈所思。"]', '["芳桂當年各一枝，行期未分壓春期。","江鱼朔雁长相憶，秦樹嵩云自不知。","下苑經過勞想像，东门送餞又差池。","灞陵柳色無離恨，莫枉长條贈所思。"]', '诗', 'shi', '', NULL, '及第東歸次灞上却寄同年 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2186935c-d029-4ee0-b0b1-4f6341b0323b', '野菊', '野菊', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["苦竹園南椒塢邊，微香冉冉淚涓涓。","已悲節物同寒雁，忍委芳心與暮蟬。","細路獨來當此夕，清尊相伴省他年。","紫雲新苑移花處，不取霜栽近御筵。"]', '["苦竹园南椒塢邊，微香冉冉泪涓涓。","已悲節物同寒雁，忍委芳心與暮蟬。","細路独来當此夕，清尊相伴省他年。","紫云新苑移花处，不取霜栽近御筵。"]', '诗', 'shi', '', NULL, '野菊 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7a33cd-54a7-47bb-b92d-d4bdd4b879cd', '板橋曉別', '板橋晓別', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["回望高城落曉河，長亭窗戶壓微波。","水仙欲上鯉魚去，一夜芙蓉紅淚多。"]', '["回望高城落晓河，长亭窗戶壓微波。","水仙欲上鯉鱼去，一夜芙蓉紅泪多。"]', '诗', 'shi', '', NULL, '板橋曉別 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a37bce0-71e0-41b2-bbbd-73c069c2cdbc', '過伊僕射舊宅', '過伊僕射旧宅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["朱邸方酬力戰功，華筵俄歎逝波窮。","回廊簷斷燕飛去，小閣塵凝人語空。","幽淚欲乾殘菊露，餘香猶入敗荷風。","何能更涉瀧江去，獨立寒流弔楚宮。"]', '["朱邸方酬力戰功，华筵俄歎逝波窮。","回廊簷斷燕飞去，小閣塵凝人語空。","幽泪欲乾殘菊露，餘香猶入敗荷风。","何能更涉瀧江去，独立寒流弔楚宮。"]', '诗', 'shi', '', NULL, '過伊僕射舊宅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7bd924-05fe-4c56-b766-2e5abc43d886', '關門柳', '关门柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["永定河邊一行柳，依依長發故年春。","東來西去人情薄，不爲清陰減路塵。"]', '["永定河邊一行柳，依依长發故年春。","东来西去人情薄，不爲清陰減路塵。"]', '诗', 'shi', '', NULL, '關門柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94bd685-56c2-4226-a759-c3ae97956296', '酬別令狐補闕', '酬別令狐補闕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["惜別夏仍半，回途秋已期。","那脩直諫草，更賦贈行詩。","錦段知無報，青萍肯見疑。","人生有通塞，公等繫安危。","警露鶴辭侶，吸風蟬抱枝。","彈冠如不問，又到掃門時。"]', '["惜別夏仍半，回途秋已期。","那脩直諫草，更賦贈行诗。","錦段知無報，青萍肯见疑。","人生有通塞，公等繫安危。","警露鹤辞侶，吸风蟬抱枝。","彈冠如不问，又到掃门时。"]', '诗', 'shi', '', NULL, '酬別令狐補闕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3112b33-9adf-4261-a6f7-9c3cf7f15a41', '銀河吹笙', '銀河吹笙', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["悵望銀河吹玉笙，樓寒院冷接平明。","重衾幽夢他年斷，別樹羈雌昨夜驚。","月榭故香因雨發，風簾殘燭隔霜清。","不須浪作緱山意，湘瑟秦簫自有情。"]', '["悵望銀河吹玉笙，楼寒院冷接平明。","重衾幽梦他年斷，別樹羈雌昨夜驚。","月榭故香因雨發，风簾殘燭隔霜清。","不須浪作緱山意，湘瑟秦簫自有情。"]', '诗', 'shi', '', NULL, '銀河吹笙 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85bdc827-ec2d-40d6-bc96-75a92744a451', '與同年李定言曲水閑話戲作', '與同年李定言曲水闲話戲作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["海燕參差溝水流，同君身世屬離憂。","相攜花下非秦贅，對泣春天類楚囚。","碧草暗侵穿苑路，珠簾不捲枕江樓。","莫驚五勝埋香骨，地下傷春亦白頭。"]', '["海燕參差溝水流，同君身世屬離憂。","相携花下非秦贅，对泣春天類楚囚。","碧草暗侵穿苑路，珠簾不捲枕江楼。","莫驚五勝埋香骨，地下傷春亦白头。"]', '诗', 'shi', '', NULL, '與同年李定言曲水閑話戲作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926ed9c9-7fab-45a1-b8e8-72971937173d', '彭城公薨後贈杜二十七勝李十七潘二君竝與愚同出故尚書安平公門下', '彭城公薨後贈杜二十七勝李十七潘二君竝與愚同出故尚书安平公门下', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["梁山兖水約從公，兩地參差一旦空。","謝墅庾村相弔後，自今歧路各西東。"]', '["梁山兖水約從公，兩地參差一旦空。","謝墅庾村相弔後，自今歧路各西东。"]', '诗', 'shi', '', NULL, '彭城公薨後贈杜二十七勝李十七潘二君竝與愚同出故尚書安平公門下 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e36705c-24cf-4e35-a9ee-c994edd8c443', '聞歌', '闻歌', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["斂笑凝眸意欲歌，高雲不動碧嵯峨。","銅臺罷望歸何處，玉輦忘還事幾多。","青冢路邊南雁盡，細腰宮裏北人過。","此聲腸斷非今日，香灺燈光奈爾何。"]', '["斂笑凝眸意欲歌，高云不动碧嵯峨。","銅台罷望归何处，玉輦忘還事幾多。","青冢路邊南雁尽，細腰宮裏北人過。","此声腸斷非今日，香灺灯光奈爾何。"]', '诗', 'shi', '', NULL, '聞歌 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b00f413-2151-4371-afc6-27fbd40bba2f', '贈華陽宋真人兼寄清都劉先生', '贈华陽宋真人兼寄清都劉先生', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["淪謫千年別帝宸，至今猶謝蘂珠人。","但驚茅許同仙籍，不道劉盧是世親。","玉撿賜書迷鳳篆，金華歸駕冷龍鱗。","不因杖屨逢周史，徐甲何曾有此身。"]', '["淪謫千年別帝宸，至今猶謝蘂珠人。","但驚茅許同仙籍，不道劉盧是世親。","玉撿賜书迷鳳篆，金华归駕冷龙鱗。","不因杖屨逢周史，徐甲何曾有此身。"]', '诗', 'shi', '', NULL, '贈華陽宋真人兼寄清都劉先生 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e0fed4-bbf2-434e-aee8-f6a82c722c85', '楚宮二首 一', '楚宮二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十二峰前落照微，高唐宮暗坐迷歸。","朝雲暮雨長相接，猶自君王恨見稀。"]', '["十二峰前落照微，高唐宮暗坐迷归。","朝云暮雨长相接，猶自君王恨见稀。"]', '诗', 'shi', '', NULL, '楚宮二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdbf77fd-ed38-490f-a090-ba7040273f83', '楚宮二首 二', '楚宮二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["月姊曾逢下彩蟾，傾城消息隔重簾。","已聞佩響知腰細，更辨絃聲覺指纖。","暮雨自歸山悄悄，秋河不動夜厭厭。","王昌且在牆東住，未必金堂得免嫌。"]', '["月姊曾逢下彩蟾，傾城消息隔重簾。","已闻佩响知腰細，更辨絃声覺指纖。","暮雨自归山悄悄，秋河不动夜厭厭。","王昌且在牆东住，未必金堂得免嫌。"]', '诗', 'shi', '', NULL, '楚宮二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f332ec60-421a-49e0-addd-94ed01d9f3d9', '和友人戲贈二首 一', '和友人戲贈二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東望花樓會不同，西來雙燕信休通。","仙人掌冷三霄露，玉女窗虛五夜風。","翠袖自隨回雪轉，燭房尋類外庭空。","殷勤莫使清香透，牢合金魚鏁桂叢。"]', '["东望花楼會不同，西来雙燕信休通。","仙人掌冷三霄露，玉女窗虛五夜风。","翠袖自隨回雪轉，燭房尋類外庭空。","殷勤莫使清香透，牢合金鱼鏁桂叢。"]', '诗', 'shi', '', NULL, '和友人戲贈二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce27db7e-0077-41a1-9872-f7aecc077d40', '和友人戲贈二首 二', '和友人戲贈二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["迢遰青門有幾關，柳梢樓角見南山。","明珠可貫須爲佩，白璧堪裁且作環。","子夜休歌團扇揜，新正未破剪刀閑。","猿啼鶴怨終年事，未抵熏爐一夕間。"]', '["迢遰青门有幾关，柳梢楼角见南山。","明珠可貫須爲佩，白璧堪裁且作环。","子夜休歌團扇揜，新正未破剪刀闲。","猿啼鹤怨終年事，未抵熏爐一夕间。"]', '诗', 'shi', '', NULL, '和友人戲贈二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66b33383-1aa5-4ec3-8f69-021007fc14ca', '題二首後重有戲贈任秀才', '題二首後重有戲贈任秀才', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一丈紅薔擁翠筠，羅窗不識繞街塵。","峽中尋覓長逢雨，月裏依稀更有人。","虛爲錯刀留遠客，枉緣書札損文鱗。","遙知小閣還斜照，羨殺烏龍臥錦茵。"]', '["一丈紅薔擁翠筠，羅窗不識繞街塵。","峽中尋覓长逢雨，月裏依稀更有人。","虛爲錯刀留远客，枉緣书札損文鱗。","遙知小閣還斜照，羨殺烏龙臥錦茵。"]', '诗', 'shi', '', NULL, '題二首後重有戲贈任秀才 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c802da18-34e9-40bf-ac0d-350c23fa0aeb', '有感二首 一', '有感二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["九服歸元化，三靈叶睿圖。","如何本初輩，自取屈氂誅。","有甚當車泣，因勞下殿趨。","何成奏雲物，直是滅萑苻。","證逮符書密，辭連性命俱。","竟緣尊漢相，不早辨胡雛。","鬼籙分朝部，軍烽照上都。","敢云堪慟哭，未免怨洪爐。"]', '["九服归元化，三靈叶睿圖。","如何本初輩，自取屈氂誅。","有甚當车泣，因勞下殿趨。","何成奏云物，直是滅萑苻。","證逮符书密，辞連性命俱。","竟緣尊漢相，不早辨胡雛。","鬼籙分朝部，軍烽照上都。","敢云堪慟哭，未免怨洪爐。"]', '诗', 'shi', '', NULL, '有感二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73b9375-ef5e-4a4b-9b94-6367a4054385', '有感二首 二', '有感二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["丹陛猶敷奏，彤庭歘戰爭。","臨危對盧植，始悔用龐萌。","御仗收前殿，兵徒劇背城。","蒼黃五色棒，掩遏一陽生。","古有清君側，今非乏老成。","素心雖未易，此舉太無名。","誰瞑銜冤目，寧吞欲絕聲。","近聞開壽讌，不廢用咸英。"]', '["丹陛猶敷奏，彤庭歘戰爭。","臨危对盧植，始悔用龐萌。","御仗收前殿，兵徒劇背城。","蒼黄五色棒，掩遏一陽生。","古有清君側，今非乏老成。","素心雖未易，此舉太無名。","誰瞑銜冤目，寧吞欲絕声。","近闻开壽讌，不廢用咸英。"]', '诗', 'shi', '', NULL, '有感二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06609c06-2c71-4ec5-a1ac-89e76d2c3428', '重有感', '重有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉帳牙旗得上遊，安危須共主君憂。","竇融表已來關右，陶侃軍宜次石頭。","豈有蛟龍愁失水，更無鷹隼與高秋。","晝號夜哭兼幽顯，早晚星關雪涕收。"]', '["玉帳牙旗得上游，安危須共主君憂。","竇融表已来关右，陶侃軍宜次石头。","豈有蛟龙愁失水，更無鷹隼與高秋。","晝號夜哭兼幽显，早晚星关雪涕收。"]', '诗', 'shi', '', NULL, '重有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c068b506-f9b7-48de-a916-1aefb2ace2d2', '壽安公主出降', '壽安公主出降', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["溈水聞貞媛，常山索銳師。","昔憂迷帝力，今分送王姬。","事等和強虜，恩殊睦本枝。","四郊多壘在，此禮恐無時。"]', '["溈水闻貞媛，常山索銳師。","昔憂迷帝力，今分送王姬。","事等和強虜，恩殊睦本枝。","四郊多壘在，此禮恐無时。"]', '诗', 'shi', '', NULL, '壽安公主出降 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314bff28-4e76-4516-a388-3d49878c69f4', '夕陽樓', '夕陽楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["花明柳暗繞天愁，上盡重城更上樓。","欲問孤鴻向何處，不知身世自悠悠。"]', '["花明柳暗繞天愁，上尽重城更上楼。","欲问孤鴻向何处，不知身世自悠悠。"]', '诗', 'shi', '', NULL, '夕陽樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8331c76b-a250-4d07-9c28-b8a456e0974c', '春雨', '春雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["悵臥新春白袷衣，白門寥落意多違。","紅樓隔雨相望冷，珠箔飄燈獨自歸。","遠路應悲春晼晚，殘宵猶得夢依稀。","玉璫緘札何由達，萬里雲羅一雁飛。"]', '["悵臥新春白袷衣，白门寥落意多違。","紅楼隔雨相望冷，珠箔飄灯独自归。","远路應悲春晼晚，殘宵猶得梦依稀。","玉璫緘札何由達，万里云羅一雁飞。"]', '诗', 'shi', '', NULL, '春雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c1800d-add5-46ba-b1a7-2a1efbee7f99', '中元作', '中元作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["絳節飄颻宮國來，中元朝拜上清回。","羊權須得金條脫，溫嶠終虛玉鏡臺。","曾省驚眠聞雨過，不知迷路爲花開。","有娀未抵瀛洲遠，青雀如何鴆鳥媒。"]', '["絳節飄颻宮国来，中元朝拜上清回。","羊權須得金條脫，溫嶠終虛玉镜台。","曾省驚眠闻雨過，不知迷路爲花开。","有娀未抵瀛洲远，青雀如何鴆鸟媒。"]', '诗', 'shi', '', NULL, '中元作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec99484-1412-4b81-9f94-c42d559dfd54', '鴛鴦', '鴛鴦', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雌去雄飛萬里天，雲羅滿眼淚潸然。","不須長結風波願，鎖向金籠始兩全。"]', '["雌去雄飞万里天，云羅满眼泪潸然。","不須长結风波願，鎖向金籠始兩全。"]', '诗', 'shi', '', NULL, '鴛鴦 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1ed72b6-15e2-4576-895d-52a917386936', '楚宮', '楚宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["湘波如淚色漻繆，楚厲迷魂逐恨遙。","楓樹夜猿愁自斷，女蘿山鬼語相邀。","空歸腐敗猶難復，更困腥臊豈易招。","但使故鄉三戶在，綵絲誰惜懼長蛟。"]', '["湘波如泪色漻繆，楚厲迷魂逐恨遙。","楓樹夜猿愁自斷，女蘿山鬼語相邀。","空归腐敗猶难复，更困腥臊豈易招。","但使故乡三戶在，綵絲誰惜懼长蛟。"]', '诗', 'shi', '', NULL, '楚宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682b6406-99cc-4a58-9b4a-6f2163a36178', '妓席暗記送同年獨孤雲之武昌', '妓席暗記送同年独孤云之武昌', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["疊嶂千重呌恨猿，長江萬里洗離魂。","武昌若有山頭石，爲拂蒼苔檢淚痕。"]', '["叠嶂千重呌恨猿，长江万里洗離魂。","武昌若有山头石，爲拂蒼苔檢泪痕。"]', '诗', 'shi', '', NULL, '妓席暗記送同年獨孤雲之武昌 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dfafe07-1bbd-40d0-b70c-a3f7a94fe995', '宿晉昌亭聞驚禽', '宿晉昌亭闻驚禽', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["羇緒鰥鰥夜景侵，高窗不掩見驚禽。","飛來曲渚煙方合，過盡南塘樹更深。","胡馬嘶和榆塞笛，楚猿吟雜橘村砧。","失羣掛木知何限，遠隔天涯共此心。"]', '["羇緒鰥鰥夜景侵，高窗不掩见驚禽。","飞来曲渚煙方合，過尽南塘樹更深。","胡马嘶和榆塞笛，楚猿吟杂橘村砧。","失羣掛木知何限，远隔天涯共此心。"]', '诗', 'shi', '', NULL, '宿晉昌亭聞驚禽 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac26a868-7b6b-4c47-a71b-d718683af67a', '深宮', '深宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["金殿銷香閉綺櫳，玉壺傳點咽銅龍。","狂飆不惜蘿陰薄，清露偏知桂葉濃。","斑竹嶺邊無限淚，景陽宮裏及時鐘。","豈知爲雨爲雲處，只有高唐十二峰。"]', '["金殿銷香閉綺櫳，玉壺傳点咽銅龙。","狂飆不惜蘿陰薄，清露偏知桂葉濃。","斑竹嶺邊無限泪，景陽宮裏及时鐘。","豈知爲雨爲云处，只有高唐十二峰。"]', '诗', 'shi', '', NULL, '深宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3d063c-4403-49de-9e11-9c9be8eda363', '明禪師院酬從兄見寄', '明禪師院酬從兄见寄', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["貞吝嫌茲世，會心馳本原。","人非四禪縛，地絕一塵喧。","霜露欹高木，星河壓故園。","撕遊儻爲勝，九折幸回軒。"]', '["貞吝嫌茲世，會心驰本原。","人非四禪縛，地絕一塵喧。","霜露欹高木，星河壓故园。","撕游儻爲勝，九折幸回軒。"]', '诗', 'shi', '', NULL, '明禪師院酬從兄見寄 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d157abb5-7728-4c43-aa0a-c19b8ac2b0b5', '寄裴衡', '寄裴衡', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["別地蕭條極，如何更獨來。","秋應爲黃葉，雨不厭青苔。","沈約只能瘦，潘仁豈是才。","雜情堪底寄，惟有冷於灰。"]', '["別地蕭條極，如何更独来。","秋應爲黄葉，雨不厭青苔。","沈約只能瘦，潘仁豈是才。","杂情堪底寄，惟有冷於灰。"]', '诗', 'shi', '', NULL, '寄裴衡 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc87ee7a-6346-4d3f-b76e-30bf5b091e66', '即日', '即日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["小苑試春衣，高樓倚暮暉。","夭桃惟是笑，舞蝶不空飛。","赤嶺久無耗，鴻門猶合圍。","幾家緣錦字，含淚坐鴛機。"]', '["小苑試春衣，高楼倚暮暉。","夭桃惟是笑，舞蝶不空飞。","赤嶺久無耗，鴻门猶合圍。","幾家緣錦字，含泪坐鴛機。"]', '诗', 'shi', '', NULL, '即日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8ea85f-aab0-4a42-bfff-339542425d29', '淮陽路', '淮陽路', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["荒村倚廢營，投宿旅魂驚。","斷雁高仍急，寒溪曉更清。","昔年嘗聚盜，此日頗分兵。","猜貳誰先致，三朝事始平。"]', '["荒村倚廢營，投宿旅魂驚。","斷雁高仍急，寒溪晓更清。","昔年嘗聚盜，此日頗分兵。","猜貳誰先致，三朝事始平。"]', '诗', 'shi', '', NULL, '淮陽路 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ff794b-ce5f-43fe-8ba8-9d3f42eafacf', '崇讓宅東亭醉後沔然有作', '崇讓宅东亭醉後沔然有作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["曲岸風雷罷，東亭霽日涼。","新秋仍酒困，幽興暫江鄉。","搖落真何遽，交親或未忘。","一帆彭蠡月，數雁塞門霜。","俗態雖多累，仙標發近狂。","聲名佳句在，身世玉琴張。","萬古山空碧，無人鬢免黃。","驊騮憂老大，鶗鴂妬芬芳。","密竹沉虛籟，孤蓮泊晚香。","如何此幽勝，淹臥劇清漳。"]', '["曲岸风雷罷，东亭霽日涼。","新秋仍酒困，幽兴暫江乡。","搖落真何遽，交親或未忘。","一帆彭蠡月，數雁塞门霜。","俗態雖多累，仙標發近狂。","声名佳句在，身世玉琴張。","万古山空碧，無人鬢免黄。","驊騮憂老大，鶗鴂妬芬芳。","密竹沉虛籟，孤蓮泊晚香。","如何此幽勝，淹臥劇清漳。"]', '诗', 'shi', '', NULL, '崇讓宅東亭醉後沔然有作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe966059-d9e0-41b0-8776-ff745cf877bc', '晚晴', '晚晴', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["深居俯夾城，春去夏猶清。","天意憐幽草，人間重晚晴。","併添高閣迥，微注小窗明。","越鳥巢乾後，歸飛體更輕。"]', '["深居俯夾城，春去夏猶清。","天意怜幽草，人间重晚晴。","併添高閣迥，微注小窗明。","越鸟巢乾後，归飞體更轻。"]', '诗', 'shi', '', NULL, '晚晴 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32525dbe-5358-4fec-8d82-ae7b34119853', '迎寄韓魯州', '迎寄韓魯州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["積雨晚騷騷，相思正鬱陶。","不知人萬里，時有燕雙高。","寇盜纏三輔，莓苔滑百牢。","聖朝推衛霍，歸日動仙曹。"]', '["積雨晚騷騷，相思正鬱陶。","不知人万里，时有燕雙高。","寇盜纏三輔，莓苔滑百牢。","聖朝推衛霍，归日动仙曹。"]', '诗', 'shi', '', NULL, '迎寄韓魯州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa573a4-f08e-4447-a053-f7723607d3e5', '武夷山', '武夷山', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["只得流霞酒一杯，空中簫鼓幾時回。","武夷洞裏生毛竹，老盡曾孫更不來。"]', '["只得流霞酒一杯，空中簫鼓幾时回。","武夷洞裏生毛竹，老尽曾孫更不来。"]', '诗', 'shi', '', NULL, '武夷山 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13076522-b29a-42a4-b49f-ffff7ebb164b', '一片', '一片', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一片瓊英價動天，連城十二昔虛傳。","良工巧費真爲累，楮葉成來不直錢。"]', '["一片瓊英價动天，連城十二昔虛傳。","良工巧費真爲累，楮葉成来不直錢。"]', '诗', 'shi', '', NULL, '一片 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8759c08-8fe1-4c91-ad4c-7ce9603884f6', '寄成都高苗二從事', '寄成都高苗二從事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紅蓮幕下紫棃新，命斷湘南病渴人。","今日問君能寄否，二江風水接天津。"]', '["紅蓮幕下紫棃新，命斷湘南病渴人。","今日问君能寄否，二江风水接天津。"]', '诗', 'shi', '', NULL, '寄成都高苗二從事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('382a6a9a-c67a-4a12-ac97-0003bd0f8c89', '鄭州獻從叔舍人褎', '鄭州獻從叔舍人褎', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蓬島煙霞閬苑鐘，三官箋奏附金龍。","茅君奕世仙曹貴，許掾全家道氣濃。","絳簡尚參黃紙案，丹爐猶用紫泥封。","不知他日華陽洞，許上經樓第幾重。"]', '["蓬島煙霞閬苑鐘，三官箋奏附金龙。","茅君奕世仙曹貴，許掾全家道氣濃。","絳簡尚參黄紙案，丹爐猶用紫泥封。","不知他日华陽洞，許上經楼第幾重。"]', '诗', 'shi', '', NULL, '鄭州獻從叔舍人褎 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4adfa07-0b3d-4434-a8b7-a89634852932', '西南行却寄相送者', '西南行却寄相送者', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["百里陰雲覆雪泥，行人只在雪雲西。","明朝驚破還鄉夢，定是陳倉碧野雞。"]', '["百里陰云覆雪泥，行人只在雪云西。","明朝驚破還乡梦，定是陳倉碧野雞。"]', '诗', 'shi', '', NULL, '西南行却寄相送者 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cffdb3f-f281-4e30-9aa5-2a7ddd22027d', '四皓廟', '四皓廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["羽翼殊勳棄若遺，皇天有運我無時。","廟前便接山門路，不長青松長紫芝。"]', '["羽翼殊勳棄若遺，皇天有運我無时。","廟前便接山门路，不长青松长紫芝。"]', '诗', 'shi', '', NULL, '四皓廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0584bca6-3fb6-43d8-945b-11800654fe0f', '題白石蓮花寄楚公', '題白石蓮花寄楚公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白石蓮花誰所共，六時長捧佛前燈。","空庭苔蘚饒霜露，時夢西山老病僧。","大海龍宮無限地，諸天雁塔幾多層。","漫誇鶖子真羅漢，不會牛車是上乘。"]', '["白石蓮花誰所共，六时长捧佛前灯。","空庭苔蘚饒霜露，时梦西山老病僧。","大海龙宮無限地，諸天雁塔幾多層。","漫誇鶖子真羅漢，不會牛车是上乘。"]', '诗', 'shi', '', NULL, '題白石蓮花寄楚公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2467a6-24a4-4556-847a-13818099dacb', '[安定]城樓', '[安定]城楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["迢遰高城百尺樓，綠楊枝外盡汀洲。","賈生年少虛垂淚，王粲春來更遠遊。","永憶江湖歸白髮，欲回天地入扁舟。","不知腐鼠成滋味，猜意鴛雛竟未休。"]', '["迢遰高城百尺楼，綠楊枝外尽汀洲。","賈生年少虛垂泪，王粲春来更远游。","永憶江湖归白髮，欲回天地入扁舟。","不知腐鼠成滋味，猜意鴛雛竟未休。"]', '诗', 'shi', '', NULL, '[安定]城樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c97c16-3012-4f56-aced-493434184fd6', '隋宮守歲', '隋宮守歲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["消息東郊木帝回，宮中行樂有新梅。","沈香甲煎爲庭燎，玉液瓊蘇作壽杯。","遙望露盤疑是月，遠聞鼉鼓欲驚雷。","昭陽第一傾城客，不踏金蓮不肯來。"]', '["消息东郊木帝回，宮中行乐有新梅。","沈香甲煎爲庭燎，玉液瓊蘇作壽杯。","遙望露盤疑是月，远闻鼉鼓欲驚雷。","昭陽第一傾城客，不踏金蓮不肯来。"]', '诗', 'shi', '', NULL, '隋宮守歲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a258f1-bcce-41a0-bee1-e6e785f30ca7', '利州江潭作', '利州江潭作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["神劒飛來不易銷，碧潭珍重駐蘭橈。","自攜明月移燈疾，欲就行雲散錦遙。","河伯軒窗通貝闕，水宮帷箔卷冰綃。","他時燕脯無人寄，雨滿空城蕙葉雕。"]', '["神劒飞来不易銷，碧潭珍重駐蘭橈。","自携明月移灯疾，欲就行云散錦遙。","河伯軒窗通貝闕，水宮帷箔卷冰綃。","他时燕脯無人寄，雨满空城蕙葉雕。"]', '诗', 'shi', '', NULL, '利州江潭作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('321aa72d-3178-42d4-9b63-be26a0bb3b3e', '即目', '即目', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["地寬樓已迥，人更迥於樓。","細意經春物，傷酲屬暮愁。","望賒殊易斷，恨久欲難收。","大埶真無利，多情豈自由。","空園兼樹廢，敗港擁花流。","書去青楓驛，鴻歸杜若洲。","單棲應分定，辭疾索誰憂。","更替林鵶恨，驚頻去不休。"]', '["地寬楼已迥，人更迥於楼。","細意經春物，傷酲屬暮愁。","望賒殊易斷，恨久欲难收。","大埶真無利，多情豈自由。","空园兼樹廢，敗港擁花流。","书去青楓驛，鴻归杜若洲。","單棲應分定，辞疾索誰憂。","更替林鵶恨，驚頻去不休。"]', '诗', 'shi', '', NULL, '即目 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('290595ea-c887-4b90-aeb7-76eecf3ba58f', '相思', '相思', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["相思樹上合歡枝，紫鳳青鸞共羽儀。","腸斷秦臺吹管客，日西春盡到來遲。"]', '["相思樹上合歡枝，紫鳳青鸾共羽儀。","腸斷秦台吹管客，日西春尽到来遲。"]', '诗', 'shi', '', NULL, '相思 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1df834-6ec8-4338-bb9c-09a923b2943d', '茂陵', '茂陵', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["漢家天馬出蒲梢，苜蓿榴花遍近郊。","內苑只知含鳳觜，屬車無復插雞翹。","玉桃偷得憐方朔，金屋脩成貯阿嬌。","誰料蘇卿老歸國，茂陵松栢雨蕭蕭。"]', '["漢家天马出蒲梢，苜蓿榴花遍近郊。","內苑只知含鳳觜，屬车無复插雞翹。","玉桃偷得怜方朔，金屋脩成貯阿嬌。","誰料蘇卿老归国，茂陵松栢雨蕭蕭。"]', '诗', 'shi', '', NULL, '茂陵 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c26081b2-47fd-4098-a10f-61df2879aec8', '鏡檻', '镜檻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鏡檻芙蓉入，香臺翡翠過。","撥弦驚火鳳，交扇拂天鵝。","隱忍陽城笑，喧傳郢市歌。","仙眉瓊作葉，佛髻鈿爲螺。","五里無因霧，三秋只見河。","月中供藥剩，海上得綃多。","玉集胡沙割，犀留聖水磨。","斜門穿戲蝶，小閣鎖飛蛾。","騎襜侵韉卷，車帷約幰鈋。","傳書兩行雁，取酒一封駞。","橋迥涼風壓，溝橫夕照和。","待烏燕太子，駐馬魏東阿。","想像鋪芳褥，依稀解醉羅。","散時簾隔露，臥後幕生波。","梯穩從攀桂，弓調任射莎。","豈能拋斷夢，聽鼓事朝珂。"]', '["镜檻芙蓉入，香台翡翠過。","撥弦驚火鳳，交扇拂天鵝。","隐忍陽城笑，喧傳郢市歌。","仙眉瓊作葉，佛髻鈿爲螺。","五里無因霧，三秋只见河。","月中供藥剩，海上得綃多。","玉集胡沙割，犀留聖水磨。","斜门穿戲蝶，小閣鎖飞蛾。","騎襜侵韉卷，车帷約幰鈋。","傳书兩行雁，取酒一封駞。","橋迥涼风壓，溝橫夕照和。","待烏燕太子，駐马魏东阿。","想像鋪芳褥，依稀解醉羅。","散时簾隔露，臥後幕生波。","梯穩從攀桂，弓調任射莎。","豈能拋斷梦，听鼓事朝珂。"]', '诗', 'shi', '', NULL, '鏡檻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61bba78-f169-4a11-884c-c70979076412', '送鄭大台文南覲', '送鄭大台文南覲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["黎辟灘聲五月寒，南風無處附平安。","君懷一匹胡威絹，爭拭酬恩淚得乾。"]', '["黎辟灘声五月寒，南风無处附平安。","君懷一匹胡威絹，爭拭酬恩泪得乾。"]', '诗', 'shi', '', NULL, '送鄭大台文南覲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3ec8d9-9b38-4d86-9b23-077176008e7d', '風', '风', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["迥拂來鴻急，斜催別燕高。","已寒休慘淡，更遠尚呼號。","楚色分西塞，夷音接下牢。","歸舟天外有，一爲戒波濤。"]', '["迥拂来鴻急，斜催別燕高。","已寒休慘淡，更远尚呼號。","楚色分西塞，夷音接下牢。","归舟天外有，一爲戒波濤。"]', '诗', 'shi', '', NULL, '風 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24b9a540-7a2c-4dba-8327-ed533a0adbf6', '洞庭魚', '洞庭鱼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["洞庭魚可拾，不假更垂罾。","鬧若雨前蟻，多於秋後蠅。","豈思鱗作簟，仍計腹爲燈。","浩蕩天池路，翱翔欲化鵬。"]', '["洞庭鱼可拾，不假更垂罾。","鬧若雨前蟻，多於秋後蠅。","豈思鱗作簟，仍計腹爲灯。","浩蕩天池路，翱翔欲化鵬。"]', '诗', 'shi', '', NULL, '洞庭魚 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dfd440-d250-4f79-9131-0a9877afe5db', '天涯', '天涯', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["春日在天涯，天涯日又斜。","鶯啼如有淚，爲溼最高花。"]', '["春日在天涯，天涯日又斜。","鶯啼如有泪，爲溼最高花。"]', '诗', 'shi', '', NULL, '天涯 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5fa4a45-19ce-4b9a-9aa6-25a77a94651e', '喜舍弟羲叟及第上禮部魏公', '喜舍弟羲叟及第上禮部魏公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["國以斯文重，公仍內署來。","風標森太華，星象逼中台。","朝滿遷鸎侶，門多吐鳳才。","寧同魯司寇，惟鑄一顏回。"]', '["国以斯文重，公仍內署来。","风標森太华，星象逼中台。","朝满遷鸎侶，门多吐鳳才。","寧同魯司寇，惟鑄一顏回。"]', '诗', 'shi', '', NULL, '喜舍弟羲叟及第上禮部魏公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('441652b5-bc89-4f25-a7e2-e0c8830bbe91', '哀箏', '哀箏', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["延頸全同鶴，柔腸素怯猿。","湘波無限淚，蜀魄有餘冤。","輕幰長無道，哀箏不出門。","何由問香炷，翠幕自黃昏。"]', '["延頸全同鹤，柔腸素怯猿。","湘波無限泪，蜀魄有餘冤。","轻幰长無道，哀箏不出门。","何由问香炷，翠幕自黄昏。"]', '诗', 'shi', '', NULL, '哀箏 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27785d86-ef4c-45b6-b06f-10ef16ab04bc', '自南山北歸經分水嶺', '自南山北归經分水嶺', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["水急愁無地，山深故有雲。","那通極目望，又作斷腸分。","鄭驛來雖及，燕臺哭不聞。","猶餘遺意在，許刻鎮南勳。"]', '["水急愁無地，山深故有云。","那通極目望，又作斷腸分。","鄭驛来雖及，燕台哭不闻。","猶餘遺意在，許刻鎮南勳。"]', '诗', 'shi', '', NULL, '自南山北歸經分水嶺 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a53f7d-75b7-46ba-afb0-7518a6f595b1', '舊頓', '旧頓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東人望幸久咨嗟，四海於今是一家。","猶鎖平時舊行殿，盡無宮戶有宮鴉。"]', '["东人望幸久咨嗟，四海於今是一家。","猶鎖平时旧行殿，尽無宮戶有宮鴉。"]', '诗', 'shi', '', NULL, '舊頓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f963bac2-1690-4563-b26d-0c23a1935f53', '代董秀才却扇', '代董秀才却扇', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["莫將畫扇出帷來，遮掩春山滯上才。","若道團圓似明月，此中須放桂花開。"]', '["莫將畫扇出帷来，遮掩春山滯上才。","若道團圓似明月，此中須放桂花开。"]', '诗', 'shi', '', NULL, '代董秀才却扇 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed66d98b-17ba-4efe-976c-4d8f598c44d1', '有感', '有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["非關宋玉有微辭，却是襄王夢覺遲。","一自高唐賦成後，楚天雲雨盡堪疑。"]', '["非关宋玉有微辞，却是襄王梦覺遲。","一自高唐賦成後，楚天云雨尽堪疑。"]', '诗', 'shi', '', NULL, '有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2238ab-7c28-4e12-a086-43562c51b81f', '驪山有感', '驪山有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["驪岫飛泉泛暖香，九龍呵護玉蓮房。","平明每幸長生殿，不從金輿惟壽王。"]', '["驪岫飞泉泛暖香，九龙呵護玉蓮房。","平明每幸长生殿，不從金輿惟壽王。"]', '诗', 'shi', '', NULL, '驪山有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26219a47-f414-4a7f-a0e8-45f48438f28f', '別智玄法師', '別智玄法師', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雲鬢無端怨別離，十年移易住山期。","東西南北皆垂淚，却是楊朱真本師。"]', '["云鬢無端怨別離，十年移易住山期。","东西南北皆垂泪，却是楊朱真本師。"]', '诗', 'shi', '', NULL, '別智玄法師 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9254f723-ac73-44c0-b6e6-e673b89f4af0', '贈孫綺新及第', '贈孫綺新及第', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["長樂遙聽上苑鐘，綵衣稱慶桂香濃。","陸機始擬誇文賦，不覺雲間有士龍。"]', '["长乐遙听上苑鐘，綵衣稱慶桂香濃。","陸機始擬誇文賦，不覺云间有士龙。"]', '诗', 'shi', '', NULL, '贈孫綺新及第 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058b45cb-6338-49d2-af61-fb3d05980bdc', '代秘書贈弘文館諸校書', '代秘书贈弘文館諸校书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["清切曹司近玉除，比來秋興復何如。","崇文館裏丹霜後，無限紅棃憶校書。"]', '["清切曹司近玉除，比来秋兴复何如。","崇文館裏丹霜後，無限紅棃憶校书。"]', '诗', 'shi', '', NULL, '代秘書贈弘文館諸校書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245493d5-ed57-489e-aa36-45d6947f3cab', '亂石', '亂石', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["虎踞龍蹲縱復橫，星光漸減雨痕生。","不須併礙東西路，哭殺廚頭阮步兵。"]', '["虎踞龙蹲縱复橫，星光漸減雨痕生。","不須併礙东西路，哭殺廚头阮步兵。"]', '诗', 'shi', '', NULL, '亂石 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b72999-28de-457a-a344-dc400d52943f', '日日', '日日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["日日春光鬬日光，山城斜路杏花香。","幾時心緒渾無事，得及游絲百尺長。"]', '["日日春光鬬日光，山城斜路杏花香。","幾时心緒渾無事，得及游絲百尺长。"]', '诗', 'shi', '', NULL, '日日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00479ca-fd1b-4a9e-bd7d-7e471a4e6464', '過楚宮', '過楚宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["巫峽迢迢舊楚宮，至今雲雨暗丹楓。","微生盡戀人間樂，只有襄王憶夢中。"]', '["巫峽迢迢旧楚宮，至今云雨暗丹楓。","微生尽戀人间乐，只有襄王憶梦中。"]', '诗', 'shi', '', NULL, '過楚宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db70485-e8b8-422d-b87f-1c59c536325e', '龍池', '龙池', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["龍池賜酒敞雲屏，羯鼓聲高衆樂停。","夜半宴歸宮漏永，薛王沉醉壽王醒。"]', '["龙池賜酒敞云屏，羯鼓声高衆乐停。","夜半宴归宮漏永，薛王沉醉壽王醒。"]', '诗', 'shi', '', NULL, '龍池 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f1b7a8-b400-46f5-b7d7-2061ace55322', '涙', '涙', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["永巷長年怨綺羅，離情終日思風波。","湘江竹上痕無限，峴首碑前灑幾多。","人去紫臺秋入塞，兵殘楚帳夜聞歌。","朝來灞水橋邊問，未抵青袍送玉珂。"]', '["永巷长年怨綺羅，離情終日思风波。","湘江竹上痕無限，峴首碑前灑幾多。","人去紫台秋入塞，兵殘楚帳夜闻歌。","朝来灞水橋邊问，未抵青袍送玉珂。"]', '诗', 'shi', '', NULL, '涙 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d86129-5463-42d3-9e96-3150f126ccad', '十字水期韋潘侍御同年不至時韋寓居水次故郭汾寧宅', '十字水期韋潘侍御同年不至时韋寓居水次故郭汾寧宅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["伊水濺濺相背流，朱欄畫閣幾人遊。","漆燈夜照真無數，蠟炬晨炊竟未休。","顧我有懷同大夢，期君不至更沉憂。","西園碧樹今誰主，與近高窗臥聽秋。"]', '["伊水濺濺相背流，朱欄畫閣幾人游。","漆灯夜照真無數，蠟炬晨炊竟未休。","顧我有懷同大梦，期君不至更沉憂。","西园碧樹今誰主，與近高窗臥听秋。"]', '诗', 'shi', '', NULL, '十字水期韋潘侍御同年不至時韋寓居水次故郭汾寧宅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1d1587-07a6-452c-9264-3c55e26b173c', '流鸎', '流鸎', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["流鸎飄蕩復參差，渡陌臨流不自持。","巧囀豈能無本意，良辰未必有佳期。","風朝露夜陰晴裏，萬戶千門開閉時。"]', '["流鸎飄蕩复參差，渡陌臨流不自持。","巧囀豈能無本意，良辰未必有佳期。","风朝露夜陰晴裏，万戶千门开閉时。"]', '诗', 'shi', '', NULL, '流鸎 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3df8e68-d875-4db2-a709-c07eb8bae466', '出關宿盤豆館對叢蘆有感', '出关宿盤豆館对叢蘆有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蘆葉梢梢夏景深，郵亭暫欲灑塵襟。","昔年曾是江南客，此日初爲關外心。","思子臺邊風自急，玉孃湖上月應沈。","清聲不遠行人去，一世荒城伴夜砧。"]', '["蘆葉梢梢夏景深，郵亭暫欲灑塵襟。","昔年曾是江南客，此日初爲关外心。","思子台邊风自急，玉孃湖上月應沈。","清声不远行人去，一世荒城伴夜砧。"]', '诗', 'shi', '', NULL, '出關宿盤豆館對叢蘆有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bae5a01-c8c7-4a16-a3d3-89b5fcd0e305', '和韓錄事送宮人入道', '和韓錄事送宮人入道', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["星使追還不自由，雙童捧上綠瓊輈。","九枝燈下朝金殿，三素雲中侍玉樓。","鳳女顛狂成久別，月娥孀獨好同遊。","當時若愛韓公子，埋骨成灰恨未休。"]', '["星使追還不自由，雙童捧上綠瓊輈。","九枝灯下朝金殿，三素云中侍玉楼。","鳳女顛狂成久別，月娥孀独好同游。","當时若愛韓公子，埋骨成灰恨未休。"]', '诗', 'shi', '', NULL, '和韓錄事送宮人入道 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3896840c-3fe8-4548-95b5-7eea3bae363f', '即目', '即目', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["小鼎煎茶面曲池，白鬚道士竹間棋。","何人書破蒲葵扇，記著南塘移樹時。"]', '["小鼎煎茶面曲池，白鬚道士竹间棋。","何人书破蒲葵扇，記著南塘移樹时。"]', '诗', 'shi', '', NULL, '即目 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c621f65-39a2-456c-ab95-6ef8b45e974d', '聖女祠', '聖女祠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["杳藹逢仙跡，蒼茫滯客途。","何年歸碧落，此路向皇都。","消息期青雀，逢迎異紫姑。","腸回楚國夢，心斷漢宮巫。","從騎裁寒竹，行車蔭白榆。","星娥一去後，月姊更來無。","寡鵠迷蒼壑，羇凰怨翠梧。","惟應碧桃下，方朔是狂夫。"]', '["杳藹逢仙跡，蒼茫滯客途。","何年归碧落，此路向皇都。","消息期青雀，逢迎異紫姑。","腸回楚国梦，心斷漢宮巫。","從騎裁寒竹，行车蔭白榆。","星娥一去後，月姊更来無。","寡鵠迷蒼壑，羇凰怨翠梧。","惟應碧桃下，方朔是狂夫。"]', '诗', 'shi', '', NULL, '聖女祠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd56a399-b6d6-41c5-8c89-53fea6235883', '七月二十九日崇讓宅讌作', '七月二十九日崇讓宅讌作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["露如微霰下前池，月過回塘萬竹悲。","浮世本來多聚散，紅蕖何事亦離披。","悠揚歸夢惟燈見，濩落生涯獨酒知。","豈到白頭長只爾，嵩陽松雪有心期。"]', '["露如微霰下前池，月過回塘万竹悲。","浮世本来多聚散，紅蕖何事亦離披。","悠揚归梦惟灯见，濩落生涯独酒知。","豈到白头长只爾，嵩陽松雪有心期。"]', '诗', 'shi', '', NULL, '七月二十九日崇讓宅讌作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcbdf93f-a1a6-4d39-8d39-2f35534cd3a4', '贈從兄閬之', '贈從兄閬之', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["悵望人間萬事違，私書幽夢約忘機。","荻花村裏魚標在，石蘚庭中鹿跡微。","幽徑定攜僧共入，寒塘好與月相依。","城中猘犬憎蘭佩，莫損幽芳久不歸。"]', '["悵望人间万事違，私书幽梦約忘機。","荻花村裏鱼標在，石蘚庭中鹿跡微。","幽徑定携僧共入，寒塘好與月相依。","城中猘犬憎蘭佩，莫損幽芳久不归。"]', '诗', 'shi', '', NULL, '贈從兄閬之 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b46369b-d429-4216-9d01-8c59005107dc', '吳宮', '吳宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["龍檻沈沈水殿清，禁門深揜斷人聲。","吳王宴罷滿宮醉，日暮水漂花出城。"]', '["龙檻沈沈水殿清，禁门深揜斷人声。","吳王宴罷满宮醉，日暮水漂花出城。"]', '诗', 'shi', '', NULL, '吳宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c9c409-9571-4eb8-abd9-91ec6c1ff564', '常娥', '常娥', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雲母屏風燭影深，長河漸落曉星沈。","常娥應悔偷靈藥，碧海青天夜夜心。"]', '["云母屏风燭影深，长河漸落晓星沈。","常娥應悔偷靈藥，碧海青天夜夜心。"]', '诗', 'shi', '', NULL, '常娥 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8df2e0-709b-4e33-b5b2-4f577a9884f7', '殘花', '殘花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["殘花啼露莫留春，尖髪誰非怨別人。","若但掩關勞燭夢，寶釵何日不生塵。"]', '["殘花啼露莫留春，尖髪誰非怨別人。","若但掩关勞燭梦，寶釵何日不生塵。"]', '诗', 'shi', '', NULL, '殘花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da10a8c6-c0e0-47be-8f73-e4358888fd31', '天津西望', '天津西望', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["虜馬崩騰忽一狂，翠華無日到東方。","天津西望腸真斷，滿眼秋波出苑牆。"]', '["虜马崩腾忽一狂，翠华無日到东方。","天津西望腸真斷，满眼秋波出苑牆。"]', '诗', 'shi', '', NULL, '天津西望 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664c13c6-bfb4-4eb0-b477-f3bf50d78646', '西亭', '西亭', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["此夜西亭月正圓，疎簾相伴宿風煙。","梧桐莫更翻清露，孤鶴從來不得眠。"]', '["此夜西亭月正圓，疎簾相伴宿风煙。","梧桐莫更翻清露，孤鹤從来不得眠。"]', '诗', 'shi', '', NULL, '西亭 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8449179c-8f81-4616-9183-02fc1a9fcac5', '憶住一師', '憶住一師', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["無事經年別遠公，帝城鐘曉憶西峰。","爐煙消盡寒燈晦，童子開門雪滿松。"]', '["無事經年別远公，帝城鐘晓憶西峰。","爐煙消尽寒灯晦，童子开门雪满松。"]', '诗', 'shi', '', NULL, '憶住一師 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95cd604d-e7f3-4837-9fd7-08773949bdff', '昨夜', '昨夜', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["不辭鶗鴂妬年芳，但惜流塵暗燭房。","昨夜西池涼露滿，桂花吹斷月中香。"]', '["不辞鶗鴂妬年芳，但惜流塵暗燭房。","昨夜西池涼露满，桂花吹斷月中香。"]', '诗', 'shi', '', NULL, '昨夜 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('318d7db7-d6c7-447f-b7af-b04eb5159332', '海客', '海客', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["海客乘槎上紫氛，星娥罷織一相聞。","只應不憚牽牛妬，聊用支機石贈君。"]', '["海客乘槎上紫氛，星娥罷织一相闻。","只應不憚牽牛妬，聊用支機石贈君。"]', '诗', 'shi', '', NULL, '海客 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd250eca-0b6e-42e2-a18d-1394c45cb365', '初食笋呈座中', '初食笋呈座中', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["嫩籜香苞初出林，於陵論價重如金。","皇都陸海應無數，忍剪凌雲一寸心。"]', '["嫩籜香苞初出林，於陵論價重如金。","皇都陸海應無數，忍剪凌云一寸心。"]', '诗', 'shi', '', NULL, '初食笋呈座中 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b51478e-5f70-4258-aff6-fd117b7222e9', '早起', '早起', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["風露澹清晨，簾間獨起人。","鸎花啼又笑，畢竟是誰春。"]', '["风露澹清晨，簾间独起人。","鸎花啼又笑，畢竟是誰春。"]', '诗', 'shi', '', NULL, '早起 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad1e022-9f0f-4acd-b596-014978311869', '寄蜀客', '寄蜀客', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["君到臨邛問酒壚，近來還有長卿無。","金徽却是無情物，不許文君憶故夫。"]', '["君到臨邛问酒壚，近来還有长卿無。","金徽却是無情物，不許文君憶故夫。"]', '诗', 'shi', '', NULL, '寄蜀客 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e2a812-b830-456f-a8f2-3d68fe0bcacb', '行至金牛驛寄興元渤海尚書', '行至金牛驛寄兴元渤海尚书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["樓上春雲水底天，五雲章色破巴牋。","諸生個個王恭柳，從事人人庾杲蓮。","六曲屏風江雨急，九枝燈檠夜珠圓。","深慙走馬金牛路，驟和陳王白玉篇。"]', '["楼上春云水底天，五云章色破巴牋。","諸生個個王恭柳，從事人人庾杲蓮。","六曲屏风江雨急，九枝灯檠夜珠圓。","深慙走马金牛路，驟和陳王白玉篇。"]', '诗', 'shi', '', NULL, '行至金牛驛寄興元渤海尚書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c434cb-285c-4fd2-b355-aaec2d1e2f0f', '深樹見一顆櫻桃尚在', '深樹见一顆櫻桃尚在', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["高桃留晚實，尋得小庭南。","矮墮綠雲髻，欹危紅玉簪。","惜堪充鳳食，痛已被鸎含。","越鳥誇香荔，齊名亦未甘。"]', '["高桃留晚實，尋得小庭南。","矮墮綠云髻，欹危紅玉簪。","惜堪充鳳食，痛已被鸎含。","越鸟誇香荔，齊名亦未甘。"]', '诗', 'shi', '', NULL, '深樹見一顆櫻桃尚在 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8b6652a-5eed-414e-b49e-be67592f78b0', '細雨', '細雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["帷飄白玉堂，簟卷碧牙牀。","楚女當時意，蕭蕭髪彩涼。"]', '["帷飄白玉堂，簟卷碧牙牀。","楚女當时意，蕭蕭髪彩涼。"]', '诗', 'shi', '', NULL, '細雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbf6f32-dc2e-4ed2-be7a-129231db405b', '歌舞', '歌舞', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["遏雲歌響清，回雪舞腰輕。","只要君流眄，君傾國自傾。"]', '["遏云歌响清，回雪舞腰轻。","只要君流眄，君傾国自傾。"]', '诗', 'shi', '', NULL, '歌舞 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e899f60-7985-4cd4-945d-c5fab85db25f', '海上', '海上', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["石橋東望海連天，徐福空來不得仙。","直遣麻姑與搔背，可能留命待桑田。"]', '["石橋东望海連天，徐福空来不得仙。","直遣麻姑與搔背，可能留命待桑田。"]', '诗', 'shi', '', NULL, '海上 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03acf765-3a7a-4a0e-89ce-b8ee06182b16', '魏侯第東北樓堂郢叔言別聊用書所見成篇', '魏侯第东北楼堂郢叔言別聊用书所见成篇', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["暗樓連夜閣，不擬爲黃昏。","未必斷別淚，何曾妨夢魂。","疑穿花逶迤，漸近火溫黁。","海底翻無水，仙家却有邨。","鎖香金屈[戌]，殢酒玉崑崙。","羽白風交扇，冰清月映盆。","舊歡塵自積，新歲電猶奔。","霞綺空留段，雲峰不帶根。","念君千里舸，江草漏燈痕。"]', '["暗楼連夜閣，不擬爲黄昏。","未必斷別泪，何曾妨梦魂。","疑穿花逶迤，漸近火溫黁。","海底翻無水，仙家却有邨。","鎖香金屈[戌]，殢酒玉崑崙。","羽白风交扇，冰清月映盆。","旧歡塵自積，新歲電猶奔。","霞綺空留段，云峰不带根。","念君千里舸，江草漏灯痕。"]', '诗', 'shi', '', NULL, '魏侯第東北樓堂郢叔言別聊用書所見成篇 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eff5e3c-acbf-4bf7-9971-ed0e3d095211', '白雲夫舊居', '白云夫旧居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["平生誤識白雲夫，再到仙簷憶酒壚。","牆外萬株人絕跡，夕陽惟照欲棲烏。"]', '["平生誤識白云夫，再到仙簷憶酒壚。","牆外万株人絕跡，夕陽惟照欲棲烏。"]', '诗', 'shi', '', NULL, '白雲夫舊居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('428b63b2-9e22-4788-89c5-8bcb9d001fff', '同學彭道士參寥', '同学彭道士參寥', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["莫羨仙家有上真，仙家暫謫亦千春。","月中桂樹高多少，試問西河斫樹人。"]', '["莫羨仙家有上真，仙家暫謫亦千春。","月中桂樹高多少，試问西河斫樹人。"]', '诗', 'shi', '', NULL, '同學彭道士參寥 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26145e3f-2165-4341-83a9-c6721d61d0f8', '到秋', '到秋', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["扇風淅瀝簟流離，萬里南風滯所思。","守到清秋還寂莫，葉丹苔碧閉門時。"]', '["扇风淅瀝簟流離，万里南风滯所思。","守到清秋還寂莫，葉丹苔碧閉门时。"]', '诗', 'shi', '', NULL, '到秋 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a353976b-e90f-48a4-a9a8-972304095488', '華師', '华師', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["孤鶴不睡雲無心，衲衣筇杖來西林。","院門晝鎖回廊靜，秋日當堦柿葉陰。"]', '["孤鹤不睡云無心，衲衣筇杖来西林。","院门晝鎖回廊静，秋日當堦柿葉陰。"]', '诗', 'shi', '', NULL, '華師 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd44f2a6-ef35-45d9-b487-c7c7821d2ed6', '華嶽下題西王母廟', '华嶽下題西王母廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["神仙有分豈關情，八馬虛隨落日行。","莫恨名姬中夜沒，君王猶自不長生。"]', '["神仙有分豈关情，八马虛隨落日行。","莫恨名姬中夜沒，君王猶自不长生。"]', '诗', 'shi', '', NULL, '華嶽下題西王母廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786f65e5-c374-411e-af4a-629176e4ce85', '過華清內廐門', '過华清內廐门', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["華清別館閉黃昏，碧草悠悠內廄門。","自是明時不巡幸，至今青海有龍孫。"]', '["华清別館閉黄昏，碧草悠悠內廄门。","自是明时不巡幸，至今青海有龙孫。"]', '诗', 'shi', '', NULL, '過華清內廐門 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18af06e-709e-4a98-9b49-6b2022daa42b', '樂遊原', '乐游原', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬樹鳴蟬隔岸虹，樂遊原上有西風。","羲和自趁虞泉宿，不放斜陽更向東。"]', '["万樹鳴蟬隔岸虹，乐游原上有西风。","羲和自趁虞泉宿，不放斜陽更向东。"]', '诗', 'shi', '', NULL, '樂遊原 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83e75a1-db6e-4035-a4b6-cab288182996', '贈荷花', '贈荷花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["世間花葉不相倫，花入金盆葉作塵。","惟有綠荷紅菡萏，卷舒開合任天真。","此[花]此葉常相映，翠減紅衰愁殺人。"]', '["世间花葉不相倫，花入金盆葉作塵。","惟有綠荷紅菡萏，卷舒开合任天真。","此[花]此葉常相映，翠減紅衰愁殺人。"]', '诗', 'shi', '', NULL, '贈荷花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50db36bc-3e3d-409d-97ab-3a665b7c4b04', '丹丘', '丹丘', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["青女丁寧結夜霜，羲和辛苦送朝陽。","丹丘萬里無消息，幾對梧桐憶鳳皇。"]', '["青女丁寧結夜霜，羲和辛苦送朝陽。","丹丘万里無消息，幾对梧桐憶鳳皇。"]', '诗', 'shi', '', NULL, '丹丘 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a857e97a-91d5-4ab2-9eed-da392c4a0de0', '房君珊瑚散', '房君珊瑚散', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["不見姮娥影，清秋守月輪。","月中閑杵臼，桂子擣成塵。"]', '["不见姮娥影，清秋守月輪。","月中闲杵臼，桂子擣成塵。"]', '诗', 'shi', '', NULL, '房君珊瑚散 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1e710d-e244-44e0-9897-51886651078d', '小桃園', '小桃园', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["竟日小桃園，休寒亦未暄。","坐鸎當酒重，送客出牆繁。","啼久豔粉薄，舞多香雪翻。","猶憐未圓月，先出照黃昏。"]', '["竟日小桃园，休寒亦未暄。","坐鸎當酒重，送客出牆繁。","啼久豔粉薄，舞多香雪翻。","猶怜未圓月，先出照黄昏。"]', '诗', 'shi', '', NULL, '小桃園 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6d1679-0aa5-4ab0-bbb6-3aeed5df53df', '嘲櫻桃', '嘲櫻桃', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["朱實鳥含盡，青樓人未歸。","南園無限樹，獨自葉如幃。"]', '["朱實鸟含尽，青楼人未归。","南园無限樹，独自葉如幃。"]', '诗', 'shi', '', NULL, '嘲櫻桃 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d6ba8c-0051-49f0-a139-db2d55d492ae', '和張秀才落花有感', '和張秀才落花有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["晴暖感餘芳，紅苞雜絳房。","落時猶自舞，掃後更聞香。","夢罷收羅薦，仙歸勅玉箱。","回腸九回後，猶有剩回腸。"]', '["晴暖感餘芳，紅苞杂絳房。","落时猶自舞，掃後更闻香。","梦罷收羅薦，仙归勅玉箱。","回腸九回後，猶有剩回腸。"]', '诗', 'shi', '', NULL, '和張秀才落花有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298b8e0c-6c88-4042-a594-cca7a6a8ea4c', '代越公房妓嘲徐公主', '代越公房妓嘲徐公主', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["笑啼俱不敢，幾欲是吞聲。","遽遣離琴怨，都由半鏡明。","應防啼與笑，微露淺深情。"]', '["笑啼俱不敢，幾欲是吞声。","遽遣離琴怨，都由半镜明。","應防啼與笑，微露淺深情。"]', '诗', 'shi', '', NULL, '代越公房妓嘲徐公主 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb02dc6-51cb-42a4-be27-d5bc16c0618d', '代貴公主', '代貴公主', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["芳條得意紅，飄落忽西東。","分逐春風去，風回得故叢。","明朝金井露，始看憶春風。"]', '["芳條得意紅，飄落忽西东。","分逐春风去，风回得故叢。","明朝金井露，始看憶春风。"]', '诗', 'shi', '', NULL, '代貴公主 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c3acb2-8f83-4491-b0fb-55f8554e19e0', '鳳', '鳳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬里峰巒歸路迷，未判容彩借山雞。","新春定有將雛樂，阿閣華池兩處棲。"]', '["万里峰巒归路迷，未判容彩借山雞。","新春定有將雛乐，阿閣华池兩处棲。"]', '诗', 'shi', '', NULL, '鳳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef251d4-9925-4007-9e29-e85d06b1f4e1', '昭肅皇帝挽歌辭三首 一', '昭肅皇帝挽歌辞三首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["九縣懷雄武，三靈仰睿文。","周王傳叔父，漢后重神君。","玉律朝驚露，金莖夜切雲。","笳簫淒欲斷，無復詠橫汾。"]', '["九縣懷雄武，三靈仰睿文。","周王傳叔父，漢后重神君。","玉律朝驚露，金莖夜切云。","笳簫淒欲斷，無复詠橫汾。"]', '诗', 'shi', '', NULL, '昭肅皇帝挽歌辭三首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e606d599-66b9-432a-a7a5-f630cad9da53', '昭肅皇帝挽歌辭三首 二', '昭肅皇帝挽歌辞三首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉塞驚宵柝，金橋罷舉烽。","始巢阿閣鳳，旋駕鼎湖龍。","門咽通神鼓，樓凝警夜鐘。","小臣觀吉從，猶誤欲東封。"]', '["玉塞驚宵柝，金橋罷舉烽。","始巢阿閣鳳，旋駕鼎湖龙。","门咽通神鼓，楼凝警夜鐘。","小臣观吉從，猶誤欲东封。"]', '诗', 'shi', '', NULL, '昭肅皇帝挽歌辭三首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ec0faf-e156-4829-aec6-cdf07eab727f', '昭肅皇帝挽歌辭三首 三', '昭肅皇帝挽歌辞三首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["莫驗昭華琯，虛傳甲帳神。","海迷求藥使，雪隔獻桃人。","桂寢青雲斷，松扉白露新。","萬方同象鳥，舉慟滿秋塵。"]', '["莫驗昭华琯，虛傳甲帳神。","海迷求藥使，雪隔獻桃人。","桂寢青云斷，松扉白露新。","万方同象鸟，舉慟满秋塵。"]', '诗', 'shi', '', NULL, '昭肅皇帝挽歌辭三首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e1cc78-213f-4ab0-85e5-6df3d35fddfc', '梓州罷吟寄同舍', '梓州罷吟寄同舍', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["不揀花朝與雪朝，五年從事霍嫖姚。","君緣接座交珠履，我爲分行近翠翹。","楚雨含情皆有託，漳濱臥病竟無憀。","長吟遠下燕臺去，惟有衣香染未銷。"]', '["不揀花朝與雪朝，五年從事霍嫖姚。","君緣接座交珠履，我爲分行近翠翹。","楚雨含情皆有託，漳濱臥病竟無憀。","长吟远下燕台去，惟有衣香染未銷。"]', '诗', 'shi', '', NULL, '梓州罷吟寄同舍 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e006dfd3-40be-40ef-ba3b-552428931ae3', '無題二首 一', '無題二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鳳尾香羅薄幾重，碧文圓頂夜深縫。","扇裁月魄羞難掩，車走雷聲語未通。","曾是寂寥金燼暗，斷無消息石榴紅。"]', '["鳳尾香羅薄幾重，碧文圓頂夜深縫。","扇裁月魄羞难掩，车走雷声語未通。","曾是寂寥金燼暗，斷無消息石榴紅。"]', '诗', 'shi', '', NULL, '無題二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6475dea-1d69-4f0d-b98a-39393f47741e', '無題二首 二', '無題二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["重帷深下莫愁堂，臥後清宵細細長。","神女生涯原是夢，小姑居處本無郎。","風波不信菱枝弱，月露誰教桂葉香。","直道相思了無益，未妨惆悵是清狂。"]', '["重帷深下莫愁堂，臥後清宵細細长。","神女生涯原是梦，小姑居处本無郎。","风波不信菱枝弱，月露誰教桂葉香。","直道相思了無益，未妨惆悵是清狂。"]', '诗', 'shi', '', NULL, '無題二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd24ccbd-680c-470d-afda-63798396e338', '病中早訪招國李十將軍遇挈家遊曲江', '病中早訪招国李十將軍遇挈家游曲江', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十頃平波溢岸清，病來惟夢此中行。","相如未是真消渴，猶放沱江過錦城。"]', '["十頃平波溢岸清，病来惟梦此中行。","相如未是真消渴，猶放沱江過錦城。"]', '诗', 'shi', '', NULL, '病中早訪招國李十將軍遇挈家遊曲江 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3256b035-3b67-4be9-9b73-3997f6ffc646', '昨日', '昨日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昨日紫姑神去也，今朝青鳥使來賒。","未容言語還分散，少得團圓足怨嗟。","二八月輪蟾影破，十三絃柱雁行斜。","平明鐘後更何事，笑倚牆邊梅樹花。"]', '["昨日紫姑神去也，今朝青鸟使来賒。","未容言語還分散，少得團圓足怨嗟。","二八月輪蟾影破，十三絃柱雁行斜。","平明鐘後更何事，笑倚牆邊梅樹花。"]', '诗', 'shi', '', NULL, '昨日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbfab70f-3306-41d6-bacb-3616986f084b', '櫻桃花下', '櫻桃花下', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["流鸎舞蝶兩相欺，不取花芳正結時。","他日未開今日謝，嘉辰長短是參差。"]', '["流鸎舞蝶兩相欺，不取花芳正結时。","他日未开今日謝，嘉辰长短是參差。"]', '诗', 'shi', '', NULL, '櫻桃花下 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810878a7-9824-47f8-a5a6-8d3a28b1474d', '故驛迎弔故桂府常侍有感', '故驛迎弔故桂府常侍有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["饑烏翻樹晚雞啼，泣過秋原沒馬泥。","二紀征南恩與舊，此時丹旐玉山西。"]', '["饑烏翻樹晚雞啼，泣過秋原沒马泥。","二紀征南恩與旧，此时丹旐玉山西。"]', '诗', 'shi', '', NULL, '故驛迎弔故桂府常侍有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39482792-8182-4fb8-a324-bfd89fa460c1', '槿花', '槿花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["風露淒淒秋景繁，可憐榮落在朝昏。","未央宮裏三千女，但保紅顏莫保恩。"]', '["风露淒淒秋景繁，可怜榮落在朝昏。","未央宮裏三千女，但保紅顏莫保恩。"]', '诗', 'shi', '', NULL, '槿花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e053b61f-d055-4484-8a65-7d977480aed5', '暮秋獨遊曲江', '暮秋独游曲江', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["荷葉生時春恨生，荷葉枯時秋恨成。","深知身在情長在，悵望江頭江水聲。"]', '["荷葉生时春恨生，荷葉枯时秋恨成。","深知身在情长在，悵望江头江水声。"]', '诗', 'shi', '', NULL, '暮秋獨遊曲江 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5824360-df41-481d-bf99-b65bb35d8fbf', '任弘農尉獻州刺史乞假還京', '任弘農尉獻州刺史乞假還京', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["黃昏封印點刑徒，愧負荆山入座隅。","却羨卞和雙刖足，一生無復沒階趨。"]', '["黄昏封印点刑徒，愧負荆山入座隅。","却羨卞和雙刖足，一生無复沒階趨。"]', '诗', 'shi', '', NULL, '任弘農尉獻州刺史乞假還京 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42b1b526-1d8e-4373-a990-af650dc8583e', '贈句芒神', '贈句芒神', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["佳期不定春期賒，春物夭閼興咨嗟。","願得句芒索青女，不教容易損年華。"]', '["佳期不定春期賒，春物夭閼兴咨嗟。","願得句芒索青女，不教容易損年华。"]', '诗', 'shi', '', NULL, '贈句芒神 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d395e7b-beda-45b7-9d58-ecb61186c80e', '無愁果有愁曲北齊歌', '無愁果有愁曲北齊歌', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東有青龍西白虎，中含福星包世度。","玉壺渭水笑清潭，鑿天不到牽牛處。","騏驎踏雲天馬獰，牛山撼碎珊瑚聲。","秋娥點滴不成淚，十二玉樓無故釘。","推煙唾月拋千里，十番紅桐一行死。","白楊別屋鬼迷人，空留暗記如蠶紙。","日暮向風牽短絲，血凝血散今誰是。"]', '["东有青龙西白虎，中含福星包世度。","玉壺渭水笑清潭，鑿天不到牽牛处。","騏驎踏云天马獰，牛山撼碎珊瑚声。","秋娥点滴不成泪，十二玉楼無故釘。","推煙唾月拋千里，十番紅桐一行死。","白楊別屋鬼迷人，空留暗記如蠶紙。","日暮向风牽短絲，血凝血散今誰是。"]', '诗', 'shi', '', NULL, '無愁果有愁曲北齊歌 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad19569a-b234-4db2-8c9f-4de50f36872c', '房中曲', '房中曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["薔薇泣幽素，翠帶花錢小。","嬌郎癡若雲，抱日西簾曉。","枕是龍宮石，割得秋波色。","玉簟失柔膚，但見蒙羅碧。","憶得前年春，未語含悲辛。","歸來已不見，錦瑟長於人。","今日澗底松，明日山頭檗。","愁到天池翻，相看不相識。"]', '["薔薇泣幽素，翠带花錢小。","嬌郎癡若云，抱日西簾晓。","枕是龙宮石，割得秋波色。","玉簟失柔膚，但见蒙羅碧。","憶得前年春，未語含悲辛。","归来已不见，錦瑟长於人。","今日澗底松，明日山头檗。","愁到天池翻，相看不相識。"]', '诗', 'shi', '', NULL, '房中曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dffc9e3f-84ce-452d-bdd7-1b1d14860240', '齊梁晴雲', '齊梁晴云', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["緩逐煙波起，如妬柳緜飄。","故臨飛閣度，欲入回陂銷。","縈歌憐畫扇，敞景弄柔條。","更奈天南位，牛渚宿殘宵。"]', '["緩逐煙波起，如妬柳緜飄。","故臨飞閣度，欲入回陂銷。","縈歌怜畫扇，敞景弄柔條。","更奈天南位，牛渚宿殘宵。"]', '诗', 'shi', '', NULL, '齊梁晴雲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610c6aa4-17ed-40ca-a064-2b0c3af7852e', '效徐陵體贈更衣', '效徐陵體贈更衣', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["密帳真珠絡，溫幃翡翠裝。","楚腰知便寵，宮眉正鬬強。","結帶懸梔子，繡領刺鴛鴦。","輕寒衣省夜，金斗熨沉香。"]', '["密帳真珠絡，溫幃翡翠裝。","楚腰知便寵，宮眉正鬬強。","結带懸梔子，繡領刺鴛鴦。","轻寒衣省夜，金斗熨沉香。"]', '诗', 'shi', '', NULL, '效徐陵體贈更衣 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1604b1c0-e643-4bc5-8c4c-c32caee588f0', '又效江南曲', '又效江南曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["郎船安兩槳，儂舸動雙橈。","掃黛開宮額，裁裙約楚腰。","乖期方積思，臨酒欲拌嬌。","莫以採菱唱，欲羨秦臺簫。"]', '["郎船安兩槳，儂舸动雙橈。","掃黛开宮額，裁裙約楚腰。","乖期方積思，臨酒欲拌嬌。","莫以採菱唱，欲羨秦台簫。"]', '诗', 'shi', '', NULL, '又效江南曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8751c49d-ce6d-4c8a-8966-8a6d74f665ba', '月夜重寄宋華陽姊妹', '月夜重寄宋华陽姊妹', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["偷桃竊藥事難兼，十二城中鎖彩蟾。","應共三英同夜賞，玉樓仍是水精簾。"]', '["偷桃竊藥事难兼，十二城中鎖彩蟾。","應共三英同夜賞，玉楼仍是水精簾。"]', '诗', 'shi', '', NULL, '月夜重寄宋華陽姊妹 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242af81a-f8c3-4ca3-ac1e-a91074d26149', '訪人不遇留別館', '訪人不遇留別館', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["卿卿不惜鎖窗春，去作長楸走馬身。","閑倚繡簾吹柳絮，日高深院斷無人。"]', '["卿卿不惜鎖窗春，去作长楸走马身。","闲倚繡簾吹柳絮，日高深院斷無人。"]', '诗', 'shi', '', NULL, '訪人不遇留別館 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc1e5de-bfda-464b-b942-81eaa8e33225', '雨中長樂水館送趙十五滂不及', '雨中长乐水館送趙十五滂不及', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["碧雲東去雨雲西，苑路高高驛路低。","秋水綠蕪終盡分，夫君太騁錦障泥。"]', '["碧云东去雨云西，苑路高高驛路低。","秋水綠蕪終尽分，夫君太騁錦障泥。"]', '诗', 'shi', '', NULL, '雨中長樂水館送趙十五滂不及 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958f0059-3cec-4585-8523-39220cf764d8', '汴上送李郢之蘇州', '汴上送李郢之蘇州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["人高詩苦滯夷門，萬里梁王有舊園。","煙幌自應憐白紵，月樓誰伴詠黃昏。","露桃塗頰依苔井，風柳誇腰住水村。","蘇小小墳今在否，紫蘭香徑與招魂。"]', '["人高诗苦滯夷门，万里梁王有旧园。","煙幌自應怜白紵，月楼誰伴詠黄昏。","露桃塗頰依苔井，风柳誇腰住水村。","蘇小小墳今在否，紫蘭香徑與招魂。"]', '诗', 'shi', '', NULL, '汴上送李郢之蘇州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f90857-83a9-4807-92e2-dd6f73dea0c9', '贈鄭讜處士', '贈鄭讜处士', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["浪跡江湖白髮新，浮雲一片是吾身。","寒歸山觀隨碁局，暖入汀洲逐釣輪。","越桂留烹張翰鱠，蜀薑供煮陸機蓴。","相逢一笑憐疎放，他日扁舟有故人。"]', '["浪跡江湖白髮新，浮云一片是吾身。","寒归山观隨碁局，暖入汀洲逐釣輪。","越桂留烹張翰鱠，蜀薑供煮陸機蓴。","相逢一笑怜疎放，他日扁舟有故人。"]', '诗', 'shi', '', NULL, '贈鄭讜處士 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e8d65f-3b6b-4174-bde9-d262676b4051', '復至裴明府所居', '复至裴明府所居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["伊人卜築自幽深，桂巷杉籬不可尋。","柱上雕蟲對書字，槽中瘦馬仰聽琴。","求之流輩豈易得，行矣關山方獨吟。","賒取松醪一斗酒，與君相伴灑煩襟。"]', '["伊人卜築自幽深，桂巷杉籬不可尋。","柱上雕蟲对书字，槽中瘦马仰听琴。","求之流輩豈易得，行矣关山方独吟。","賒取松醪一斗酒，與君相伴灑煩襟。"]', '诗', 'shi', '', NULL, '復至裴明府所居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1edf0a20-87ff-4ca0-851f-abffeb1972d1', '覽古', '覽古', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["莫恃金湯忽太平，草間霜露古今情。","空糊頳壞真何益，欲舉黃旗竟未成。","長樂瓦飛隨水逝，景陽鐘墮失天明。","回頭一弔箕山客，始信逃堯不爲名。"]', '["莫恃金湯忽太平，草间霜露古今情。","空糊頳壞真何益，欲舉黄旗竟未成。","长乐瓦飞隨水逝，景陽鐘墮失天明。","回头一弔箕山客，始信逃堯不爲名。"]', '诗', 'shi', '', NULL, '覽古 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e0fde6-4599-47d4-865e-cb62e86a28d0', '子初郊墅', '子初郊墅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["看山對酒君思我，聽鼓離城我訪君。","臘雪已添牆下水，齋鐘不散檻前雲。","陰移竹柏濃還淡，歌雜漁樵斷更聞。","亦擬村南買煙舍，子孫相約事耕耘。"]', '["看山对酒君思我，听鼓離城我訪君。","臘雪已添牆下水，斋鐘不散檻前云。","陰移竹柏濃還淡，歌杂漁樵斷更闻。","亦擬村南買煙舍，子孫相約事耕耘。"]', '诗', 'shi', '', NULL, '子初郊墅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fd6525-b368-41f5-b625-c901e00202b3', '漢南書事', '漢南书事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["西師萬衆幾時回，哀痛天書近已裁。","文吏何曾重刀筆，將軍猶自舞輪臺。","幾時拓土成王道，從古窮兵是禍胎。","陛下好生千萬壽，玉樓長御白雲杯。"]', '["西師万衆幾时回，哀痛天书近已裁。","文吏何曾重刀笔，將軍猶自舞輪台。","幾时拓土成王道，從古窮兵是禍胎。","陛下好生千万壽，玉楼长御白云杯。"]', '诗', 'shi', '', NULL, '漢南書事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c93c1b3-316c-4b0f-acf6-5a1613104c32', '當句有對', '當句有对', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["密邇平陽接上蘭，秦樓鴛瓦漢宮盤。","池光不定花光亂，日氣初涵露氣乾。","但覺游蜂饒舞蝶，豈知孤鳳憶離鸞。","三星自轉三山遠，紫府程遙碧落寬。"]', '["密邇平陽接上蘭，秦楼鴛瓦漢宮盤。","池光不定花光亂，日氣初涵露氣乾。","但覺游蜂饒舞蝶，豈知孤鳳憶離鸾。","三星自轉三山远，紫府程遙碧落寬。"]', '诗', 'shi', '', NULL, '當句有對 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7f3b9e-084e-4f78-af9c-68a34ecf54eb', '井絡', '井絡', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["井絡天彭一掌中，漫誇天設劒爲峰。","陣圖東聚燕江石，邊柝西懸雪嶺松。","堪歎故君成杜宇，可能先主是真龍。","將來爲報姦雄輩，莫向金牛訪舊蹤。"]', '["井絡天彭一掌中，漫誇天設劒爲峰。","陣圖东聚燕江石，邊柝西懸雪嶺松。","堪歎故君成杜宇，可能先主是真龙。","將来爲報姦雄輩，莫向金牛訪旧蹤。"]', '诗', 'shi', '', NULL, '井絡 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f915d3-7491-4306-b37a-f6812a654f5e', '寫意', '寫意', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["燕雁迢迢隔上林，高秋望斷正長吟。","人間路有潼江險，天外山惟玉壘深。","日向花間留返照，雲從城上結層陰。","三年已制思鄉淚，更入新年恐不禁。"]', '["燕雁迢迢隔上林，高秋望斷正长吟。","人间路有潼江險，天外山惟玉壘深。","日向花间留返照，云從城上結層陰。","三年已制思乡泪，更入新年恐不禁。"]', '诗', 'shi', '', NULL, '寫意 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d23413-0dbe-4045-9c94-21817b6b4abe', '隨師東', '隨師东', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東征日調萬黃金，幾竭中原買鬬心。","軍令未聞誅馬謖，捷書惟是報孫歆。","但須鸑鷟巢阿閣，豈假鴟鴞在泮林。","可惜前朝玄菟郡，積骸成莽陣雲深。"]', '["东征日調万黄金，幾竭中原買鬬心。","軍令未闻誅马謖，捷书惟是報孫歆。","但須鸑鷟巢阿閣，豈假鴟鴞在泮林。","可惜前朝玄菟郡，積骸成莽陣云深。"]', '诗', 'shi', '', NULL, '隨師東 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a9da1b-1b08-4067-9030-b65756d160dc', '宋玉', '宋玉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["何事荆臺百萬家，惟教宋玉擅才華。","楚辭已不饒唐勒，風賦何曾讓景差。","落日渚宮供觀閣，開年雲夢送煙花。","可憐庾信尋荒徑，猶得三朝託後車。"]', '["何事荆台百万家，惟教宋玉擅才华。","楚辞已不饒唐勒，风賦何曾讓景差。","落日渚宮供观閣，开年云梦送煙花。","可怜庾信尋荒徑，猶得三朝託後车。"]', '诗', 'shi', '', NULL, '宋玉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f08235-2abe-4392-b905-ccc95276fa30', '韓同年新居餞韓西迎家室戲贈', '韓同年新居餞韓西迎家室戲贈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["籍籍征西萬戶侯，新緣貴婿起朱樓。","一名我漫居先甲，千騎君翻在上頭。","雲路招邀迴綵鳳，天河迢遰笑牽牛。","南朝禁臠無人近，瘦盡瓊枝詠四愁。"]', '["籍籍征西万戶侯，新緣貴婿起朱楼。","一名我漫居先甲，千騎君翻在上头。","云路招邀迴綵鳳，天河迢遰笑牽牛。","南朝禁臠無人近，瘦尽瓊枝詠四愁。"]', '诗', 'shi', '', NULL, '韓同年新居餞韓西迎家室戲贈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b25b3c0-1450-42e9-84b0-eb2fbac2bfd8', '奉和太原公送前楊秀才戴兼招楊正字戎', '奉和太原公送前楊秀才戴兼招楊正字戎', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["潼關地接古弘農，萬里高飛雁與鴻。","桂樹一枝當白日，芸香三代繼清風。","仙舟尚惜乖雙美，綵服何由得盡同。","誰憚士龍多笑疾，美髭終類晉司空。"]', '["潼关地接古弘農，万里高飞雁與鴻。","桂樹一枝當白日，芸香三代繼清风。","仙舟尚惜乖雙美，綵服何由得尽同。","誰憚士龙多笑疾，美髭終類晉司空。"]', '诗', 'shi', '', NULL, '奉和太原公送前楊秀才戴兼招楊正字戎 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a65e3b-dc73-4c9f-86c1-6a34050f0039', '池邊', '池邊', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉管葭灰細細吹，流鸎上下燕參差。","日西千遶池邊樹，憶把枯條撼雪時。"]', '["玉管葭灰細細吹，流鸎上下燕參差。","日西千遶池邊樹，憶把枯條撼雪时。"]', '诗', 'shi', '', NULL, '池邊 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02456f60-6ab5-4de8-b9ed-f7519818f0ca', '賈生', '賈生', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["宣室求賢訪逐臣，賈生才調更無倫。","可憐夜半虛前席，不問蒼生問鬼神。"]', '["宣室求賢訪逐臣，賈生才調更無倫。","可怜夜半虛前席，不问蒼生问鬼神。"]', '诗', 'shi', '', NULL, '賈生 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ac253a-605a-455a-8ef1-4db76f263e69', '送王十三校書分司', '送王十三校书分司', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["多少分曹掌秘文，洛陽花雪夢隨君。","定知何遜緣聯句，每到城東憶范雲。"]', '["多少分曹掌秘文，洛陽花雪梦隨君。","定知何遜緣聯句，每到城东憶范云。"]', '诗', 'shi', '', NULL, '送王十三校書分司 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c05119-28d2-4647-a58f-e2dda460d5de', '寄惱韓同年二首 一', '寄惱韓同年二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["簾外辛夷定已開，開時莫放豔陽回。","年華若到經風雨，便是胡僧話劫灰。"]', '["簾外辛夷定已开，开时莫放豔陽回。","年华若到經风雨，便是胡僧話劫灰。"]', '诗', 'shi', '', NULL, '寄惱韓同年二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61659953-ea54-4c63-8b9d-4a19d05a8b30', '寄惱韓同年二首 二', '寄惱韓同年二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["龍山晴雪鳳樓霞，洞裏迷人有幾家。","我爲傷春心自醉，不勞君勸石榴花。"]', '["龙山晴雪鳳楼霞，洞裏迷人有幾家。","我爲傷春心自醉，不勞君勸石榴花。"]', '诗', 'shi', '', NULL, '寄惱韓同年二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f602b4b7-b7cf-4b67-a1a9-12282c8072ad', '謁山', '謁山', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["從來繫日乏長繩，水去雲回恨不勝。","欲就麻姑買滄海，一杯春露冷如冰。"]', '["從来繫日乏长繩，水去云回恨不勝。","欲就麻姑買滄海，一杯春露冷如冰。"]', '诗', 'shi', '', NULL, '謁山 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a49bc13-8939-4d2d-ac7e-f3fb0d24918a', '鈞天', '鈞天', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["上帝鈞天會衆靈，昔人因夢到青冥。","伶倫吹裂孤生竹，却爲知音不得聽。"]', '["上帝鈞天會衆靈，昔人因梦到青冥。","伶倫吹裂孤生竹，却爲知音不得听。"]', '诗', 'shi', '', NULL, '鈞天 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c9f158-8e05-4056-96f5-ca699b182651', '失猿', '失猿', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["祝融南去萬重雲，清嘯無因更一聞。","莫遣碧江通箭道，不教腸斷憶同羣。"]', '["祝融南去万重云，清嘯無因更一闻。","莫遣碧江通箭道，不教腸斷憶同羣。"]', '诗', 'shi', '', NULL, '失猿 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e4b854-a0a3-4b95-a45b-eb2c3b9c7742', '戲題友人壁', '戲題友人壁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["花逕逶迤柳巷深，小闌亭舞囀春禽。","相如解作長門賦，却用文君取酒金。"]', '["花逕逶迤柳巷深，小闌亭舞囀春禽。","相如解作长门賦，却用文君取酒金。"]', '诗', 'shi', '', NULL, '戲題友人壁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4981ac5a-eb1d-4f53-92f2-b917c96e1cb1', '假日', '假日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["素琴絃斷酒缾空，倚坐欹眠日已中。","誰向劉靈天幕內，更當陶令北窻風。"]', '["素琴絃斷酒缾空，倚坐欹眠日已中。","誰向劉靈天幕內，更當陶令北窻风。"]', '诗', 'shi', '', NULL, '假日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc78fe8-b466-4452-9010-0ee4a336c0a7', '寄遠', '寄远', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["姮娥擣藥無時已，玉女投壺未肯休。","何日桑田俱變了，不教伊水向東流。"]', '["姮娥擣藥無时已，玉女投壺未肯休。","何日桑田俱变了，不教伊水向东流。"]', '诗', 'shi', '', NULL, '寄遠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab77712-fd4f-49bb-9448-d3757930dba6', '王昭君', '王昭君', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["毛延壽畫欲通神，忍爲黃金不顧人。","馬上琵琶行萬里，漢宮長有隔生春。"]', '["毛延壽畫欲通神，忍爲黄金不顧人。","马上琵琶行万里，漢宮长有隔生春。"]', '诗', 'shi', '', NULL, '王昭君 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc57ab42-df51-48ce-ae62-ed2d59fe0a23', '舊將軍', '旧將軍', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雲臺高議正紛紛，誰定當時蕩寇勳。","日暮灞陵原上獵，李將軍是故將軍。"]', '["云台高議正紛紛，誰定當时蕩寇勳。","日暮灞陵原上獵，李將軍是故將軍。"]', '诗', 'shi', '', NULL, '舊將軍 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff3c01f2-a898-43e6-9753-c1aef10c9934', '曼倩辭', '曼倩辞', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十八年來墮世間，瑤池歸夢碧桃閑。","如何漢殿穿鍼夜，又向窻中覷阿環。"]', '["十八年来墮世间，瑤池归梦碧桃闲。","如何漢殿穿鍼夜，又向窻中覷阿环。"]', '诗', 'shi', '', NULL, '曼倩辭 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc1659f-763b-4030-a6ab-a24103e457a7', '所居', '所居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["窻下尋書細，溪邊坐石平。","水風醒酒病，霜日曝衣輕。","雞黍隨人設，蒲漁得地生。","前賢無不謂，容易即遺名。"]', '["窻下尋书細，溪邊坐石平。","水风醒酒病，霜日曝衣轻。","雞黍隨人設，蒲漁得地生。","前賢無不謂，容易即遺名。"]', '诗', 'shi', '', NULL, '所居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22dca88-d21b-42ee-966a-d0cad2f1ce16', '高松', '高松', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["高松出衆木，伴我向天涯。","客散初晴候，僧來不語時。","有風傳雅韻，無雪試幽姿。","上藥終相待，他年訪伏龜。"]', '["高松出衆木，伴我向天涯。","客散初晴候，僧来不語时。","有风傳雅韻，無雪試幽姿。","上藥終相待，他年訪伏龟。"]', '诗', 'shi', '', NULL, '高松 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6effad7a-4035-4848-b239-229c70901a62', '訪秋', '訪秋', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["酒薄吹還醒，樓危望已窮。","江臯當落日，帆席見歸風。","煙帶龍潭白，霞分鳥道紅。","殷勤報秋意，只是有丹楓。"]', '["酒薄吹還醒，楼危望已窮。","江臯當落日，帆席见归风。","煙带龙潭白，霞分鸟道紅。","殷勤報秋意，只是有丹楓。"]', '诗', 'shi', '', NULL, '訪秋 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97083d3-0fd7-4cb1-b5bb-cb6260ce07fe', '昭州', '昭州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["桂水春猶早，昭川日正西。","虎當官道鬬，猿上驛樓啼。","繩爛金沙井，松乾乳洞梯。","鄉音殊可駭，仍有醉如泥。"]', '["桂水春猶早，昭川日正西。","虎當官道鬬，猿上驛楼啼。","繩爛金沙井，松乾乳洞梯。","乡音殊可駭，仍有醉如泥。"]', '诗', 'shi', '', NULL, '昭州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e77a57ba-1bb8-48d5-b68c-34b51c175f6e', '哭劉司戶蕡', '哭劉司戶蕡', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["路有論冤謫，言皆在中興。","空聞遷賈誼，不待相孫弘。","江闊惟回首，天高但撫膺。","去年相送地，春雪滿黃陵。"]', '["路有論冤謫，言皆在中兴。","空闻遷賈誼，不待相孫弘。","江闊惟回首，天高但撫膺。","去年相送地，春雪满黄陵。"]', '诗', 'shi', '', NULL, '哭劉司戶蕡 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03916cf-f4b4-4144-9ba8-450f028795ae', '裴明府居止', '裴明府居止', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["愛君茅屋下，向晚水溶溶。","試墨書新竹，張琴和古松。","坐來聞好鳥，歸去度疎鐘。","明日還相見，橋南貰酒醲。"]', '["愛君茅屋下，向晚水溶溶。","試墨书新竹，張琴和古松。","坐来闻好鸟，归去度疎鐘。","明日還相见，橋南貰酒醲。"]', '诗', 'shi', '', NULL, '裴明府居止 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('756653f2-048c-4463-805f-739b73681958', '陸發荆南始至商洛', '陸發荆南始至商洛', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昔去真無奈，今還豈自知。","青辭木奴橘，紫見地仙芝。","四海秋風闊，千嵓暮景遲。","向來憂際會，猶有五湖期。"]', '["昔去真無奈，今還豈自知。","青辞木奴橘，紫见地仙芝。","四海秋风闊，千嵓暮景遲。","向来憂際會，猶有五湖期。"]', '诗', 'shi', '', NULL, '陸發荆南始至商洛 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3757d4-033b-4c69-baf8-8558055d42d4', '陳後宮', '陳後宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玄武開新苑，龍舟讌幸頻。","渚蓮參法駕，沙鳥犯句陳。","壽獻金莖露，歌翻玉樹塵。","夜來江令醉，別詔宿臨春。"]', '["玄武开新苑，龙舟讌幸頻。","渚蓮參法駕，沙鸟犯句陳。","壽獻金莖露，歌翻玉樹塵。","夜来江令醉，別詔宿臨春。"]', '诗', 'shi', '', NULL, '陳後宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83007a15-cc6d-4eb4-8758-0d1a2739ce77', '樂遊原', '乐游原', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["春夢亂不記，春原登已重。","青門弄煙柳，紫閣舞雲松。","拂硯輕冰散，開尊綠酎濃。","無悰託詩遣，吟罷更無悰。"]', '["春梦亂不記，春原登已重。","青门弄煙柳，紫閣舞云松。","拂硯轻冰散，开尊綠酎濃。","無悰託诗遣，吟罷更無悰。"]', '诗', 'shi', '', NULL, '樂遊原 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fef80d2-5d8a-4a3d-b39d-98e162b7a665', '贈子直花下', '贈子直花下', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["池光忽隱牆，花氣亂侵房。","屏緣蝶留粉，窗油蜂印黃。","官書推小吏，侍史從清郎。","竝馬更吟去，尋思有底忙。"]', '["池光忽隐牆，花氣亂侵房。","屏緣蝶留粉，窗油蜂印黄。","官书推小吏，侍史從清郎。","竝马更吟去，尋思有底忙。"]', '诗', 'shi', '', NULL, '贈子直花下 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e443c36-3168-4728-bc0d-f80377f08b9e', '小園獨酌', '小园独酌', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["柳帶誰能結，花房未肯開。","空餘雙蝶舞，竟絕一人來。","半展龍鬚席，輕斟瑪瑙杯。","年年春不定，虛信歲前梅。"]', '["柳带誰能結，花房未肯开。","空餘雙蝶舞，竟絕一人来。","半展龙鬚席，轻斟瑪瑙杯。","年年春不定，虛信歲前梅。"]', '诗', 'shi', '', NULL, '小園獨酌 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c7a332-9a19-4939-a38a-d1f1ffdd9aac', '思歸', '思归', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["固有樓堪依，能無酒可傾。","嶺雲春沮洳，江月夜晴明。","魚亂書何託，猿哀夢易驚。","舊居連上苑，時節正遷鸎。"]', '["固有楼堪依，能無酒可傾。","嶺云春沮洳，江月夜晴明。","鱼亂书何託，猿哀梦易驚。","旧居連上苑，时節正遷鸎。"]', '诗', 'shi', '', NULL, '思歸 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eec5cf1-4b4d-4419-944e-5b33f272d56d', '獻寄舊府開封公', '獻寄旧府开封公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["幕府三年遠，春秋一字襃。","書論秦逐客，賦續楚離騷。","地理南溟闊，天文北極高。","酬恩撫身世，未覺勝鴻毛。"]', '["幕府三年远，春秋一字襃。","书論秦逐客，賦續楚離騷。","地理南溟闊，天文北極高。","酬恩撫身世，未覺勝鴻毛。"]', '诗', 'shi', '', NULL, '獻寄舊府開封公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ffd0e1-e85d-4100-b89f-7b077bfeb497', '向晚', '向晚', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["當風橫去幰，臨水卷空帷。","北土鞦韆罷，南朝祓禊歸。","花情羞脈脈，柳意悵微微。","莫歎佳期晚，佳期自古稀。"]', '["當风橫去幰，臨水卷空帷。","北土鞦韆罷，南朝祓禊归。","花情羞脈脈，柳意悵微微。","莫歎佳期晚，佳期自古稀。"]', '诗', 'shi', '', NULL, '向晚 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4aa20e-0532-4940-beee-163f08a0a8ad', '春游', '春游', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["橋峻斑騅疾，川長白鳥高。","煙輕惟潤柳，風濫欲吹桃。","徙倚三層閣，摩挲七寶刀。","庾郎年最少，青草妬春袍。"]', '["橋峻斑騅疾，川长白鸟高。","煙轻惟潤柳，风濫欲吹桃。","徙倚三層閣，摩挲七寶刀。","庾郎年最少，青草妬春袍。"]', '诗', 'shi', '', NULL, '春游 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e8cbbf6-3284-48fd-a120-27024e74a442', '離席', '離席', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["出宿金尊掩，從公玉帳新。","依依向餘照，遠遠隔芳塵。","細草翻驚雁，殘花伴醉人。","楊朱不用勸，只是更霑巾。"]', '["出宿金尊掩，從公玉帳新。","依依向餘照，远远隔芳塵。","細草翻驚雁，殘花伴醉人。","楊朱不用勸，只是更霑巾。"]', '诗', 'shi', '', NULL, '離席 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7f9be0-8e61-47a2-9078-e3f33966f797', '俳諧', '俳諧', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["短顧何由遂，遲光且莫驚。","鸎能歌子夜，蝶解舞宮城。","柳訝眉雙淺，桃猜粉太輕。","年華有情狀，吾豈怯平生。"]', '["短顧何由遂，遲光且莫驚。","鸎能歌子夜，蝶解舞宮城。","柳訝眉雙淺，桃猜粉太轻。","年华有情狀，吾豈怯平生。"]', '诗', 'shi', '', NULL, '俳諧 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5262b973-36ff-4bae-979c-8e674b705893', '細雨', '細雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蕭灑傍回汀，依微過短亭。","氣涼先動竹，點細未開萍。","稍促高高燕，微疎的的螢。","故園煙草色，仍近五門青。"]', '["蕭灑傍回汀，依微過短亭。","氣涼先动竹，点細未开萍。","稍促高高燕，微疎的的螢。","故园煙草色，仍近五门青。"]', '诗', 'shi', '', NULL, '細雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed4190b-f684-45d2-a1dd-6111536f27b6', '商於新開路', '商於新开路', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["六百商於路，崎嶇古共聞。","蜂房春欲暮，虎穽日初曛。","路向泉間辨，人從樹杪分。","更誰開捷徑，速擬上青雲。"]', '["六百商於路，崎嶇古共闻。","蜂房春欲暮，虎穽日初曛。","路向泉间辨，人從樹杪分。","更誰开捷徑，速擬上青云。"]', '诗', 'shi', '', NULL, '商於新開路 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffc746f8-fc07-4cc8-a60f-a70d2d13cb3f', '題鄭大有隱居', '題鄭大有隐居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["結構何峰是，喧閑此地分。","石梁高瀉月，樵路細侵雲。","堰臥蛟螭室，希夷鳥獸羣。","近知西嶺上，玉管有時聞。"]', '["結構何峰是，喧闲此地分。","石梁高瀉月，樵路細侵云。","堰臥蛟螭室，希夷鸟獸羣。","近知西嶺上，玉管有时闻。"]', '诗', 'shi', '', NULL, '題鄭大有隱居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc6082d1-7aff-4ace-a1bb-602972a4eb03', '夜飲', '夜饮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["卜夜容衰鬢，開筵屬異方。","燭分歌扇淚，雨送酒船香。","江海三年客，乾坤百戰場。","誰能辭酩酊，淹臥劇清漳。"]', '["卜夜容衰鬢，开筵屬異方。","燭分歌扇泪，雨送酒船香。","江海三年客，乾坤百戰場。","誰能辞酩酊，淹臥劇清漳。"]', '诗', 'shi', '', NULL, '夜飲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39cee781-3835-415e-a59d-87eadbc8e5ca', '江上', '江上', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬里風來地，清江北望樓。","雲通梁苑路，月帶楚城秋。","刺字從漫滅，歸途尚阻脩。","前程更煙水，吾道豈淹留。"]', '["万里风来地，清江北望楼。","云通梁苑路，月带楚城秋。","刺字從漫滅，归途尚阻脩。","前程更煙水，吾道豈淹留。"]', '诗', 'shi', '', NULL, '江上 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c6cbc9-753a-4f09-86bf-4fe2d8bb1fee', '涼思', '涼思', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["客去波平檻，蟬休露滿枝。","永懷當此節，倚立自移時。","北斗兼春遠，南陵寓使遲。","天涯占夢數，疑誤有新知。"]', '["客去波平檻，蟬休露满枝。","永懷當此節，倚立自移时。","北斗兼春远，南陵寓使遲。","天涯占梦數，疑誤有新知。"]', '诗', 'shi', '', NULL, '涼思 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96183765-aba5-4f09-b0e8-ffc9233246f4', '鷥鳳', '鷥鳳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["舊鏡鸞何處，衰桐鳳不棲。","金錢饒孔雀，錦段落山雞。","王子調清管，天人降紫泥。","豈無雲路分，相望不應迷。"]', '["旧镜鸾何处，衰桐鳳不棲。","金錢饒孔雀，錦段落山雞。","王子調清管，天人降紫泥。","豈無云路分，相望不應迷。"]', '诗', 'shi', '', NULL, '鷥鳳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68582fdd-45c9-42d9-b969-87b3c5ede889', '李衛公', '李衛公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["絳紗弟子音塵絕，鸞鏡佳人舊會稀。","今日致身歌舞地，木棉花暖鷓鴣飛。"]', '["絳紗弟子音塵絕，鸾镜佳人旧會稀。","今日致身歌舞地，木棉花暖鷓鴣飞。"]', '诗', 'shi', '', NULL, '李衛公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2a64e8-e5e6-4a54-873f-6b5bfe8f5a1d', '韋蟾', '韋蟾', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["謝家離別正淒涼，少傅臨岐賭佩囊。","却憶短亭回首處，夜來煙雨滿池塘。"]', '["謝家離別正淒涼，少傅臨岐賭佩囊。","却憶短亭回首处，夜来煙雨满池塘。"]', '诗', 'shi', '', NULL, '韋蟾 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f90e38-6104-487f-bcc8-8356a1acd3d4', '自貺', '自貺', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["陶令棄官後，仰眠書屋中。","誰將五斗米，擬換北窗風。"]', '["陶令棄官後，仰眠书屋中。","誰將五斗米，擬換北窗风。"]', '诗', 'shi', '', NULL, '自貺 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c038d184-4ba3-4b7c-a849-31d2c1b9030e', '蝶', '蝶', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["孤蝶小徘徊，翩翾粉翅開。","併應傷皎潔，頻近雪中來。"]', '["孤蝶小徘徊，翩翾粉翅开。","併應傷皎潔，頻近雪中来。"]', '诗', 'shi', '', NULL, '蝶 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ec5d09-642e-419e-82d3-5a4b16c75cbf', '夜意', '夜意', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["簾垂幕半卷，枕冷被仍香。","如何爲相憶，魂夢過瀟湘。"]', '["簾垂幕半卷，枕冷被仍香。","如何爲相憶，魂梦過瀟湘。"]', '诗', 'shi', '', NULL, '夜意 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f81bac-a6f7-4c5f-9c15-7277ce8e2cd7', '因書', '因书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["絕徼南通棧，孤城北枕江。","猿聲連月檻，鳥影落天窗。","海石分碁子，郫筒當酒缸。","生歸話辛苦，別夜對凝釭。"]', '["絕徼南通棧，孤城北枕江。","猿声連月檻，鸟影落天窗。","海石分碁子，郫筒當酒缸。","生归話辛苦，別夜对凝釭。"]', '诗', 'shi', '', NULL, '因書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71f2dc7-76b6-49e0-999c-d76dac5ba0aa', '奉寄安國大師兼簡子蒙', '奉寄安国大師兼簡子蒙', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["憶奉蓮花座，兼聞貝葉經。","巖光分蠟屐，澗響入銅缾。","日下徒推鶴，天涯正對螢。","魚山羨曹植，眷屬有文星。"]', '["憶奉蓮花座，兼闻貝葉經。","巖光分蠟屐，澗响入銅缾。","日下徒推鹤，天涯正对螢。","鱼山羨曹植，眷屬有文星。"]', '诗', 'shi', '', NULL, '奉寄安國大師兼簡子蒙 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6afeba-b99d-42d0-b2a7-c1b8fe87adba', '閑遊', '闲游', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["危亭題竹粉，曲沼嗅荷花。","數日同攜酒，平明不在家。","尋幽殊未極，得句總堪誇。","強下西樓去，西樓倚暮霞。"]', '["危亭題竹粉，曲沼嗅荷花。","數日同携酒，平明不在家。","尋幽殊未極，得句總堪誇。","強下西楼去，西楼倚暮霞。"]', '诗', 'shi', '', NULL, '閑遊 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2188f3d7-5dfb-45fd-8e71-1e97b1263cbd', '縣中惱飲席', '縣中惱饮席', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["晚醉題詩贈物華，罷吟還醉忘歸家。","若無江氏五色筆，爭奈河陽一縣花。"]', '["晚醉題诗贈物华，罷吟還醉忘归家。","若無江氏五色笔，爭奈河陽一縣花。"]', '诗', 'shi', '', NULL, '縣中惱飲席 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed639115-f3ed-40fd-8a15-fdb08cd77934', '題李上謩壁', '題李上謩壁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["舊著思玄賦，新編雜擬詩。","江庭猶近別，山舍得幽期。","嫩割周顒韭，肥烹鮑照葵。","飽聞南燭酒，仍及撥醅時。"]', '["旧著思玄賦，新編杂擬诗。","江庭猶近別，山舍得幽期。","嫩割周顒韭，肥烹鲍照葵。","飽闻南燭酒，仍及撥醅时。"]', '诗', 'shi', '', NULL, '題李上謩壁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32f662b-4ce2-4481-a1b7-53cfbd41b2cf', '江村題壁', '江村題壁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["沙岸竹森森，維艄聽越禽。","數家同老壽，一徑自陰深。","喜客嘗留橘，應官說採金。","傾壺真得地，愛日靜霜砧。"]', '["沙岸竹森森，維艄听越禽。","數家同老壽，一徑自陰深。","喜客嘗留橘，應官说採金。","傾壺真得地，愛日静霜砧。"]', '诗', 'shi', '', NULL, '江村題壁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa19603-f858-4fa7-832a-75f76c24e192', '即日', '即日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["桂林聞舊說，曾不異炎方。","山響匡牀語，花飄度臘香。","幾時逢雁足，著處斷猿腸。","獨撫青青桂，臨城憶雪霜。"]', '["桂林闻旧说，曾不異炎方。","山响匡牀語，花飄度臘香。","幾时逢雁足，著处斷猿腸。","独撫青青桂，臨城憶雪霜。"]', '诗', 'shi', '', NULL, '即日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ae6da2-783a-4da3-9012-3cb96ff93fca', '漫成五章 一', '漫成五章 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["沈宋裁辭矜變律，王楊落筆得良朋。","當時自謂宗師妙，今日惟觀對屬能。"]', '["沈宋裁辞矜变律，王楊落笔得良朋。","當时自謂宗師妙，今日惟观对屬能。"]', '诗', 'shi', '', NULL, '漫成五章 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7c473c-01d3-46fc-829c-fd79b864b0bc', '漫成五章 二', '漫成五章 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["李杜操持事略齊，三才萬象共端倪。","集仙殿與金鑾殿，可是蒼蠅惑曙雞。"]', '["李杜操持事略齊，三才万象共端倪。","集仙殿與金鑾殿，可是蒼蠅惑曙雞。"]', '诗', 'shi', '', NULL, '漫成五章 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735c36c7-50b7-4d55-b77f-54cf2bffd19a', '漫成五章 三', '漫成五章 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["生兒古有孫征虜，嫁女今無王右軍。","借問琴書終一世，何如旗蓋仰三分。"]', '["生兒古有孫征虜，嫁女今無王右軍。","借问琴书終一世，何如旗蓋仰三分。"]', '诗', 'shi', '', NULL, '漫成五章 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ab34de-208b-42bd-8432-116a9fcc28a6', '漫成五章 四', '漫成五章 四', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["代北偏師銜使節，關中裨將建行臺。","不妨常日饒輕薄，且喜臨戎用草萊。"]', '["代北偏師銜使節，关中裨將建行台。","不妨常日饒轻薄，且喜臨戎用草萊。"]', '诗', 'shi', '', NULL, '漫成五章 四 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea82e0c2-3af3-48a9-a08a-2012a4772101', '漫成五章 五', '漫成五章 五', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["郭令素心非黷武，韓公本意在和戎。","兩都耆舊偏垂淚，臨老中原見朔風。"]', '["郭令素心非黷武，韓公本意在和戎。","兩都耆旧偏垂泪，臨老中原见朔风。"]', '诗', 'shi', '', NULL, '漫成五章 五 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de91c17f-6db9-48c8-a6e3-db4e499803af', '射魚曲', '射鱼曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["思牢弩箭磨青石，繡額蠻渠三虎力。","尋潮背日伺泅鱗，貝闕夜移鯨失色。","纖纖粉簳馨香餌，綠鴨回塘養龍水。","含冰漢語遠於天，何由回作金盤死。"]', '["思牢弩箭磨青石，繡額蠻渠三虎力。","尋潮背日伺泅鱗，貝闕夜移鯨失色。","纖纖粉簳馨香餌，綠鴨回塘養龙水。","含冰漢語远於天，何由回作金盤死。"]', '诗', 'shi', '', NULL, '射魚曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a696d8-ae23-42b2-ad56-0af657c1176e', '日高', '日高', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鍍鐶故錦縻輕拖，玉𥫽不動便門鎖。","水精眠夢是何人，欄藥日高紅髲𩭝。","飛香上雲春訴天，雲梯十二門九關。","輕身滅影何可望，粉蛾帖死屏風上。"]', '["鍍鐶故錦縻轻拖，玉𥫽不动便门鎖。","水精眠梦是何人，欄藥日高紅髲𩭝。","飞香上云春訴天，云梯十二门九关。","轻身滅影何可望，粉蛾帖死屏风上。"]', '诗', 'shi', '', NULL, '日高 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0839ea23-580d-43fd-bc24-ca9e752d0e8e', '宮中曲', '宮中曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["雲母濾宮月，夜夜白於水。","賺得羊車來，低扇遮黃子。","水精不覺冷，自刻鴛鴦翅。","蠶縷茜香濃，正朝纏左臂。","巴牋兩三幅，滿寫承恩字。","欲得識青天，昨夜蒼龍是。"]', '["云母濾宮月，夜夜白於水。","賺得羊车来，低扇遮黄子。","水精不覺冷，自刻鴛鴦翅。","蠶縷茜香濃，正朝纏左臂。","巴牋兩三幅，满寫承恩字。","欲得識青天，昨夜蒼龙是。"]', '诗', 'shi', '', NULL, '宮中曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5139878e-bd5a-4aa3-9333-00b1ce9f4cc4', '海上謠', '海上謠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["桂水寒於江，玉兔秋冷咽。","海底覓仙人，香桃如瘦骨。","紫鸞不肯舞，滿翅蓬山雪。","借得龍堂寬，曉出揲雲髪。","劉郎舊香炷，立見茂陵樹。","雲孫帖帖臥秋煙，上元細字如蠶眠。"]', '["桂水寒於江，玉兔秋冷咽。","海底覓仙人，香桃如瘦骨。","紫鸾不肯舞，满翅蓬山雪。","借得龙堂寬，晓出揲云髪。","劉郎旧香炷，立见茂陵樹。","云孫帖帖臥秋煙，上元細字如蠶眠。"]', '诗', 'shi', '', NULL, '海上謠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8dd56f-f879-4962-8bc2-e8a8b5660174', '李夫人三首 一', '李夫人三首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一帶不結心，兩股方安髻。","慙愧白茅人，月沒教星替。"]', '["一带不結心，兩股方安髻。","慙愧白茅人，月沒教星替。"]', '诗', 'shi', '', NULL, '李夫人三首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f9bb0d-5622-482c-b165-11fd6e89d3a0', '李夫人三首 二', '李夫人三首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["剩結茱萸枝，多擘秋蓮的。","獨自有波光，綵囊盛不得。"]', '["剩結茱萸枝，多擘秋蓮的。","独自有波光，綵囊盛不得。"]', '诗', 'shi', '', NULL, '李夫人三首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65344e34-9b98-44cb-9ad9-bb92010a52e2', '李夫人三首 三', '李夫人三首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蠻絲繫條脫，妍眼和香屑。","壽宮不惜鑄南人，柔腸早被秋眸割。","清澄有餘幽素香，鰥魚渴鳳真珠房。","不知瘦骨類冰井，更許夜簾通曉霜。","土花漠漠雲茫茫，黃河欲盡天蒼蒼。"]', '["蠻絲繫條脫，妍眼和香屑。","壽宮不惜鑄南人，柔腸早被秋眸割。","清澄有餘幽素香，鰥鱼渴鳳真珠房。","不知瘦骨類冰井，更許夜簾通晓霜。","土花漠漠云茫茫，黄河欲尽天蒼蒼。"]', '诗', 'shi', '', NULL, '李夫人三首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91d4049-4d11-4b38-891c-888b3aa592ce', '景陽宮井雙桐', '景陽宮井雙桐', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["秋港菱花乾，玉盤明月蝕。","血滲兩枯心，情多去未得。","徒經白門伴，不見丹山客。","未待刻作人，愁多有魂魄。","誰將玉盤與，不死翻相誤。","天更闊於江，孫枝覓郎主。","昔妬隣宮槐，道類雙眉歛。","今日繁紅櫻，拋人占長簟。","翠襦不禁綻，留淚啼天眼。","寒灰劫盡問方知，石羊不去誰相絆。"]', '["秋港菱花乾，玉盤明月蝕。","血滲兩枯心，情多去未得。","徒經白门伴，不见丹山客。","未待刻作人，愁多有魂魄。","誰將玉盤與，不死翻相誤。","天更闊於江，孫枝覓郎主。","昔妬隣宮槐，道類雙眉歛。","今日繁紅櫻，拋人占长簟。","翠襦不禁綻，留泪啼天眼。","寒灰劫尽问方知，石羊不去誰相絆。"]', '诗', 'shi', '', NULL, '景陽宮井雙桐 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8991ff-00c0-47b6-b1d1-1bd0e61ad1a0', '秋日晚思', '秋日晚思', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["桐槿日零落，雨餘方寂寥。","枕寒莊蝶去，窻冷胤螢銷。","取適琴將酒，忘名牧與樵。","平生有遊舊，一一在煙霄。"]', '["桐槿日零落，雨餘方寂寥。","枕寒莊蝶去，窻冷胤螢銷。","取適琴將酒，忘名牧與樵。","平生有游旧，一一在煙霄。"]', '诗', 'shi', '', NULL, '秋日晚思 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40fe3139-61c4-4a96-8206-f879f613a694', '春宵自遣', '春宵自遣', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["地勝遺塵事，身閑念歲華。","晚晴風過竹，深夜月當花。","石亂知泉咽，苔荒任逕斜。","陶然恃琴酒，忘却在山家。"]', '["地勝遺塵事，身闲念歲华。","晚晴风過竹，深夜月當花。","石亂知泉咽，苔荒任逕斜。","陶然恃琴酒，忘却在山家。"]', '诗', 'shi', '', NULL, '春宵自遣 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b71e7a7-5444-4112-87d1-26510d74961d', '七夕偶題', '七夕偶題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["寶婺搖珠珮，常娥照玉輪。","靈歸天上匹，巧遺世間人。","花果香千戶，笙竽濫四隣。","明朝曬犢鼻，方信阮家貧。"]', '["寶婺搖珠珮，常娥照玉輪。","靈归天上匹，巧遺世间人。","花果香千戶，笙竽濫四隣。","明朝曬犢鼻，方信阮家貧。"]', '诗', 'shi', '', NULL, '七夕偶題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24c0447-4f15-4fff-9025-caca400fa139', '靈仙閣晚眺寄鄆州韋評事', '靈仙閣晚眺寄鄆州韋評事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["愚公方住谷，仁者本依山。","共誓林泉志，胡爲尊俎間。","華蓮開菡萏，荆玉刻孱顏。","爽氣臨周道，嵐光入漢關。","滿壺徒蟻泛，高閣已苔斑。","想就安車召，寧期負矢還。","潘遊全璧散，郭去半舟閑。","定笑幽人跡，鴻軒不可攀。"]', '["愚公方住谷，仁者本依山。","共誓林泉志，胡爲尊俎间。","华蓮开菡萏，荆玉刻孱顏。","爽氣臨周道，嵐光入漢关。","满壺徒蟻泛，高閣已苔斑。","想就安车召，寧期負矢還。","潘游全璧散，郭去半舟闲。","定笑幽人跡，鴻軒不可攀。"]', '诗', 'shi', '', NULL, '靈仙閣晚眺寄鄆州韋評事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4350eb92-339b-49e8-b8a3-8a13b6cb4813', '幽居冬暮', '幽居冬暮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["羽翼摧殘日，郊園寂寞時。","曉雞驚樹雪，寒騖守冰池。","急景忽云暮，頹年浸已衰。","如何匡國分，不與夙心期。"]', '["羽翼摧殘日，郊园寂寞时。","晓雞驚樹雪，寒騖守冰池。","急景忽云暮，頹年浸已衰。","如何匡国分，不與夙心期。"]', '诗', 'shi', '', NULL, '幽居冬暮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcaa691-8161-4893-9958-ce4d224e6be3', '過姚孝子廬偶書', '過姚孝子廬偶书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["拱木臨周道，荒廬積古苔。","魚因感姜出，鶴爲弔陶來。","兩鬢蓬常亂，雙眸血不開。","聖朝敦爾類，非獨路人哀。"]', '["拱木臨周道，荒廬積古苔。","鱼因感姜出，鹤爲弔陶来。","兩鬢蓬常亂，雙眸血不开。","聖朝敦爾類，非独路人哀。"]', '诗', 'shi', '', NULL, '過姚孝子廬偶書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('702e1b2f-5792-4007-9be4-4d121e740061', '賦得月照冰池', '賦得月照冰池', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["皓月方離海，堅冰正滿池。","金波雙激射，璧彩兩參差。","影占徘徊處，光含的皪時。","高低連素色，上下接清規。","顧兔飛難定，潛魚躍未期。","鵲驚俱欲遶，狐聽始無疑。","似鏡將盈手，如霜恐透肌。","獨憐遊翫意，達曉不知疲。"]', '["皓月方離海，堅冰正满池。","金波雙激射，璧彩兩參差。","影占徘徊处，光含的皪时。","高低連素色，上下接清規。","顧兔飞难定，潛鱼躍未期。","鵲驚俱欲遶，狐听始無疑。","似镜將盈手，如霜恐透肌。","独怜游翫意，達晓不知疲。"]', '诗', 'shi', '', NULL, '賦得月照冰池 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f35b78-9101-4e37-9c51-0ab68d3fcf52', '永樂縣所居一草一木無非自栽今春悉已芳茂因書即事一章', '永乐縣所居一草一木無非自栽今春悉已芳茂因书即事一章', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["手種悲陳事，心期玩物華。","柳飛彭澤雪，桃散武陵霞。","枳嫩棲鸞葉，桐香待鳳花。","綬藤縈弱蔓，袍草展新芽。","學植功雖倍，成蹊跡尚賒。","芳年誰共玩，終老邵平瓜。"]', '["手種悲陳事，心期玩物华。","柳飞彭澤雪，桃散武陵霞。","枳嫩棲鸾葉，桐香待鳳花。","綬藤縈弱蔓，袍草展新芽。","学植功雖倍，成蹊跡尚賒。","芳年誰共玩，終老邵平瓜。"]', '诗', 'shi', '', NULL, '永樂縣所居一草一木無非自栽今春悉已芳茂因書即事一章 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee868dd-0971-493e-8cbb-97d8e8e2b68d', '南潭上亭讌集以疾後至因而抒情', '南潭上亭讌集以疾後至因而抒情', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["馬卿聊應召，謝傅已登山。","歌發百花外，樂調深竹間。","鷁舟縈遠岸，魚鑰啓重關。","鸎蝶如相引，煙蘿不暇攀。","佳人啓玉齒，上客頷朱顏。","肯念沈痾士，俱期倒載還。"]', '["马卿聊應召，謝傅已登山。","歌發百花外，乐調深竹间。","鷁舟縈远岸，鱼鑰啓重关。","鸎蝶如相引，煙蘿不暇攀。","佳人啓玉齒，上客頷朱顏。","肯念沈痾士，俱期倒載還。"]', '诗', 'shi', '', NULL, '南潭上亭讌集以疾後至因而抒情 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0a5d7c-e6f1-4ef7-847d-42367dd4ffe1', '寒食行次冷泉驛', '寒食行次冷泉驛', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["驛途仍近節，旅宿倍思家。","獨夜三更月，空庭一樹花。","介山當驛秀，汾水遶關斜。","自怯春寒苦，那堪禁火賒。"]', '["驛途仍近節，旅宿倍思家。","独夜三更月，空庭一樹花。","介山當驛秀，汾水遶关斜。","自怯春寒苦，那堪禁火賒。"]', '诗', 'shi', '', NULL, '寒食行次冷泉驛 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b17e56c-b0f1-4293-a390-aa8ccdce82c3', '寄華嶽孫逸人', '寄华嶽孫逸人', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["靈嶽幾千仞，老松逾百尋。","攀崖仍躡壁，噉葉復眠陰。","海上呼三島，齋中戲五禽。","唯應逢阮籍，長嘯作鸞音。"]', '["靈嶽幾千仞，老松逾百尋。","攀崖仍躡壁，噉葉复眠陰。","海上呼三島，斋中戲五禽。","唯應逢阮籍，长嘯作鸾音。"]', '诗', 'shi', '', NULL, '寄華嶽孫逸人 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8520c586-9556-4c55-8a11-56d416380376', '戲題贈稷山驛吏王全', '戲題贈稷山驛吏王全', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["絳臺驛吏老風塵，耽酒成仙幾十春。","過客不勞詢甲子，惟書亥字與時人。"]', '["絳台驛吏老风塵，耽酒成仙幾十春。","過客不勞詢甲子，惟书亥字與时人。"]', '诗', 'shi', '', NULL, '戲題贈稷山驛吏王全 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de6a9e6-0185-4bc4-8bc5-3c38a3b9def4', '和韋潘前輩七月十二日夜泊池州城下先寄上李使君', '和韋潘前輩七月十二日夜泊池州城下先寄上李使君', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["桂含爽氣三秋首，蓂吐中旬二葉新。","正是澄江如練處，玄暉應喜見詩人。"]', '["桂含爽氣三秋首，蓂吐中旬二葉新。","正是澄江如練处，玄暉應喜见诗人。"]', '诗', 'shi', '', NULL, '和韋潘前輩七月十二日夜泊池州城下先寄上李使君 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50295b5c-22d9-4c04-975c-7edddb177542', '花下醉', '花下醉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["尋芳不覺醉流霞，倚樹沈眠日已斜。","客散酒醒深夜後，更持紅燭賞殘花。"]', '["尋芳不覺醉流霞，倚樹沈眠日已斜。","客散酒醒深夜後，更持紅燭賞殘花。"]', '诗', 'shi', '', NULL, '花下醉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc7d768-3364-466a-9db3-ccec07df57a1', '所居永樂縣久旱縣宰祈禱得雨因賦詩', '所居永乐縣久旱縣宰祈禱得雨因賦诗', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["甘膏滴滴是精誠，晝夜如絲一尺盈。","祗怪閭閻喧鼓吹，邑人同報束長生。"]', '["甘膏滴滴是精誠，晝夜如絲一尺盈。","祗怪閭閻喧鼓吹，邑人同報束长生。"]', '诗', 'shi', '', NULL, '所居永樂縣久旱縣宰祈禱得雨因賦詩 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af6841a-3381-426d-a811-4e1d133ba180', '正月十五夜聞京有燈恨不得觀', '正月十五夜闻京有灯恨不得观', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["月色燈光滿帝都，香車寶輦隘通衢。","身閑不睹中興盛，羞逐鄉人賽紫姑。"]', '["月色灯光满帝都，香车寶輦隘通衢。","身闲不睹中兴盛，羞逐乡人賽紫姑。"]', '诗', 'shi', '', NULL, '正月十五夜聞京有燈恨不得觀 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbce96ac-c994-4521-b108-5e25b931320a', '贈趙協律晳', '贈趙協律晳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["俱識孫公與謝公，二年歌哭處還同。","已叨鄒馬聲華末，更共劉盧族望通南省恩深賓館在，東山事往妓樓空。","不堪歲暮相逢地，我欲西征君又東。"]', '["俱識孫公與謝公，二年歌哭处還同。","已叨鄒马声华末，更共劉盧族望通南省恩深賓館在，东山事往妓楼空。","不堪歲暮相逢地，我欲西征君又东。"]', '诗', 'shi', '', NULL, '贈趙協律晳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9c820c-a58e-49f3-b2be-e614fc15850a', '搖落', '搖落', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["搖落傷年日，羈留念遠心。","水亭吟斷續，月幌夢飛沈。","古木含風久，疎螢怯露深。","人閑始遙夜，地迥更清砧。","結愛曾傷晚，端憂復至今。","未諳滄海路，何處玉山岑？","灘激黃牛暮，雲屯白帝陰。","遙知霑灑意，不減欲分襟。"]', '["搖落傷年日，羈留念远心。","水亭吟斷續，月幌梦飞沈。","古木含风久，疎螢怯露深。","人闲始遙夜，地迥更清砧。","結愛曾傷晚，端憂复至今。","未諳滄海路，何处玉山岑？","灘激黄牛暮，云屯白帝陰。","遙知霑灑意，不減欲分襟。"]', '诗', 'shi', '', NULL, '搖落 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9386eae5-ef3b-4c42-8602-bee9a75a8018', '滯雨', '滯雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["滯雨長安夜，殘燈獨客愁。","故鄉雲水地，歸夢不宜秋。"]', '["滯雨长安夜，殘灯独客愁。","故乡云水地，归梦不宜秋。"]', '诗', 'shi', '', NULL, '滯雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('264265bc-10cc-4084-b6e7-e6d93ddfecbd', '偶題二首 一', '偶題二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["小亭閒眠微醉消，山榴海栢枝相交。","水文簟上琥珀枕，傍有墮釵雙翠翹。"]', '["小亭閒眠微醉消，山榴海栢枝相交。","水文簟上琥珀枕，傍有墮釵雙翠翹。"]', '诗', 'shi', '', NULL, '偶題二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26560253-1755-422e-861b-0a1d456bf79a', '偶題二首 二', '偶題二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["清月依微香露輕，曲房小院多逢迎。","春叢定見饒棲鳥，飲罷莫持紅燭行。"]', '["清月依微香露轻，曲房小院多逢迎。","春叢定见饒棲鸟，饮罷莫持紅燭行。"]', '诗', 'shi', '', NULL, '偶題二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00135042-ba1a-4926-9c73-f227f3a7793e', '月', '月', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["過水穿樓觸處明，藏人帶樹遠含清。","初生欲缺虛惆悵，未必圓時即有情。"]', '["過水穿楼觸处明，藏人带樹远含清。","初生欲缺虛惆悵，未必圓时即有情。"]', '诗', 'shi', '', NULL, '月 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b3540f-48bf-4116-a9aa-73b368ac9521', '夜冷', '夜冷', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["樹遶池寬月影多，村砧塢笛隔風蘿。","西亭翠被餘香薄，一夜將愁向敗荷。"]', '["樹遶池寬月影多，村砧塢笛隔风蘿。","西亭翠被餘香薄，一夜將愁向敗荷。"]', '诗', 'shi', '', NULL, '夜冷 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d3fa77-35a3-407f-9205-1d372b8c98ca', '正月崇讓宅', '正月崇讓宅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["密鎖重關掩綠苔，廊深閣迥此徘徊。","先知風起月含暈，尚自露寒花未開。","蝙拂簾旌終展轉，鼠翻牕網小驚猜。","背燈獨共餘香語，不覺猶歌起夜來。"]', '["密鎖重关掩綠苔，廊深閣迥此徘徊。","先知风起月含暈，尚自露寒花未开。","蝙拂簾旌終展轉，鼠翻牕網小驚猜。","背灯独共餘香語，不覺猶歌起夜来。"]', '诗', 'shi', '', NULL, '正月崇讓宅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0944b7-f3a5-415f-b728-4c275497cc98', '城外', '城外', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["露寒風定不無情，臨水當山又隔城。","未必明時勝蜯蛤，一生長共月虧盈。"]', '["露寒风定不無情，臨水當山又隔城。","未必明时勝蜯蛤，一生长共月虧盈。"]', '诗', 'shi', '', NULL, '城外 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4914cff-9362-498b-9602-c802daf5c870', '撰彭陽公誌文畢有感', '撰彭陽公誌文畢有感', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["延陵留表墓，峴首送沈碑。","敢伐不加點，猶當無愧辭。","百生終莫報，九死諒難追。","待得生金後，川原亦幾移。"]', '["延陵留表墓，峴首送沈碑。","敢伐不加点，猶當無愧辞。","百生終莫報，九死諒难追。","待得生金後，川原亦幾移。"]', '诗', 'shi', '', NULL, '撰彭陽公誌文畢有感 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9380d4f6-e19d-4ff1-8309-07f4ede69f7c', '北青蘿', '北青蘿', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["殘陽西入崦，茅屋訪孤僧。","落葉人何在，寒雲路幾層。","獨敲初夜磬，閑倚一枝藤。","世界微塵裏，吾寧愛與憎。"]', '["殘陽西入崦，茅屋訪孤僧。","落葉人何在，寒云路幾層。","独敲初夜磬，闲倚一枝藤。","世界微塵裏，吾寧愛與憎。"]', '诗', 'shi', '', NULL, '北青蘿 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c43285a-df09-4b32-b5d7-9af713978aa6', '戲贈張書記', '戲贈張书記', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["別館君孤枕，空庭我閉關。","池光不受月，野氣欲沈山。","星漢秋方會，關河夢幾還。","危絃傷遠道，明鏡惜紅顏。","古木含風久，平蕪盡日閑。","心知兩愁絕，不段若尋環。"]', '["別館君孤枕，空庭我閉关。","池光不受月，野氣欲沈山。","星漢秋方會，关河梦幾還。","危絃傷远道，明镜惜紅顏。","古木含风久，平蕪尽日闲。","心知兩愁絕，不段若尋环。"]', '诗', 'shi', '', NULL, '戲贈張書記 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88687ce-4a49-4ee7-a7e7-201caaa98247', '幽人', '幽人', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["丹竈三年火，蒼崖萬歲藤。","樵歸說逢虎，碁罷正留僧。","星斗同秦分，人煙接漢陵。","東流清渭苦，不盡照衰興。"]', '["丹竈三年火，蒼崖万歲藤。","樵归说逢虎，碁罷正留僧。","星斗同秦分，人煙接漢陵。","东流清渭苦，不尽照衰兴。"]', '诗', 'shi', '', NULL, '幽人 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f746e9-c478-46ee-9338-3b7cdb5ae376', '念遠', '念远', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["日月淹秦甸，江湖動越吟。","蒼桐應露下，白閣自雲深。","皎皎非鸞扇，翹翹失鳳簪。","牀空鄂君被，杵冷女媭砧。","北思驚沙雁，南情屬海禽。","關山已搖落，天地共登臨。"]', '["日月淹秦甸，江湖动越吟。","蒼桐應露下，白閣自云深。","皎皎非鸾扇，翹翹失鳳簪。","牀空鄂君被，杵冷女媭砧。","北思驚沙雁，南情屬海禽。","关山已搖落，天地共登臨。"]', '诗', 'shi', '', NULL, '念遠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8fc044-5100-49fd-86fb-9431f821777e', '過故崔兖海宅與崔明秀才話舊因寄僚杜趙李三掾', '過故崔兖海宅與崔明秀才話旧因寄僚杜趙李三掾', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["絳帳恩如昨，烏衣事莫尋。","諸生空會葬，舊掾已華簪。","共入留賓驛，俱分市駿金。","莫憑無鬼論，終負託孤心。"]', '["絳帳恩如昨，烏衣事莫尋。","諸生空會葬，旧掾已华簪。","共入留賓驛，俱分市駿金。","莫憑無鬼論，終負託孤心。"]', '诗', 'shi', '', NULL, '過故崔兖海宅與崔明秀才話舊因寄僚杜趙李三掾 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fd89cf-a133-42f4-80eb-d4997dc36bec', '微雨', '微雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["初隨林靄動，稍共夜涼分。","窗迥侵燈冷，庭虛近水聞。"]', '["初隨林靄动，稍共夜涼分。","窗迥侵灯冷，庭虛近水闻。"]', '诗', 'shi', '', NULL, '微雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b7a173-d330-4add-afc4-013c9d480ed9', '南山趙行軍新詩盛稱游讌之洽因寄一絶', '南山趙行軍新诗盛稱游讌之洽因寄一絶', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蓮幕遙臨黑水津，橐鞬無事但尋春。","梁王司馬非孫武，且免宮中斬美人。"]', '["蓮幕遙臨黑水津，橐鞬無事但尋春。","梁王司马非孫武，且免宮中斬美人。"]', '诗', 'shi', '', NULL, '南山趙行軍新詩盛稱游讌之洽因寄一絶 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60a62f9-bae4-45fe-b7f1-899b0acf8515', '曲江', '曲江', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["望斷平時翠輦過，空聞子夜鬼悲歌。","金輿不返傾城色，玉殿猶分下苑波。","死憶華亭聞唳鶴，老憂王室泣銅駝。","天荒地變心難折，若比陽春意未多。"]', '["望斷平时翠輦過，空闻子夜鬼悲歌。","金輿不返傾城色，玉殿猶分下苑波。","死憶华亭闻唳鹤，老憂王室泣銅駝。","天荒地变心难折，若比陽春意未多。"]', '诗', 'shi', '', NULL, '曲江 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e00bc2-52d6-49bd-91c2-6ef990f4e0b7', '景陽井', '景陽井', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["景陽宮井剩堪悲，不盡龍鸞誓死期。","腸斷吳王宮外水，濁泥猶得葬西施。"]', '["景陽宮井剩堪悲，不尽龙鸾誓死期。","腸斷吳王宮外水，濁泥猶得葬西施。"]', '诗', 'shi', '', NULL, '景陽井 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9a793a-a116-4a9c-b0b9-8a4f38b7ae89', '故番禺侯以贓罪致不辜事覺母者他日過其門', '故番禺侯以贓罪致不辜事覺母者他日過其门', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["飲鴆非君命，茲身亦厚亡。","江陵從種橘，交廣合投香。","不見千金子，空馀數仞墻。","殺人須顯戮，誰舉漢三章。"]', '["饮鴆非君命，茲身亦厚亡。","江陵從種橘，交廣合投香。","不见千金子，空馀數仞墻。","殺人須显戮，誰舉漢三章。"]', '诗', 'shi', '', NULL, '故番禺侯以贓罪致不辜事覺母者他日過其門 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63431f77-0404-4f65-8bf0-a193ece18c35', '詠雲', '詠云', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["捧月三更斷，藏星七夕明。","纔聞飄迥路，旋見隔重城。","潭暮隨龍起，河秋壓雁聲。","只應惟宋玉，知是楚神名。"]', '["捧月三更斷，藏星七夕明。","纔闻飄迥路，旋见隔重城。","潭暮隨龙起，河秋壓雁声。","只應惟宋玉，知是楚神名。"]', '诗', 'shi', '', NULL, '詠雲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea9f624-70b1-4bc6-b2d6-00c20bed2e79', '夜出西溪', '夜出西溪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東府憂春盡，西溪許日曛。","月澄新漲水，星見欲銷雲。","柳好休傷別，松高莫出羣。","軍書雖倚馬，猶未當能文。"]', '["东府憂春尽，西溪許日曛。","月澄新漲水，星见欲銷云。","柳好休傷別，松高莫出羣。","軍书雖倚马，猶未當能文。"]', '诗', 'shi', '', NULL, '夜出西溪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c8050c-4122-4c2a-a6a6-e66d096331a2', '效長吉', '效长吉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["長長漢殿眉，窄窄楚宮衣。","鏡好鸞空舞，簾疎燕誤飛。","君王不可問，昨夜約黃歸。"]', '["长长漢殿眉，窄窄楚宮衣。","镜好鸾空舞，簾疎燕誤飞。","君王不可问，昨夜約黄归。"]', '诗', 'shi', '', NULL, '效長吉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97baa2c2-02e7-4320-8ccc-9509c669d752', '柳', '柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["江南江北雪初消，漠漠輕黃惹嫩條。","灞岸已攀行客手，楚宮先騁舞姬腰。","清明帶雨臨官道，晚日含風拂野橋。","如線如絲正牽恨，王孫歸路一何遙。"]', '["江南江北雪初消，漠漠轻黄惹嫩條。","灞岸已攀行客手，楚宮先騁舞姬腰。","清明带雨臨官道，晚日含风拂野橋。","如線如絲正牽恨，王孫归路一何遙。"]', '诗', 'shi', '', NULL, '柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98dadbcc-7409-42f1-b504-2b2775282f4c', '九月於東逢雪', '九月於东逢雪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["舉家忻共報，秋雪墮前峰。","嶺外他年憶，於東此日逢。","粒輕還自亂，花薄未成重。","豈是驚離鬢，應來洗病容。"]', '["舉家忻共報，秋雪墮前峰。","嶺外他年憶，於东此日逢。","粒轻還自亂，花薄未成重。","豈是驚離鬢，應来洗病容。"]', '诗', 'shi', '', NULL, '九月於東逢雪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99969894-e7ad-4687-a9ee-c02c7c232a48', '四皓廟', '四皓廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["本爲留侯慕赤松，漢庭方識紫芝翁。","蕭何只解追韓信，豈得虛當第一功。"]', '["本爲留侯慕赤松，漢庭方識紫芝翁。","蕭何只解追韓信，豈得虛當第一功。"]', '诗', 'shi', '', NULL, '四皓廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acb0fbd-d02d-4370-97d3-17edc3d0258a', '送阿龜歸華', '送阿龟归华', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["草堂歸意背煙蘿，黃綬垂腰不奈何。","因汝華陽求藥物，碧松根下茯苓多。"]', '["草堂归意背煙蘿，黄綬垂腰不奈何。","因汝华陽求藥物，碧松根下茯苓多。"]', '诗', 'shi', '', NULL, '送阿龜歸華 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f45be7b3-9455-4769-a066-3bb421d02a19', '九日', '九日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["曾共山翁把酒時，霜天白菊繞堦墀。","十年泉下無人問，九日樽前有所思。","不學漢臣栽苜蓿，空教楚客詠江籬。","郎君官貴施行馬，東閣無因再得窺。"]', '["曾共山翁把酒时，霜天白菊繞堦墀。","十年泉下無人问，九日樽前有所思。","不学漢臣栽苜蓿，空教楚客詠江籬。","郎君官貴施行马，东閣無因再得窺。"]', '诗', 'shi', '', NULL, '九日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ecc68c-d75d-4256-bc26-6ebb2e184bc5', '僧院牡丹', '僧院牡丹', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["薄葉風才倚，枝輕霧不勝。","開先如避客，色淺爲依僧。","粉壁正蕩水，緗幃初卷燈。","傾城惟待笑，要裂幾多繒。"]', '["薄葉风才倚，枝轻霧不勝。","开先如避客，色淺爲依僧。","粉壁正蕩水，緗幃初卷灯。","傾城惟待笑，要裂幾多繒。"]', '诗', 'shi', '', NULL, '僧院牡丹 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2b6768-c929-4910-97f5-7472cc1217e1', '贈司勳杜十三員外', '贈司勳杜十三員外', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["杜牧司勳字牧之，清秋一首杜秋詩。","前身應是梁江總，名總還曾字總持。","心鐵已從干鏌利，鬢絲休嘆雪霜垂。","漢江遠弔西江水，羊[祜]韋丹盡有碑。"]', '["杜牧司勳字牧之，清秋一首杜秋诗。","前身應是梁江總，名總還曾字總持。","心鐵已從干鏌利，鬢絲休嘆雪霜垂。","漢江远弔西江水，羊[祜]韋丹尽有碑。"]', '诗', 'shi', '', NULL, '贈司勳杜十三員外 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751c67f2-a4a5-462e-877f-87d9e9e47578', '高花', '高花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["花將人共笑，籬外露繁枝。","宋玉臨江宅，墻低不礙窺。"]', '["花將人共笑，籬外露繁枝。","宋玉臨江宅，墻低不礙窺。"]', '诗', 'shi', '', NULL, '高花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5831e658-329d-4fd8-b624-c4af883a121f', '嘲桃', '嘲桃', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["無賴夭桃面，平明露井東。","春風爲開了，却擬笑春風。"]', '["無賴夭桃面，平明露井东。","春风爲开了，却擬笑春风。"]', '诗', 'shi', '', NULL, '嘲桃 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d87f3b-c668-427b-9e56-0e1022911d52', '送豐都李尉', '送豐都李尉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬古商於地，憑君泣路岐。","固難尋綺季，可得信張儀。","雨氣燕先覺，葉陰蟬遽知。","望鄉尤忌晚，山晚更參差。"]', '["万古商於地，憑君泣路岐。","固难尋綺季，可得信張儀。","雨氣燕先覺，葉陰蟬遽知。","望乡尤忌晚，山晚更參差。"]', '诗', 'shi', '', NULL, '送豐都李尉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df747d5-e7b2-4651-ab44-f0f7db3534c1', '天平公座中呈令狐令公時蔡京在坐京曾爲僧徒故有第五句', '天平公座中呈令狐令公时蔡京在坐京曾爲僧徒故有第五句', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["罷執霓旌上醮壇，慢粧嬌樹水晶盤。","更深欲訴蛾眉歛，衣薄臨醒玉豔寒。","白足禪僧思敗道，青袍御史擬休官。","雖然同是將軍客，不敢公然子細看。"]', '["罷執霓旌上醮壇，慢粧嬌樹水晶盤。","更深欲訴蛾眉歛，衣薄臨醒玉豔寒。","白足禪僧思敗道，青袍御史擬休官。","雖然同是將軍客，不敢公然子細看。"]', '诗', 'shi', '', NULL, '天平公座中呈令狐令公時蔡京在坐京曾爲僧徒故有第五句 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475063b5-bd8e-48a9-9ea2-d0226e53d7de', '江上憶嚴五廣休', '江上憶嚴五廣休', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["征南幕下帶長刀，夢筆深藏五色毫。","逢著澄江不敢詠，鎮西留與謝功曹。"]', '["征南幕下带长刀，梦笔深藏五色毫。","逢著澄江不敢詠，鎮西留與謝功曹。"]', '诗', 'shi', '', NULL, '江上憶嚴五廣休 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d6818a-3178-4ec6-ba53-74234ea48421', '餞席重送從叔余之梓州', '餞席重送從叔余之梓州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["莫歎萬重山，君還我未還。","武關猶悵望，何況百牢關。"]', '["莫歎万重山，君還我未還。","武关猶悵望，何況百牢关。"]', '诗', 'shi', '', NULL, '餞席重送從叔余之梓州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c35c7ff-bf5d-4dca-9e32-da58c5713909', '訪隱', '訪隐', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["路到層峰斷，門依老樹開。","月從平楚轉，泉自上方來。","薤白羅朝饌，松黃暖夜盃。","相留笑孫綽，空解賦天台。"]', '["路到層峰斷，门依老樹开。","月從平楚轉，泉自上方来。","薤白羅朝饌，松黄暖夜盃。","相留笑孫綽，空解賦天台。"]', '诗', 'shi', '', NULL, '訪隱 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8f26bd-589f-462d-b1a4-e9f30f19dbcb', '寓興', '寓兴', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["薄宦仍多病，從知竟遠遊。","談諧叨客禮，休澣接冥搜。","樹好頻移榻，雲奇不下樓。","豈關無景物，自是有鄉愁。"]', '["薄宦仍多病，從知竟远游。","談諧叨客禮，休澣接冥搜。","樹好頻移榻，云奇不下楼。","豈关無景物，自是有乡愁。"]', '诗', 'shi', '', NULL, '寓興 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f484765-e036-4f66-b3e8-0e36f0fec4cb', '東南', '东南', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["東南一望日中烏，欲遂羲和去得無。","且向秦樓棠樹下，每朝先覓照羅敷。"]', '["东南一望日中烏，欲遂羲和去得無。","且向秦楼棠樹下，每朝先覓照羅敷。"]', '诗', 'shi', '', NULL, '東南 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c66868-b96c-4213-a1ae-a3311faa0982', '歸來', '归来', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["舊隱無何別，歸來始更悲。","難尋白道士，不見惠禪師。","草徑蟲鳴急，沙渠水下遲。","却將波浪眼，清曉對紅梨。"]', '["旧隐無何別，归来始更悲。","难尋白道士，不见惠禪師。","草徑蟲鳴急，沙渠水下遲。","却將波浪眼，清晓对紅梨。"]', '诗', 'shi', '', NULL, '歸來 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18a5269-8281-44f4-9fc6-b0f097b580aa', '子直晉昌李花', '子直晉昌李花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["吳館何時熨，秦臺幾夜熏。","綃輕誰解卷，香異自先聞。","月裏誰無姊，雲中亦有君。","罇前見飄蕩，愁極客襟分。"]', '["吳館何时熨，秦台幾夜熏。","綃轻誰解卷，香異自先闻。","月裏誰無姊，云中亦有君。","罇前见飄蕩，愁極客襟分。"]', '诗', 'shi', '', NULL, '子直晉昌李花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1338b8-d89b-4f96-8346-0ce769e21d60', '河清與趙氏昆季讌集得擬杜工部', '河清與趙氏昆季讌集得擬杜工部', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["勝概殊江右，佳名逼渭川。","虹收青嶂雨，鳥沒夕陽天。","客鬢行如此，滄波坐渺然。","此中真得地，漂蕩釣魚船。"]', '["勝概殊江右，佳名逼渭川。","虹收青嶂雨，鸟沒夕陽天。","客鬢行如此，滄波坐渺然。","此中真得地，漂蕩釣鱼船。"]', '诗', 'shi', '', NULL, '河清與趙氏昆季讌集得擬杜工部 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29fe9b6a-61b4-4cff-8e65-0ea9e1649922', '寓目', '寓目', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["園桂懸心碧，池蓮飫眼紅。","此生真遠客，幾別即衰翁。","小幌風煙入，高窻霧雨通。","新知他日好，錦瑟傍朱櫳。"]', '["园桂懸心碧，池蓮飫眼紅。","此生真远客，幾別即衰翁。","小幌风煙入，高窻霧雨通。","新知他日好，錦瑟傍朱櫳。"]', '诗', 'shi', '', NULL, '寓目 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e36123-9411-4b9b-b9e3-4bc20f6c5b38', '題道靜院院在中條山故王顏中丞所置虢州刺史捨官居此今寫真存焉', '題道静院院在中條山故王顏中丞所置虢州刺史捨官居此今寫真存焉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紫府丹成化鶴羣，青松手植變龍文。","壺中別有仙家日，嶺上猶多隱士雲。","獨坐遺芳成故事，褰帷舊貌似元君。","自憐築室靈山下，徒望朝嵐與夕曛。"]', '["紫府丹成化鹤羣，青松手植变龙文。","壺中別有仙家日，嶺上猶多隐士云。","独坐遺芳成故事，褰帷旧貌似元君。","自怜築室靈山下，徒望朝嵐與夕曛。"]', '诗', 'shi', '', NULL, '題道靜院院在中條山故王顏中丞所置虢州刺史捨官居此今寫真存焉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9521af5a-4b92-4e5f-af33-ba71807dbce2', '賦得桃李無言', '賦得桃李無言', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["夭桃花正發，穠李蘂方繁。","應候非爭豔，成蹊不在言。","靜中霞暗吐，香處雪潛翻。","得意搖風態，含情泣露痕。","芬芳光上苑，寂默委中園。","赤白徒自許，幽芳誰與論。"]', '["夭桃花正發，穠李蘂方繁。","應候非爭豔，成蹊不在言。","静中霞暗吐，香处雪潛翻。","得意搖风態，含情泣露痕。","芬芳光上苑，寂默委中园。","赤白徒自許，幽芳誰與論。"]', '诗', 'shi', '', NULL, '賦得桃李無言 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('404b5d91-26be-4868-b366-3c9562917770', '登霍山驛樓', '登霍山驛楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["廟列前峰迥，樓開四望窮。","嶺鼷嵐色外，陂雁夕陽中。","弱柳千條露，衰荷一面風。","壺關有狂孽，速繼老生功。"]', '["廟列前峰迥，楼开四望窮。","嶺鼷嵐色外，陂雁夕陽中。","弱柳千條露，衰荷一面风。","壺关有狂孽，速繼老生功。"]', '诗', 'shi', '', NULL, '登霍山驛樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcc8af5-e5cd-4dbd-9db4-bdfdb585826b', '寄和水部馬郎中題興德驛時昭義已平', '寄和水部马郎中題兴德驛时昭義已平', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["仙郎倦去心，鄭驛暫登臨。","水色瀟湘闊，沙程朔漠深。","鷁舟時往復，鷗鳥恣浮沈。","更想逢歸馬，悠悠嶽樹陰。"]', '["仙郎倦去心，鄭驛暫登臨。","水色瀟湘闊，沙程朔漠深。","鷁舟时往复，鷗鸟恣浮沈。","更想逢归马，悠悠嶽樹陰。"]', '诗', 'shi', '', NULL, '寄和水部馬郎中題興德驛時昭義已平 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c37368-602f-4ccf-9de5-36e827acaac0', '題小松', '題小松', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["憐君孤秀植庭中，細葉輕陰滿座風。","桃李盛時雖寂寞，雪霜多後始青蔥。","一年幾變枯榮事，百尺方資柱石功。","爲謝西園車馬客，定悲搖落盡成空。"]', '["怜君孤秀植庭中，細葉轻陰满座风。","桃李盛时雖寂寞，雪霜多後始青蔥。","一年幾变枯榮事，百尺方資柱石功。","爲謝西园车马客，定悲搖落尽成空。"]', '诗', 'shi', '', NULL, '題小松 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc1fb1be-6613-49e7-b3ff-45b6c5cb6590', '行次昭應縣道上送戶部李郎中充昭義攻討', '行次昭應縣道上送戶部李郎中充昭義攻討', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["將軍大斾埽狂童，詔選名賢贊武功。","暫逐虎牙臨故絳，遠含雞舌過新豐。","魚遊沸鼎知無日，鳥覆危巢豈待風。","早勒勳庸燕石上，佇光綸綍漢廷中。"]', '["將軍大斾埽狂童，詔選名賢贊武功。","暫逐虎牙臨故絳，远含雞舌過新豐。","鱼游沸鼎知無日，鸟覆危巢豈待风。","早勒勳庸燕石上，佇光綸綍漢廷中。"]', '诗', 'shi', '', NULL, '行次昭應縣道上送戶部李郎中充昭義攻討 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf6916b-e466-4acb-a755-e2bfc3a3f6d7', '水齋', '水斋', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["多病欣依有道邦，南塘宴起想秋江。","卷簾飛燕還拂水，開戶暗蟲猶打窗。","更閱前題已披卷，仍斟昨夜未開缸。","誰人爲報故交道，莫惜鯉雨時一雙。"]', '["多病欣依有道邦，南塘宴起想秋江。","卷簾飞燕還拂水，开戶暗蟲猶打窗。","更閱前題已披卷，仍斟昨夜未开缸。","誰人爲報故交道，莫惜鯉雨时一雙。"]', '诗', 'shi', '', NULL, '水齋 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee77a97-c70a-4d90-bd7b-01f0f8cf9998', '奉同諸公題河中任中丞新創河亭四韻之作', '奉同諸公題河中任中丞新創河亭四韻之作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬里誰能訪十洲，新亭雲搆壓中流。","河鮫縱翫難爲室，海蜃遙驚恥化樓。","左右名山窮遠目，東西大道鎖輕舟。","獨留巧思傳千古，長與蒲津作勝遊。"]', '["万里誰能訪十洲，新亭云搆壓中流。","河鮫縱翫难爲室，海蜃遙驚恥化楼。","左右名山窮远目，东西大道鎖轻舟。","独留巧思傳千古，长與蒲津作勝游。"]', '诗', 'shi', '', NULL, '奉同諸公題河中任中丞新創河亭四韻之作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62cc5ffe-6f2f-43a8-9cf3-562c4607039d', '過故府中武威公交城舊莊感事', '過故府中武威公交城旧莊感事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["信陵亭館接郊畿，幽象遙通晉水祠。","日落高門喧燕雀，風飄大樹撼熊羆。","新蒲似筆思投日，芳草如茵憶吐時。","山下祗今黃絹字，淚痕猶墮六州兒。"]', '["信陵亭館接郊畿，幽象遙通晉水祠。","日落高门喧燕雀，风飄大樹撼熊羆。","新蒲似笔思投日，芳草如茵憶吐时。","山下祗今黄絹字，泪痕猶墮六州兒。"]', '诗', 'shi', '', NULL, '過故府中武威公交城舊莊感事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e9b15b-75ed-46c3-ada7-d4d10190785f', '贈田叟', '贈田叟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["荷蓧衰翁似有情，相逢攜手遶村行。","燒畬曉映遠山色，伐樹暝傳深谷聲。","鷗鳥忘機翻浹洽，交親得路昧平生。","撫躬道直誠感激，在野無賢心自驚。"]', '["荷蓧衰翁似有情，相逢携手遶村行。","燒畬晓映远山色，伐樹暝傳深谷声。","鷗鸟忘機翻浹洽，交親得路昧平生。","撫躬道直誠感激，在野無賢心自驚。"]', '诗', 'shi', '', NULL, '贈田叟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6f6aa7-b244-45a3-9cb5-c4b9737c9bce', '贈別前蔚州契苾使君', '贈別前蔚州契苾使君', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["何年部落到陰陵，奕世勤王國史稱。","夜捲牙旗千帳雪，朝飛羽騎一河冰。","蕃兒襁負來青塚，狄女壺漿出白登。","日晚鸊鵜泉畔獵，路人遙識郅都鷹。"]', '["何年部落到陰陵，奕世勤王国史稱。","夜捲牙旗千帳雪，朝飞羽騎一河冰。","蕃兒襁負来青塚，狄女壺漿出白登。","日晚鸊鵜泉畔獵，路人遙識郅都鷹。"]', '诗', 'shi', '', NULL, '贈別前蔚州契苾使君 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416a1b26-baf9-499f-8838-34ce8d26691a', '和人題真娘墓', '和人題真娘墓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["虎丘山下劒池邊，長遣遊人嘆逝川。","罥樹斷絲悲舞席，出雲清梵想歌筵。","柳眉空吐效顰葉，榆莢還飛買笑錢。","一自香魂招不得，祗應江上獨嬋娟。"]', '["虎丘山下劒池邊，长遣游人嘆逝川。","罥樹斷絲悲舞席，出云清梵想歌筵。","柳眉空吐效顰葉，榆莢還飞買笑錢。","一自香魂招不得，祗應江上独嬋娟。"]', '诗', 'shi', '', NULL, '和人題真娘墓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc83756d-d6a8-4da7-9daf-4f1e91470ed7', '人日即事', '人日即事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["文王喻復今朝是，子晉吹笙此日同。","舜格有苗旬太遠，周稱流火月難窮。","鏤金作勝傳荆俗，翦綵爲人起晉風。","獨想道衡詩思苦，離家恨得二年中。"]', '["文王喻复今朝是，子晉吹笙此日同。","舜格有苗旬太远，周稱流火月难窮。","鏤金作勝傳荆俗，翦綵爲人起晉风。","独想道衡诗思苦，離家恨得二年中。"]', '诗', 'shi', '', NULL, '人日即事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e08df46-f0ea-4e85-b136-c0945ab28482', '春日寄懷', '春日寄懷', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["世間榮落重逡巡，我獨丘園坐四春。","縱使有花兼有月，可堪無酒又無人。","青袍似草年年定，白髮如絲日日新。","欲逐風波千萬里，未知何路到龍津。"]', '["世间榮落重逡巡，我独丘园坐四春。","縱使有花兼有月，可堪無酒又無人。","青袍似草年年定，白髮如絲日日新。","欲逐风波千万里，未知何路到龙津。"]', '诗', 'shi', '', NULL, '春日寄懷 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2540c7c4-de81-4032-8360-262fa6d72053', '和劉評事永樂閑居見寄', '和劉評事永乐闲居见寄', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白社幽閑君暫居，青雲器業我全疎。","看封諫草歸鸞掖，尚賁衡門待鶴書。","蓮聳碧峰關路近，荷翻翠扇水堂虛。","自探典籍忘名利，欹枕時驚落蠹魚。"]', '["白社幽闲君暫居，青云器業我全疎。","看封諫草归鸾掖，尚賁衡门待鹤书。","蓮聳碧峰关路近，荷翻翠扇水堂虛。","自探典籍忘名利，欹枕时驚落蠹鱼。"]', '诗', 'shi', '', NULL, '和劉評事永樂閑居見寄 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1ac9e3-ae77-47b4-a501-ab9ca2eb84bc', '和馬郎中移白菊見示', '和马郎中移白菊见示', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["陶詩只採黃金寶，郢曲新傳白雪英。","素色不同籬下發，繁花疑自月中生。","浮杯小摘開雲母，帶露全移綴水精。","偏稱含香五字客，從茲得地始芳榮。"]', '["陶诗只採黄金寶，郢曲新傳白雪英。","素色不同籬下發，繁花疑自月中生。","浮杯小摘开云母，带露全移綴水精。","偏稱含香五字客，從茲得地始芳榮。"]', '诗', 'shi', '', NULL, '和馬郎中移白菊見示 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04fcdbd-a33c-4a85-bb27-f14970010de5', '喜聞太原同院崔侍御臺拜兼寄在臺三二同年之什', '喜闻太原同院崔侍御台拜兼寄在台三二同年之什', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鵬魚何事遇屯同，雲水升沈一會中。","劉放未歸雞樹老，鄒陽新去兔園空。","寂寥我對先生柳，赫奕君乘御史驄。","若向南臺見鶯友，爲傳垂翅度春風。"]', '["鵬鱼何事遇屯同，云水升沈一會中。","劉放未归雞樹老，鄒陽新去兔园空。","寂寥我对先生柳，赫奕君乘御史驄。","若向南台见鶯友，爲傳垂翅度春风。"]', '诗', 'shi', '', NULL, '喜聞太原同院崔侍御臺拜兼寄在臺三二同年之什 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac26cbb-e57d-4df7-bd60-cf668ef47d4a', '喜雪', '喜雪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["朔雪自龍沙，呈祥勢可嘉。","有田皆種玉，無樹不開花。","班扇慵裁素，曹衣詎比麻。","鵝歸逸少宅，鶴滿令威家。","寂寞門扉掩，依稀履跡斜。","人疑遊麵市，馬似困鹽車。","洛水妃虛妬，姑山客漫誇。","聯辭雖許謝，和曲本慙巴。","粉署闈全隔，霜臺路正賒。","此時傾賀酒，相望在京華。"]', '["朔雪自龙沙，呈祥勢可嘉。","有田皆種玉，無樹不开花。","班扇慵裁素，曹衣詎比麻。","鵝归逸少宅，鹤满令威家。","寂寞门扉掩，依稀履跡斜。","人疑游麵市，马似困鹽车。","洛水妃虛妬，姑山客漫誇。","聯辞雖許謝，和曲本慙巴。","粉署闈全隔，霜台路正賒。","此时傾賀酒，相望在京华。"]', '诗', 'shi', '', NULL, '喜雪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d156e0-7c71-4f1d-beb9-e6accf2ce7c0', '柳枝五首 一', '柳枝五首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["花房與蜜脾，蜂雄蛺蝶雌。","同時不同類，那復更相思。"]', '["花房與蜜脾，蜂雄蛺蝶雌。","同时不同類，那复更相思。"]', '诗', 'shi', '', NULL, '柳枝五首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07022b01-e5ce-4d70-8cc3-d8e92cd40baf', '柳枝五首 二', '柳枝五首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["本是丁香樹，春條結始生。","玉作彈碁局，中心亦不平。"]', '["本是丁香樹，春條結始生。","玉作彈碁局，中心亦不平。"]', '诗', 'shi', '', NULL, '柳枝五首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a48fb9c2-4bd6-4150-981d-245b904b758e', '柳枝五首 三', '柳枝五首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["嘉瓜引蔓長，碧玉冰寒漿。","東陵雖五色，不忍值牙香。"]', '["嘉瓜引蔓长，碧玉冰寒漿。","东陵雖五色，不忍值牙香。"]', '诗', 'shi', '', NULL, '柳枝五首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e06bcb-8091-46f4-8a36-548bb55b54e7', '柳枝五首 四', '柳枝五首 四', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["柳枝井上蟠，蓮葉浦中乾。","錦鱗與繡羽，水陸有傷殘。"]', '["柳枝井上蟠，蓮葉浦中乾。","錦鱗與繡羽，水陸有傷殘。"]', '诗', 'shi', '', NULL, '柳枝五首 四 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79caf113-8524-4f43-b128-5aa3a8a165dd', '柳枝五首 五', '柳枝五首 五', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["畫屏繡步障，物物自成雙。","如何湖上望，只是見鴛鴦。"]', '["畫屏繡步障，物物自成雙。","如何湖上望，只是见鴛鴦。"]', '诗', 'shi', '', NULL, '柳枝五首 五 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a0df6ca-b050-4985-bfee-4bda09da6bc6', '燕臺四首 春', '燕台四首 春', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["風光冉冉東西陌，幾日嬌魂尋不得。","蜜房羽客類芳心，冶葉倡條徧相識。","暖藹輝遲桃樹西，高鬟立共桃鬟齊。","雄龍雌鳳杳何許，絮亂絲繁天亦迷。","醉起微陽若初曙，映簾夢斷聞殘語。","愁將鐵網罥珊瑚，海闊天翻迷處所。","衣帶無情有寬窄，春煙自碧秋霜白。","研丹擘石天不知，願得天牢鎖冤魄。","夾羅委篋單綃起，香肌冷襯琤琤珮。","今日東風自不勝，化作幽光入西海。"]', '["风光冉冉东西陌，幾日嬌魂尋不得。","蜜房羽客類芳心，冶葉倡條徧相識。","暖藹輝遲桃樹西，高鬟立共桃鬟齊。","雄龙雌鳳杳何許，絮亂絲繁天亦迷。","醉起微陽若初曙，映簾梦斷闻殘語。","愁將鐵網罥珊瑚，海闊天翻迷处所。","衣带無情有寬窄，春煙自碧秋霜白。","研丹擘石天不知，願得天牢鎖冤魄。","夾羅委篋單綃起，香肌冷襯琤琤珮。","今日东风自不勝，化作幽光入西海。"]', '诗', 'shi', '', NULL, '燕臺四首 春 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c254cc-0149-4bb9-89cb-d9146893714d', '燕臺四首 夏', '燕台四首 夏', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["前閣雨簾愁不卷，後堂芳樹陰陰見。","石城景物類黃泉，夜半行郎空柘彈。","綾扇喚風閶闔天，輕帷翠幕波淵旋。","蜀魂寂寞有伴未，幾夜瘴花開木棉。","桂宮留影光難取，嫣薰蘭破輕輕語。","直教銀漢墮懷中，未遣星妃鎮來去。","濁水清波何異源，濟河水清黃河渾。","安得簿霧起緗裙，手接雲軿呼太君。"]', '["前閣雨簾愁不卷，後堂芳樹陰陰见。","石城景物類黄泉，夜半行郎空柘彈。","綾扇喚风閶闔天，轻帷翠幕波淵旋。","蜀魂寂寞有伴未，幾夜瘴花开木棉。","桂宮留影光难取，嫣薰蘭破轻轻語。","直教銀漢墮懷中，未遣星妃鎮来去。","濁水清波何異源，濟河水清黄河渾。","安得簿霧起緗裙，手接云軿呼太君。"]', '诗', 'shi', '', NULL, '燕臺四首 夏 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31328cbe-0011-48e1-9f8f-892d2993df6b', '燕臺四首 秋', '燕台四首 秋', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["月浪衝天天宇濕，涼蟾落盡疎星入。","雲屏不動掩孤嚬，西樓一夜風箏急。","欲織相思花寄遠，終日相思却相怨。","但聞北斗聲迴環，不見長河水清淺。","金魚鎖斷紅桂春，古時塵滿鴛鴦茵。","堪悲小苑作長道，玉樹未憐亡國人。","瑤琴愔愔藏楚弄，越羅冷薄金泥重。","簾鉤鸚鵡夜驚霜，喚起南雲繞雲夢。","雙璫丁丁聯尺素，內記湘川相識處。","歌唇一世銜雨看，可惜馨香手中故。"]', '["月浪衝天天宇濕，涼蟾落尽疎星入。","云屏不动掩孤嚬，西楼一夜风箏急。","欲织相思花寄远，終日相思却相怨。","但闻北斗声迴环，不见长河水清淺。","金鱼鎖斷紅桂春，古时塵满鴛鴦茵。","堪悲小苑作长道，玉樹未怜亡国人。","瑤琴愔愔藏楚弄，越羅冷薄金泥重。","簾鉤鸚鵡夜驚霜，喚起南云繞云梦。","雙璫丁丁聯尺素，內記湘川相識处。","歌唇一世銜雨看，可惜馨香手中故。"]', '诗', 'shi', '', NULL, '燕臺四首 秋 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491fe247-c00b-4f11-9e67-7db1c7d55b3c', '燕臺四首 冬', '燕台四首 冬', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["天東日出天西下，雌鳳孤飛女龍寡。","青溪白石不相望，堂中遠甚蒼梧野。","凍壁霜華交隱起，芳根中斷香心死。","浪乘畫舸憶蟾蜍，月娥未必嬋娟子。","楚管蠻絃愁一概，空城舞罷腰支在。","當時歡向掌中銷，桃葉桃根雙姊妹。","破鬟矮墮凌朝寒，白玉燕釵黃金蟬。","風車雨馬不持去，蠟燭啼紅怨天曙。"]', '["天东日出天西下，雌鳳孤飞女龙寡。","青溪白石不相望，堂中远甚蒼梧野。","凍壁霜华交隐起，芳根中斷香心死。","浪乘畫舸憶蟾蜍，月娥未必嬋娟子。","楚管蠻絃愁一概，空城舞罷腰支在。","當时歡向掌中銷，桃葉桃根雙姊妹。","破鬟矮墮凌朝寒，白玉燕釵黄金蟬。","风车雨马不持去，蠟燭啼紅怨天曙。"]', '诗', 'shi', '', NULL, '燕臺四首 冬 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8979051e-dbab-4191-b4eb-da134a09f691', '河內詩二首 一', '河內诗二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鼉鼓沈沈虬水咽，秦絲不上蠻絃絕。","常娥衣薄不禁寒，蟾蜍夜豔秋河月。","碧城冷落空蒙煙，簾輕幕重金鉤欄。","靈香不下兩皇子，孤星直上相風竿。","八桂林邊九芝草，短襟小鬢相逢道。","入門暗數一千春，願去閏年留月小。","梔子交加香蓼繁，停辛佇苦留待君。"]', '["鼉鼓沈沈虬水咽，秦絲不上蠻絃絕。","常娥衣薄不禁寒，蟾蜍夜豔秋河月。","碧城冷落空蒙煙，簾轻幕重金鉤欄。","靈香不下兩皇子，孤星直上相风竿。","八桂林邊九芝草，短襟小鬢相逢道。","入门暗數一千春，願去閏年留月小。","梔子交加香蓼繁，停辛佇苦留待君。"]', '诗', 'shi', '', NULL, '河內詩二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d828e0d8-f37b-4835-9bf3-daf2294e4b45', '河內詩二首 二', '河內诗二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["閶門日下吳歌遠，陂路綠菱香滿滿。","後溪暗起鯉魚風，船旗閃斷芙蓉幹。","輕身奉君畏身輕，雙橈兩槳樽酒清。","莫因風雨罷團扇，此曲斷腸惟北聲。","低樓小徑城南道，猶自金鞍對芳草。"]', '["閶门日下吳歌远，陂路綠菱香满满。","後溪暗起鯉鱼风，船旗閃斷芙蓉幹。","轻身奉君畏身轻，雙橈兩槳樽酒清。","莫因风雨罷團扇，此曲斷腸惟北声。","低楼小徑城南道，猶自金鞍对芳草。"]', '诗', 'shi', '', NULL, '河內詩二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ad36fa-903a-4312-8a17-3d090b5a29e0', '贈送前劉五經映三十四韻', '贈送前劉五經映三十四韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["建國宜師古，興邦屬上庠。","從來以儒戲，安得振朝綱。","叔世何多難，茲基遂已亡。","泣麟猶委吏，歌鳳更佯狂。","屋壁餘無幾，焚坑逮可傷。","挾書秦二世，壤宅漢諸王。","草草臨盟誓，區區務富強。","微茫金馬署，狼籍鬬雞場。","盡欲心無竅，皆如面正墻。","驚疑豹文鼠，貪竊虎皮羊。","南渡宜終否，西遷冀小康。","策非方正士，貢絕孝廉郎。","海鳥悲鐘鼓，狙公畏服裳。","多岐空擾擾，幽室竟倀倀。","凝邈爲時範，虛空作士常。","何由羞五霸，直自呰三皇。","別派驅楊墨，他鑣並老莊。","詩書資破冢，法制困探囊。","周禮仍存魯，隋師果禪唐。","鼎新麾一舉，革故法三章。","星宿森文雅，風雷起退藏。","縲囚爲學切，掌故受經忙。","夫子時之彥，先生跡未荒。","褐衣終不召，白首興難忘。","感激殊非聖，棲遲到異粻。","片辭褒有德，一字貶無良。","燕地尊鄒衍，西河重卜商。","式閭真道在，擁篲信謙光。","獲預青衿列，叨來絳帳旁。","雖從各言志，還要大爲防。","勿謂孤寒棄，深憂訐直妨。","叔孫讒易得，盜跖暴難當。","雁下秦雲黑，蟬休隴葉黃。","莫踰巾屨念，容許後升堂。"]', '["建国宜師古，兴邦屬上庠。","從来以儒戲，安得振朝綱。","叔世何多难，茲基遂已亡。","泣麟猶委吏，歌鳳更佯狂。","屋壁餘無幾，焚坑逮可傷。","挾书秦二世，壤宅漢諸王。","草草臨盟誓，區區務富強。","微茫金马署，狼籍鬬雞場。","尽欲心無竅，皆如面正墻。","驚疑豹文鼠，貪竊虎皮羊。","南渡宜終否，西遷冀小康。","策非方正士，貢絕孝廉郎。","海鸟悲鐘鼓，狙公畏服裳。","多岐空擾擾，幽室竟倀倀。","凝邈爲时範，虛空作士常。","何由羞五霸，直自呰三皇。","別派驱楊墨，他鑣並老莊。","诗书資破冢，法制困探囊。","周禮仍存魯，隋師果禪唐。","鼎新麾一舉，革故法三章。","星宿森文雅，风雷起退藏。","縲囚爲学切，掌故受經忙。","夫子时之彥，先生跡未荒。","褐衣終不召，白首兴难忘。","感激殊非聖，棲遲到異粻。","片辞褒有德，一字貶無良。","燕地尊鄒衍，西河重卜商。","式閭真道在，擁篲信謙光。","獲預青衿列，叨来絳帳旁。","雖從各言志，還要大爲防。","勿謂孤寒棄，深憂訐直妨。","叔孫讒易得，盜跖暴难當。","雁下秦云黑，蟬休隴葉黄。","莫踰巾屨念，容許後升堂。"]', '诗', 'shi', '', NULL, '贈送前劉五經映三十四韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6767b044-44d9-46ee-b87b-33bfcb381ba0', '哭遂州蕭侍郎二十四韻', '哭遂州蕭侍郎二十四韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["遙作時多難，先令禍有源。","初驚逐客議，旋駭黨人冤。","密侍榮方入，司刑望愈尊。","皆因優詔用，實有諫書存。","苦霧三辰沒，窮陰四塞昏。","虎威狐更假，隼擊鳥踰喧。","徒欲心存闕，終遭耳屬垣。","遺音和蜀魄，易簀對巴猿。","有女悲初寡，無男泣過門。","朝爭屈原草，廟餒莫敖魂。","迥閣傷神峻，長江極望翻。","青雲寧寄意，白骨始霑恩。","早歲思東閤，爲邦屬故園。","登舟慚郭泰，解榻愧陳蕃。","分以忘年契，情猶錫類敦。","公先真帝子，我系本王孫。","嘯傲張高蓋，從容接短轅。","秋吟小山桂，春醉後堂萱。","自歎離通籍，何嘗忘呌閽。","不成穿壙入，終擬上書論。","多士還魚貫，云誰正駿奔。","暫能誅儵忽，長與問乾坤。","蟻漏三泉路，螿啼百草根。","始知同泰講，徼福是虛言。"]', '["遙作时多难，先令禍有源。","初驚逐客議，旋駭黨人冤。","密侍榮方入，司刑望愈尊。","皆因優詔用，實有諫书存。","苦霧三辰沒，窮陰四塞昏。","虎威狐更假，隼擊鸟踰喧。","徒欲心存闕，終遭耳屬垣。","遺音和蜀魄，易簀对巴猿。","有女悲初寡，無男泣過门。","朝爭屈原草，廟餒莫敖魂。","迥閣傷神峻，长江極望翻。","青云寧寄意，白骨始霑恩。","早歲思东閤，爲邦屬故园。","登舟慚郭泰，解榻愧陳蕃。","分以忘年契，情猶錫類敦。","公先真帝子，我系本王孫。","嘯傲張高蓋，從容接短轅。","秋吟小山桂，春醉後堂萱。","自歎離通籍，何嘗忘呌閽。","不成穿壙入，終擬上书論。","多士還鱼貫，云誰正駿奔。","暫能誅儵忽，长與问乾坤。","蟻漏三泉路，螿啼百草根。","始知同泰講，徼福是虛言。"]', '诗', 'shi', '', NULL, '哭遂州蕭侍郎二十四韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c89d8196-a13b-4f0c-9f5f-71652c0061e1', '送千牛李將軍赴闕五十韻', '送千牛李將軍赴闕五十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["照席瓊枝秀，當年紫綬榮。","班資古直閣，勳伐舊西京。","在昔王綱紊，因誰國步清。","如無一戰霸，安有大橫庚。","內豎依憑切，凶門責望輕。","中台終惡直，上將更要盟。","丹陛祥煙滅，皇闈殺氣橫。","喧闐衆狙怒，容易八蠻驚。","梼杌寬之久，防風戮不行。","素來矜異類，此去豈親征。","捨魯真非策，居邠未有名。","曾無力牧御，寧待雨師迎。","火箭侵乘石，雲橋逼禁營。","何時絕刁斗，不夜見欃槍。","屢亦聞投鼠，誰其敢射鯨。","世情休念亂，物議笑輕生。","大鹵思龍躍，蒼梧失象耕。","靈衣沾愧汗，儀馬困陰兵。","別館蘭薰酷，深宮蠟燄明。","黃山遮舞態，黑水斷歌聲。","縱未移周鼎，何辭免趙坑。","空拳轉鬬地，數板不沈城。","且欲憑神算，無因計力爭。","幽囚蘇武節，棄市仲由纓。","下殿言終驗，增埤事早萌。","蒸雞殊減饍，屑麴異和羹。","否極時還泰，屯餘運果亨。","流離幾南渡，倉卒得西平。","神鬼收昏黑，姦兇首滿盈。","官非督護貴，師以丈人貞。","覆載還高下，寒暄急改更。","馬前烹莽卓，壇上揖韓彭。","扈蹕三才正，回軍六合晴。","此時惟短劒，仍世盡雙旌。","顧我由羣從，逢君嘆老成。","慶流歸嫡長，貽厥在名卿。","隼擊須當要，鵬摶莫問程。","趨朝排玉座，出位泣金莖。","幸藉梁園賦，叨蒙許氏評。","中郎推貴壻，定遠重時英。","政已標三尚，人今佇一鳴。","長刀懸月魄，快馬駭星精。","披豁慚深眷，暌離動素誠。","蕙留春晼晚，松待歲崢嶸。","異縣期迴雁，登時已飯鯖。","去程風刺刺，別夜漏丁丁。","庾信生多感，楊朱死有情。","絃危中婦瑟，甲冷想夫箏。","會與秦樓鳳，俱聽漢苑鸎。","洛川迷曲沼，煙月兩心傾。"]', '["照席瓊枝秀，當年紫綬榮。","班資古直閣，勳伐旧西京。","在昔王綱紊，因誰国步清。","如無一戰霸，安有大橫庚。","內豎依憑切，凶门責望轻。","中台終惡直，上將更要盟。","丹陛祥煙滅，皇闈殺氣橫。","喧闐衆狙怒，容易八蠻驚。","梼杌寬之久，防风戮不行。","素来矜異類，此去豈親征。","捨魯真非策，居邠未有名。","曾無力牧御，寧待雨師迎。","火箭侵乘石，云橋逼禁營。","何时絕刁斗，不夜见欃槍。","屢亦闻投鼠，誰其敢射鯨。","世情休念亂，物議笑轻生。","大鹵思龙躍，蒼梧失象耕。","靈衣沾愧汗，儀马困陰兵。","別館蘭薰酷，深宮蠟燄明。","黄山遮舞態，黑水斷歌声。","縱未移周鼎，何辞免趙坑。","空拳轉鬬地，數板不沈城。","且欲憑神算，無因計力爭。","幽囚蘇武節，棄市仲由纓。","下殿言終驗，增埤事早萌。","蒸雞殊減饍，屑麴異和羹。","否極时還泰，屯餘運果亨。","流離幾南渡，倉卒得西平。","神鬼收昏黑，姦兇首满盈。","官非督護貴，師以丈人貞。","覆載還高下，寒暄急改更。","马前烹莽卓，壇上揖韓彭。","扈蹕三才正，回軍六合晴。","此时惟短劒，仍世尽雙旌。","顧我由羣從，逢君嘆老成。","慶流归嫡长，貽厥在名卿。","隼擊須當要，鵬摶莫问程。","趨朝排玉座，出位泣金莖。","幸藉梁园賦，叨蒙許氏評。","中郎推貴壻，定远重时英。","政已標三尚，人今佇一鳴。","长刀懸月魄，快马駭星精。","披豁慚深眷，暌離动素誠。","蕙留春晼晚，松待歲崢嶸。","異縣期迴雁，登时已飯鯖。","去程风刺刺，別夜漏丁丁。","庾信生多感，楊朱死有情。","絃危中婦瑟，甲冷想夫箏。","會與秦楼鳳，俱听漢苑鸎。","洛川迷曲沼，煙月兩心傾。"]', '诗', 'shi', '', NULL, '送千牛李將軍赴闕五十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727fc701-c7b8-48b8-89be-7759dc365062', '詠懷寄秘閣舊僚二十六韻', '詠懷寄秘閣旧僚二十六韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["年鬢日堪悲，衡茅益自嗤。","攻文枯若木，處世鈍如鎚。","敢忘垂堂戒，寧將暗室欺。","懸頭曾苦學，折臂反成醫。","僕御嫌夫懦，孩童笑叔癡。","小男方嗜栗，幼女漫憂葵。","遇炙誰先噉，逢韲即便吹。","官銜同畫餅，面貎乏凝脂。","典籍將蠡測，文章若管窺。","圖形翻類狗，入夢肯非羆。","自哂成書簏，終當呪酒巵。","懶霑襟上血，羞鑷鏡中絲。","槖籥言方喻，樗蒱齒詎知。","事神徒惕慮，佞佛媿虛辭。","曲藝垂麟角，浮名狀虎皮。","乘軒寧見寵，巢幕更逢危。","禮俗拘嵇喜，侯王忻戴逵。","途窮方結舌，靜勝但搘頤。","糲食空彈劒，亨衢詎置錐。","栢臺成口號，芸閣暫肩隨。","悔逐遷鸎伴，誰觀擇虱時。","甕間眠太率，牀下隱何卑。","奮跡登弘閣，摧心對董帷。","校讎如有暇，松竹一相思。"]', '["年鬢日堪悲，衡茅益自嗤。","攻文枯若木，处世鈍如鎚。","敢忘垂堂戒，寧將暗室欺。","懸头曾苦学，折臂反成醫。","僕御嫌夫懦，孩童笑叔癡。","小男方嗜栗，幼女漫憂葵。","遇炙誰先噉，逢韲即便吹。","官銜同畫餅，面貎乏凝脂。","典籍將蠡測，文章若管窺。","圖形翻類狗，入梦肯非羆。","自哂成书簏，終當呪酒巵。","懶霑襟上血，羞鑷镜中絲。","槖籥言方喻，樗蒱齒詎知。","事神徒惕慮，佞佛媿虛辞。","曲藝垂麟角，浮名狀虎皮。","乘軒寧见寵，巢幕更逢危。","禮俗拘嵇喜，侯王忻戴逵。","途窮方結舌，静勝但搘頤。","糲食空彈劒，亨衢詎置錐。","栢台成口號，芸閣暫肩隨。","悔逐遷鸎伴，誰观擇虱时。","甕间眠太率，牀下隐何卑。","奮跡登弘閣，摧心对董帷。","校讎如有暇，松竹一相思。"]', '诗', 'shi', '', NULL, '詠懷寄秘閣舊僚二十六韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dbe123-eb3a-4d48-ba55-0a14d193f33e', '戊辰會靜中出貽同志二十韻', '戊辰會静中出貽同志二十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["大道諒無外，會越自登真。","丹元子何索，在己莫問隣。","蒨璨玉琳華，翶翔九真君。","戲擲萬里火，聊召六甲旬。","瑤簡被靈誥，持符開七門。","金鈴攝羣魔，絳節何兟兟。","吟弄東海若，笑倚扶桑春。","三山誠迥視，九州揚一塵。","我本玄元胄，稟華由上津。","中迷鬼道樂，沈爲下土民。","託質屬太陰，鍊形復爲人。","誓將覆宮澤，安此真與神。","龜山有慰薦，南真爲彌綸。","玉管會玄圃，火棗承天姻。","科車遏故氣，侍香傳靈氛。","飄颻被青霓，婀娜佩紫紋。","林洞何其微，下仙不與羣。","丹泥因未控，萬劫猶逡巡。","荆蕪既以薙，舟壑永無湮。","相期保妙命，騰景侍帝宸。"]', '["大道諒無外，會越自登真。","丹元子何索，在己莫问隣。","蒨璨玉琳华，翶翔九真君。","戲擲万里火，聊召六甲旬。","瑤簡被靈誥，持符开七门。","金鈴攝羣魔，絳節何兟兟。","吟弄东海若，笑倚扶桑春。","三山誠迥視，九州揚一塵。","我本玄元胄，稟华由上津。","中迷鬼道乐，沈爲下土民。","託質屬太陰，鍊形复爲人。","誓將覆宮澤，安此真與神。","龟山有慰薦，南真爲彌綸。","玉管會玄圃，火棗承天姻。","科车遏故氣，侍香傳靈氛。","飄颻被青霓，婀娜佩紫紋。","林洞何其微，下仙不與羣。","丹泥因未控，万劫猶逡巡。","荆蕪既以薙，舟壑永無湮。","相期保妙命，腾景侍帝宸。"]', '诗', 'shi', '', NULL, '戊辰會靜中出貽同志二十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af70c9da-8e36-44b4-aee0-4e73e87192e1', '和鄭愚贈汝陽王孫家箏妓二十韻', '和鄭愚贈汝陽王孫家箏妓二十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["冰霧怨何窮，秦絲嬌未已。","寒空煙霞高，白日一萬里。","碧嶂愁不行，濃翠遙相倚。","茜袖捧瓊姿，皎日丹霞起。","孤猿耿幽寂，西風吹白芷。","回首蒼梧深，女蘿閉山鬼。","荒郊白鱗斷，別浦晴霞委。","長彴壓河心，白道連地尾。","秦人昔富家，綠窗聞妙旨。","鴻驚雁背飛，象牀殊故里。","因令五十絲，中道分宮徵。","斗粟配新聲，娣姪徒纖指。","風流大堤上，悵望白門裏。","蠹粉實雌絃，燈光冷如水。","羌管促蠻柱，從醉吳宮耳。","滿內不埽眉，君王對西子。","初花慘朝露，冷臂淒愁髓。","一曲送連錢，遠別長於死。","玉砌銜紅蘭，粧窗結碧綺。","九門十二關，清晨禁桃李。"]', '["冰霧怨何窮，秦絲嬌未已。","寒空煙霞高，白日一万里。","碧嶂愁不行，濃翠遙相倚。","茜袖捧瓊姿，皎日丹霞起。","孤猿耿幽寂，西风吹白芷。","回首蒼梧深，女蘿閉山鬼。","荒郊白鱗斷，別浦晴霞委。","长彴壓河心，白道連地尾。","秦人昔富家，綠窗闻妙旨。","鴻驚雁背飞，象牀殊故里。","因令五十絲，中道分宮徵。","斗粟配新声，娣姪徒纖指。","风流大堤上，悵望白门裏。","蠹粉實雌絃，灯光冷如水。","羌管促蠻柱，從醉吳宮耳。","满內不埽眉，君王对西子。","初花慘朝露，冷臂淒愁髓。","一曲送連錢，远別长於死。","玉砌銜紅蘭，粧窗結碧綺。","九门十二关，清晨禁桃李。"]', '诗', 'shi', '', NULL, '和鄭愚贈汝陽王孫家箏妓二十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb0a5a6-b0c4-45eb-8d92-e8ea38463dd3', '四年冬以退居蒲之永樂渴然有農夫望歲之志遂作憶雪又作殘雪詩各一百言以寄情於游舊 憶雪', '四年冬以退居蒲之永乐渴然有農夫望歲之志遂作憶雪又作殘雪诗各一百言以寄情於游旧 憶雪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["愛景人方樂，同雲候稍愆。","徒聞周雅什，願賦朔風篇。","欲俟千箱慶，須資六出妍。","詠留飛絮後，歌唱落梅前。","庭樹思瓊蕊，粧樓認粉綿。","瑞邀盈尺日，豐待兩岐年。","預約延枚酒，虛乘訪戴船。","映書孤志業，披氅阻神仙。","幾向霜階步，頻將月幌褰。","玉京應已足，白屋但顒然。"]', '["愛景人方乐，同云候稍愆。","徒闻周雅什，願賦朔风篇。","欲俟千箱慶，須資六出妍。","詠留飞絮後，歌唱落梅前。","庭樹思瓊蕊，粧楼認粉綿。","瑞邀盈尺日，豐待兩岐年。","預約延枚酒，虛乘訪戴船。","映书孤志業，披氅阻神仙。","幾向霜階步，頻將月幌褰。","玉京應已足，白屋但顒然。"]', '诗', 'shi', '', NULL, '四年冬以退居蒲之永樂渴然有農夫望歲之志遂作憶雪又作殘雪詩各一百言以寄情於游舊 憶雪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879b7153-c37a-420f-82e7-9f863d1ce365', '四年冬以退居蒲之永樂渴然有農夫望歲之志遂作憶雪又作殘雪詩各一百言以寄情於游舊 殘雪', '四年冬以退居蒲之永乐渴然有農夫望歲之志遂作憶雪又作殘雪诗各一百言以寄情於游旧 殘雪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["旭日開晴色，寒空失素塵。","遶墻全剝粉，傍井漸消銀。","刻獸摧鹽虎，爲山倒玉人。","珠還猶照魏，璧碎尚留秦。","落日驚侵畫，餘光悞惜春。","簷冰滴鵝管，屋瓦鏤魚鱗。","嶺霽嵐光坼，松暄翠粒新。","擁林愁拂盡，著砌恐行頻。","焦寢忻無患，梁園去有因。","莫能知帝力，空此荷平均。"]', '["旭日开晴色，寒空失素塵。","遶墻全剝粉，傍井漸消銀。","刻獸摧鹽虎，爲山倒玉人。","珠還猶照魏，璧碎尚留秦。","落日驚侵畫，餘光悞惜春。","簷冰滴鵝管，屋瓦鏤鱼鱗。","嶺霽嵐光坼，松暄翠粒新。","擁林愁拂尽，著砌恐行頻。","焦寢忻無患，梁园去有因。","莫能知帝力，空此荷平均。"]', '诗', 'shi', '', NULL, '四年冬以退居蒲之永樂渴然有農夫望歲之志遂作憶雪又作殘雪詩各一百言以寄情於游舊 殘雪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb89bf00-4f43-4dfa-96a3-899b19931b80', '大鹵平後移家到永樂縣居書懷十韻寄劉韋二前輩二公嘗於此縣寄居', '大鹵平後移家到永乐縣居书懷十韻寄劉韋二前輩二公嘗於此縣寄居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["驅馬遶河干，家山照露寒。","依然五柳在，況值百花殘。","昔去驚投筆，今來分挂冠。","不憂懸磬乏，乍喜覆盂安。","甑破寧迴顧，舟沈豈暇看。","脫身離虎口，移疾就猪肝。","鬢入新年白，顏無舊日丹。","自悲秋穫少，谁懼夏畦難。","逸志忘鴻鵠，清香披蕙蘭。","還持一杯酒，坐想二公懽。"]', '["驱马遶河干，家山照露寒。","依然五柳在，況值百花殘。","昔去驚投笔，今来分挂冠。","不憂懸磬乏，乍喜覆盂安。","甑破寧迴顧，舟沈豈暇看。","脫身離虎口，移疾就猪肝。","鬢入新年白，顏無旧日丹。","自悲秋穫少，谁懼夏畦难。","逸志忘鴻鵠，清香披蕙蘭。","還持一杯酒，坐想二公懽。"]', '诗', 'shi', '', NULL, '大鹵平後移家到永樂縣居書懷十韻寄劉韋二前輩二公嘗於此縣寄居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda04956-3b08-44a5-af05-d4b170ce445f', '河陽詩', '河陽诗', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["黃河搖溶天上來，玉樓影近中天臺。","龍頭瀉酒客壽杯，主人淺笶紅玫瑰。","梓澤東來七十里，長溝複塹埋雲子。","可惜秋眸一臠光，漢陵走馬黃塵起。","南浦老魚腥古涎，真珠密字芙蓉篇。","湘中寄到夢不到，衰容自去拋涼天。","憶得蛟絲裁小卓，蛺蝶飛迴木綿薄。","綠繍笙囊不見人，一口紅霞夜深嚼。","幽蘭泣露新香死，畫圖淺縹松溪水。","楚絲微覺竹枝高，半曲新辭寫緜紙。","巴西夜市紅守宮，後房點臂斑斑紅。","堤南渴雁自飛久，蘆花一夜吹西風。","曉簾串斷蜻蜓翼，羅屏但有空青色。","玉灣不釣三千年，蓮房暗被蛟龍惜。","濕銀注鏡井口平，鸞釵映月寒錚錚。","不知桂樹在何處，仙人不下雙金莖。","百尺相風插重屋，側近嫣紅伴柔綠。","百勞不識對月郎，湘竹千條爲一束。"]', '["黄河搖溶天上来，玉楼影近中天台。","龙头瀉酒客壽杯，主人淺笶紅玫瑰。","梓澤东来七十里，长溝複塹埋云子。","可惜秋眸一臠光，漢陵走马黄塵起。","南浦老鱼腥古涎，真珠密字芙蓉篇。","湘中寄到梦不到，衰容自去拋涼天。","憶得蛟絲裁小卓，蛺蝶飞迴木綿薄。","綠繍笙囊不见人，一口紅霞夜深嚼。","幽蘭泣露新香死，畫圖淺縹松溪水。","楚絲微覺竹枝高，半曲新辞寫緜紙。","巴西夜市紅守宮，後房点臂斑斑紅。","堤南渴雁自飞久，蘆花一夜吹西风。","晓簾串斷蜻蜓翼，羅屏但有空青色。","玉灣不釣三千年，蓮房暗被蛟龙惜。","濕銀注镜井口平，鸾釵映月寒錚錚。","不知桂樹在何处，仙人不下雙金莖。","百尺相风插重屋，側近嫣紅伴柔綠。","百勞不識对月郎，湘竹千條爲一束。"]', '诗', 'shi', '', NULL, '河陽詩 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8511f2ce-c150-4948-ad49-ad6e8ac118ff', '自桂林奉使江陵途中感懷寄獻尚書', '自桂林奉使江陵途中感懷寄獻尚书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["下客依蓮幕，明公念竹林。","縱然膺使命，何以奉徽音。","投刺雖傷晚，酬恩豈在今。","迎來新瑣闥，從到碧瑤岑。","水勢初知海，天文始識參。","固慚非賈誼，惟恐後陳琳。","前席驚虛辱，華樽許細斟。","尚憐秦痔苦，不遣楚醪沈。","既載從戎筆，仍披選勝襟。","瀧通伏波柱，簾對有虞琴。","宅與嚴城接，門藏別岫深。","閣涼松冉冉，堂靜桂森森。","社內容周續，鄉中保展禽。","白衣居士訪，烏帽逸人尋。","佞佛將成傳，耽書或類淫。","長懷五羖贖，終著九州箴。","良訊封鴛綺，餘光借玳簪。","張衡愁浩浩，沈約瘦愔愔。","蘆白疑粘鬢，楓丹欲照心。","歸期無雁報，旅抱有猿侵。","短日安能駐，低雲只有陰。","亂鴉衝曬網，寒女簇遙砧。","東道違寧久，西園望不禁。","江生魂黯黯，泉客淚涔涔。","逸翰應藏法，高辭肯浪吟。","數須傳庾翼，莫獨與盧諶。","假寐憑書簏，哀吟叩劒鐔。","未嘗貪偃息，那復議登臨。","彼美迴清鏡，其誰受曲針。","人皆向燕路，無乃費黃金。"]', '["下客依蓮幕，明公念竹林。","縱然膺使命，何以奉徽音。","投刺雖傷晚，酬恩豈在今。","迎来新瑣闥，從到碧瑤岑。","水勢初知海，天文始識參。","固慚非賈誼，惟恐後陳琳。","前席驚虛辱，华樽許細斟。","尚怜秦痔苦，不遣楚醪沈。","既載從戎笔，仍披選勝襟。","瀧通伏波柱，簾对有虞琴。","宅與嚴城接，门藏別岫深。","閣涼松冉冉，堂静桂森森。","社內容周續，乡中保展禽。","白衣居士訪，烏帽逸人尋。","佞佛將成傳，耽书或類淫。","长懷五羖贖，終著九州箴。","良訊封鴛綺，餘光借玳簪。","張衡愁浩浩，沈約瘦愔愔。","蘆白疑粘鬢，楓丹欲照心。","归期無雁報，旅抱有猿侵。","短日安能駐，低云只有陰。","亂鴉衝曬網，寒女簇遙砧。","东道違寧久，西园望不禁。","江生魂黯黯，泉客泪涔涔。","逸翰應藏法，高辞肯浪吟。","數須傳庾翼，莫独與盧諶。","假寐憑书簏，哀吟叩劒鐔。","未嘗貪偃息，那复議登臨。","彼美迴清镜，其誰受曲針。","人皆向燕路，無乃費黄金。"]', '诗', 'shi', '', NULL, '自桂林奉使江陵途中感懷寄獻尚書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d0605f6-b831-4ddf-a00e-18a0f7380ddd', '送從翁從東川弘農尚書幕', '送從翁從东川弘農尚书幕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["大鎮初更帥，嘉賓素見邀。","使車無遠近，歸路更煙霄。","穩放驊騮步，高安翡翠巢。","御風知有在，去國肯無聊。","早忝諸孫末，俱從小隱招。","心懸紫雲閣，夢斷赤城標。","素女悲清瑟，秦娥弄玉簫。","山連玄圃近，水接絳河遙。","豈意聞周鐸，翻然慕舜韶。","皆辭喬木去，遠逐斷蓬飄。","薄俗誰其激，斯民已甚恌。","鸞皇期一舉，燕雀不相饒。","敢共頽波遠，因之內火燒。","是非過別夢，時節慘驚飙。","未至誰能賦，中乾欲病痟。","屢曾紆錦繍，勉欲報瓊瑤。","我恐霜侵鬢，君先綬挂腰。","甘心與陳阮，揮手謝松喬。","錦里差隣接，雲臺閉寂寥。","一川虛月魄，萬崦自芝苗。","瘴雨瀧間急，離魂峽外銷。","非關無燭夜，其奈落花朝。","幾處逢鳴佩，何筵不翠翹。","蠻童騎象舞，江市賣鮫綃。","南詔知非敵，西山亦屢驕。","勿貪佳麗地，不爲聖明朝。","少減東城飲，時看北斗杓。","莫因乖別久，遂逐歲寒凋。","盛幕開高宴，將軍問故僚。","爲言公玉季，早日棄漁樵。"]', '["大鎮初更帥，嘉賓素见邀。","使车無远近，归路更煙霄。","穩放驊騮步，高安翡翠巢。","御风知有在，去国肯無聊。","早忝諸孫末，俱從小隐招。","心懸紫云閣，梦斷赤城標。","素女悲清瑟，秦娥弄玉簫。","山連玄圃近，水接絳河遙。","豈意闻周鐸，翻然慕舜韶。","皆辞喬木去，远逐斷蓬飄。","薄俗誰其激，斯民已甚恌。","鸾皇期一舉，燕雀不相饒。","敢共頽波远，因之內火燒。","是非過別梦，时節慘驚飙。","未至誰能賦，中乾欲病痟。","屢曾紆錦繍，勉欲報瓊瑤。","我恐霜侵鬢，君先綬挂腰。","甘心與陳阮，揮手謝松喬。","錦里差隣接，云台閉寂寥。","一川虛月魄，万崦自芝苗。","瘴雨瀧间急，離魂峽外銷。","非关無燭夜，其奈落花朝。","幾处逢鳴佩，何筵不翠翹。","蠻童騎象舞，江市賣鮫綃。","南詔知非敵，西山亦屢驕。","勿貪佳丽地，不爲聖明朝。","少減东城饮，时看北斗杓。","莫因乖別久，遂逐歲寒凋。","盛幕开高宴，將軍问故僚。","爲言公玉季，早日棄漁樵。"]', '诗', 'shi', '', NULL, '送從翁從東川弘農尚書幕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733f6c2e-04a1-4935-9054-01ae4e03220c', '李肱所遺畫松詩書兩紙得四十韻', '李肱所遺畫松诗书兩紙得四十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬草已涼露，開圖披古松。","青山徧滄海，此樹生何峰。","孤根邈無倚，直立撐鴻濛。","端如君子身，挺若壯士胸。","樛枝勢夭矯，忽欲蟠拏空。","又如驚螭走，默與奔雲逢。","孫枝擢細葉，旖旎狐裘茸。","鄒颠蓐髪軟，麗姬眉黛濃。","視久眩目睛，倏忽變輝容。","竦削正稠直，婀娜旋敷峰。","又如洞房冷，翠被張穹籠。","亦若暨羅女，平旦妝顏容。","細疑襲氣母，猛若爭神功。","燕雀固寂寂，霧露常衝衝。","香蘭媿傷暮，碧竹慚空中。","可集呈瑞鳳，堪藏行雨龍。","淮山桂偃蹇，蜀郡桑重童。","枝條亮眇脆，靈氣何由同。","昔聞咸陽帝，近說稽山儂。","或著仙人號，或以大夫封。","終南與清都，煙雨遙相通。","安知夜夜意，不起西南風。","美人昔清興，重之猶月鐘。","寶笥十八九，香緹千萬重。","一旦鬼瞰室，稠疊張羉罿。","赤羽中要害，是非皆怱怱。","生如碧海月，死踐霜郊蓬。","平生握中玩，散失隨奴童。","我聞照妖鏡，及與神劒鋒。","寓身會有地，不爲凡物蒙。","伊人秉蕬圖，顧眄擇所從。","而我何爲者，開顏捧靈蹤。","報以漆鳴琴，懸之真珠櫳。","是時方暑夏，座內若嚴冬。","憶昔謝四騎，學仙玉陽東。","千株盡若此，路入瓊瑤宮。","口詠玄雲歌，手把金芙蓉。","濃藹深霓袖，色映琅玕中。","悲哉墮世網，去之若遺弓。","形魄天壇上，海日高曈曈。","終騎紫鸞歸，持寄扶桑翁。"]', '["万草已涼露，开圖披古松。","青山徧滄海，此樹生何峰。","孤根邈無倚，直立撐鴻濛。","端如君子身，挺若壯士胸。","樛枝勢夭矯，忽欲蟠拏空。","又如驚螭走，默與奔云逢。","孫枝擢細葉，旖旎狐裘茸。","鄒颠蓐髪軟，丽姬眉黛濃。","視久眩目睛，倏忽变輝容。","竦削正稠直，婀娜旋敷峰。","又如洞房冷，翠被張穹籠。","亦若暨羅女，平旦妝顏容。","細疑襲氣母，猛若爭神功。","燕雀固寂寂，霧露常衝衝。","香蘭媿傷暮，碧竹慚空中。","可集呈瑞鳳，堪藏行雨龙。","淮山桂偃蹇，蜀郡桑重童。","枝條亮眇脆，靈氣何由同。","昔闻咸陽帝，近说稽山儂。","或著仙人號，或以大夫封。","終南與清都，煙雨遙相通。","安知夜夜意，不起西南风。","美人昔清兴，重之猶月鐘。","寶笥十八九，香緹千万重。","一旦鬼瞰室，稠叠張羉罿。","赤羽中要害，是非皆怱怱。","生如碧海月，死踐霜郊蓬。","平生握中玩，散失隨奴童。","我闻照妖镜，及與神劒鋒。","寓身會有地，不爲凡物蒙。","伊人秉蕬圖，顧眄擇所從。","而我何爲者，开顏捧靈蹤。","報以漆鳴琴，懸之真珠櫳。","是时方暑夏，座內若嚴冬。","憶昔謝四騎，学仙玉陽东。","千株尽若此，路入瓊瑤宮。","口詠玄云歌，手把金芙蓉。","濃藹深霓袖，色映琅玕中。","悲哉墮世網，去之若遺弓。","形魄天壇上，海日高曈曈。","終騎紫鸾归，持寄扶桑翁。"]', '诗', 'shi', '', NULL, '李肱所遺畫松詩書兩紙得四十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52c24db-89d8-423c-aa49-b665a8b41141', '戲題樞言草閣三十二韻', '戲題樞言草閣三十二韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["君家在河北，我家在山西。","百歲本無業，陰陰仙李枝。","尚書文與武，戰罷幕府開。","君從渭南至，我自仙遊來。","平昔苦南北，動成雲雨乖。","逮今兩攜手，對若牀下鞵。","夜歸碣石館，朝上黃金臺。","我有苦寒調，君抱陽春才。","年顏各少壯，髪綠齒尚齊。","我雖不能飲，君時醉如泥。","政靜籌畫簡，退食多相攜。","埽掠走馬路，整頓射雉翳。","春風二三月，柳密鶯正啼。","清河在門外，上與浮雲齊。","欹冠調玉琴，彈作松風哀。","又彈明君怨，一去怨不回。","感激坐者泣，起視雁行低。","翻憂龍山雪，却雜胡沙飛。","仲容銅琵琶，項直聲淒淒。","上貼金捍撥，畫爲承露雞。","君時臥掁觸，勸客白玉盃。","苦云年光疾，不飲將安歸。","我賞此言是，因循未能諧。","君言中聖人，坐臥莫我違。","楡莢亂不整，楊花飛相隨。","上有白日照，下有東風吹。","青樓有美人，顏色如玫瑰。","歌聲入青雲，所痛無良媒。","少年苦不久，顧慕良難哉。","徒令真珠肶，裛入珊瑚腮。","君今且少安，聽我苦吟詩。","古詩何人作，老大從傷悲。"]', '["君家在河北，我家在山西。","百歲本無業，陰陰仙李枝。","尚书文與武，戰罷幕府开。","君從渭南至，我自仙游来。","平昔苦南北，动成云雨乖。","逮今兩携手，对若牀下鞵。","夜归碣石館，朝上黄金台。","我有苦寒調，君抱陽春才。","年顏各少壯，髪綠齒尚齊。","我雖不能饮，君时醉如泥。","政静籌畫簡，退食多相携。","埽掠走马路，整頓射雉翳。","春风二三月，柳密鶯正啼。","清河在门外，上與浮云齊。","欹冠調玉琴，彈作松风哀。","又彈明君怨，一去怨不回。","感激坐者泣，起視雁行低。","翻憂龙山雪，却杂胡沙飞。","仲容銅琵琶，項直声淒淒。","上貼金捍撥，畫爲承露雞。","君时臥掁觸，勸客白玉盃。","苦云年光疾，不饮將安归。","我賞此言是，因循未能諧。","君言中聖人，坐臥莫我違。","楡莢亂不整，楊花飞相隨。","上有白日照，下有东风吹。","青楼有美人，顏色如玫瑰。","歌声入青云，所痛無良媒。","少年苦不久，顧慕良难哉。","徒令真珠肶，裛入珊瑚腮。","君今且少安，听我苦吟诗。","古诗何人作，老大從傷悲。"]', '诗', 'shi', '', NULL, '戲題樞言草閣三十二韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a153607f-10f7-41ab-ba80-88ed17e9d728', '偶成轉韻七十二句贈四同舍', '偶成轉韻七十二句贈四同舍', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["沛國東風吹大澤，蒲青柳碧春一色。","我來不見隆準人，瀝酒空餘廟中客。","征東同舍鴛與鸞，酒酣勸我懸征鞍。","藍山寶肆不可入，玉中仍是青琅玕。","武威將軍使中俠，少年箭道驚楊葉。","戰功高後數文章，憐我秋齋夢蝴蝶。","詰旦九門傳奏章，高車大馬來煌煌。","路逢鄒枚不暇揖，臘月大雪過大梁。","憶昔公爲會昌宰，我時入謁虛懷待。","衆中賞我賦高唐，迴看屈宋由年輩。","公事武皇爲鐵冠，歷廳請我相所難。","我時顦顇在書閣，臥枕芸香春夜闌。","明年赴辟下昭桂，東郊慟哭辭兄弟。","韓公堆上跋馬時，廻望秦川樹如薺。","依稀南指陽臺雲，鯉魚食鈎猿失羣。","湘妃廟下已春盡，虞帝城前初日曛。","謝遊橋上澄江館，下望山城如一彈。","鷓鴣聲苦曉驚眠，朱槿花嬌晚相伴。","頃之失職辭南風，破帆壞槳荆江中。","斬蛟斷璧不無意，平生自許非忩忩。","歸來寂寞靈臺下，著破藍衫出無馬。","天官補吏府中趨，玉骨瘦來無一把。","手封狴牢屯制囚，直廳印鎖黃昏愁。","平明赤帖使修表，上賀嫖姚收賊州。","舊山萬仞青霞外，望見扶桑出東海。","愛君憂國去未能，白道青松了然在。","此時聞有燕昭臺，挺身東望心眼開。","且吟王粲從軍樂，不賦淵明歸去來。","彭門十萬皆雄勇，首戴公恩若山重。","廷評日下握靈蛇，書記眠時吞綵鳳。","之子夫君鄭與裴，何甥謝舅當世才。","青袍白簡風流極，碧沼紅蓮傾倒開。","我生麤疎不足數，梁父哀吟鴝鵒舞。","橫行闊視倚公憐，狂來筆力如牛弩。","借酒祝公千萬年，吾徒禮分常周旋。","收旗臥鼓相天子，相門出相光青史。"]', '["沛国东风吹大澤，蒲青柳碧春一色。","我来不见隆準人，瀝酒空餘廟中客。","征东同舍鴛與鸾，酒酣勸我懸征鞍。","藍山寶肆不可入，玉中仍是青琅玕。","武威將軍使中俠，少年箭道驚楊葉。","戰功高後數文章，怜我秋斋梦蝴蝶。","詰旦九门傳奏章，高车大马来煌煌。","路逢鄒枚不暇揖，臘月大雪過大梁。","憶昔公爲會昌宰，我时入謁虛懷待。","衆中賞我賦高唐，迴看屈宋由年輩。","公事武皇爲鐵冠，歷廳請我相所难。","我时顦顇在书閣，臥枕芸香春夜闌。","明年赴辟下昭桂，东郊慟哭辞兄弟。","韓公堆上跋马时，廻望秦川樹如薺。","依稀南指陽台云，鯉鱼食鈎猿失羣。","湘妃廟下已春尽，虞帝城前初日曛。","謝游橋上澄江館，下望山城如一彈。","鷓鴣声苦晓驚眠，朱槿花嬌晚相伴。","頃之失職辞南风，破帆壞槳荆江中。","斬蛟斷璧不無意，平生自許非忩忩。","归来寂寞靈台下，著破藍衫出無马。","天官補吏府中趨，玉骨瘦来無一把。","手封狴牢屯制囚，直廳印鎖黄昏愁。","平明赤帖使修表，上賀嫖姚收賊州。","旧山万仞青霞外，望见扶桑出东海。","愛君憂国去未能，白道青松了然在。","此时闻有燕昭台，挺身东望心眼开。","且吟王粲從軍乐，不賦淵明归去来。","彭门十万皆雄勇，首戴公恩若山重。","廷評日下握靈蛇，书記眠时吞綵鳳。","之子夫君鄭與裴，何甥謝舅當世才。","青袍白簡风流極，碧沼紅蓮傾倒开。","我生麤疎不足數，梁父哀吟鴝鵒舞。","橫行闊視倚公怜，狂来笔力如牛弩。","借酒祝公千万年，吾徒禮分常周旋。","收旗臥鼓相天子，相门出相光青史。"]', '诗', 'shi', '', NULL, '偶成轉韻七十二句贈四同舍 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb373e9-4d4e-48f0-8dac-43a20d12466e', '五言述德抒情詩一首四十韻獻上杜七兄僕射相公', '五言述德抒情诗一首四十韻獻上杜七兄僕射相公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["帝作黃金闕，仙開白玉京。","有人扶太極，惟嶽降元精。","耿賈官勳大，荀陳地望清。","旂常懸祖德，甲令著嘉聲。","經出宣尼壁，書留晏子楹。","武鄉傳陳法，踐土主文盟。","自昔流王澤，由來仗國楨。","九河分合沓，一柱忽崢嶸。","得主勞三顧，驚人肯再鳴。","碧虛天共轉，黃道日同行。","後飲曹參酒，先和傅說羹。","即時賢路闢，此夜泰階平。","願保無疆福，將圖不朽名。","率身期濟世，叩額慮興兵。","感念殽屍露，咨嗟趙卒坑。","儻令安隱忍，何以贊貞明。","惡草雖當路，寒松實挺生。","人言真可畏，公意本無爭。","故事留臺閣，前驅且斾旌。","芙蓉王儉府，楊柳亞夫營。","清嘯頻疎俗，高談屢析酲。","過庭多令子，乞墅有名甥。","南詔應聞命，西山莫敢驚。","寄辭收的博，端坐掃欃槍。","雅宴初無倦，長歌底有情。","檻危春水暖，樓迥雪峰晴。","移席牽緗蔓，迴橈撲絳英。","誰知杜武庫，只見謝宣城。","有客趨高義，於今滯下卿。","登門慚後至，置驛恐虛迎。","自是依劉表，安能比老彭。","雕龍心己切，畫虎意何成。","豈有曾黔突，徒勞不倚衡。","乘時乖巧宦，占象合艱貞。","廢忘淹中學，遲迴谷口耕。","悼傷潘岳重，樹立馬遷輕。","隴鳥悲丹觜，湘蘭怨紫莖。","歸期過舊歲，旅夢遶殘更。","弱植叨華族，衰門倚外兄。","欲陳勞者曲，未唱淚先橫。"]', '["帝作黄金闕，仙开白玉京。","有人扶太極，惟嶽降元精。","耿賈官勳大，荀陳地望清。","旂常懸祖德，甲令著嘉声。","經出宣尼壁，书留晏子楹。","武乡傳陳法，踐土主文盟。","自昔流王澤，由来仗国楨。","九河分合沓，一柱忽崢嶸。","得主勞三顧，驚人肯再鳴。","碧虛天共轉，黄道日同行。","後饮曹參酒，先和傅说羹。","即时賢路闢，此夜泰階平。","願保無疆福，將圖不朽名。","率身期濟世，叩額慮兴兵。","感念殽屍露，咨嗟趙卒坑。","儻令安隐忍，何以贊貞明。","惡草雖當路，寒松實挺生。","人言真可畏，公意本無爭。","故事留台閣，前驱且斾旌。","芙蓉王儉府，楊柳亞夫營。","清嘯頻疎俗，高談屢析酲。","過庭多令子，乞墅有名甥。","南詔應闻命，西山莫敢驚。","寄辞收的博，端坐掃欃槍。","雅宴初無倦，长歌底有情。","檻危春水暖，楼迥雪峰晴。","移席牽緗蔓，迴橈撲絳英。","誰知杜武庫，只见謝宣城。","有客趨高義，於今滯下卿。","登门慚後至，置驛恐虛迎。","自是依劉表，安能比老彭。","雕龙心己切，畫虎意何成。","豈有曾黔突，徒勞不倚衡。","乘时乖巧宦，占象合艱貞。","廢忘淹中学，遲迴谷口耕。","悼傷潘岳重，樹立马遷轻。","隴鸟悲丹觜，湘蘭怨紫莖。","归期過旧歲，旅梦遶殘更。","弱植叨华族，衰门倚外兄。","欲陳勞者曲，未唱泪先橫。"]', '诗', 'shi', '', NULL, '五言述德抒情詩一首四十韻獻上杜七兄僕射相公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90bb2eb8-0a59-43e9-9d1c-b29f382d3aaf', '今月二日不自量度輒以詩一首四十韻干凟尊嚴伏蒙仁恩俯賜披覽獎踰其實情溢於辭顧惟疎蕪曷用酬戴輒復五言四十韻詩獻上亦詩人詠嘆不足之義也', '今月二日不自量度輒以诗一首四十韻干凟尊嚴伏蒙仁恩俯賜披覽獎踰其實情溢於辞顧惟疎蕪曷用酬戴輒复五言四十韻诗獻上亦诗人詠嘆不足之義也', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["家擅無雙譽，朝居第一功。","四時當首夏，八節應條風。","滌濯臨清濟，巉巖倚碧嵩。","鮑壺冰皎潔，王佩玉丁東。","處劇張京兆，通經戴侍中。","將星臨迥夜，卿月麗層穹。","下令銷秦盜，高談破宋聾。","含霜太山竹，拂霧嶧陽桐。","樂道乾知退，當官蹇匪躬。","服箱青海馬，入兆渭川熊。","固是符真宰，徒勞讓化工。","鳳池春瀲豔，雞樹曉曈曨。","願守三章約，還期九譯通。","薰琴調大舜，寶瑟和神農。","慷慨資元老，周旋值狡童。","仲尼羞問陣，魏絳喜和戎。","欵欵將除蠧，孜孜欲達聰。","所求因渭濁，安肯與雷同。","物議將調鼎，君恩忽賜弓。","開吳相上下，全蜀占西東。","銳卒魚懸餌，豪胥鳥在籠。","疲民呼杜母，隣國仰羊公。","置驛推東道，安禪合北宗。","嘉賓增重價，上士悟真空。","扇舉遮王導，樽開見孔融。","煙飛愁舞罷，塵定惜歌終。","岸柳兼池綠，園花映燭紅。","未曾周顗醉，轉覺季之恭。","繫滯喧人望，便蕃屬聖衷。","天書何日降，庭燎幾時烘。","早歲乖投刺，今晨幸發蒙。","遠途哀跛鼈，薄藝獎雕蟲。","故事曾尊隗，前修有薦雄。","終須煩刻畫，聊擬更磨礲。","蠻嶺晴留雪，巴江晚帶楓。","營巢憐越燕，裂帛待燕鴻。","自苦誠先檗，長飄不後蓬。","容華雖少健，思緒即悲翁。","感激淮山館，優游碣石宮。","待公三入相，丕祚始無窮。"]', '["家擅無雙譽，朝居第一功。","四时當首夏，八節應條风。","滌濯臨清濟，巉巖倚碧嵩。","鲍壺冰皎潔，王佩玉丁东。","处劇張京兆，通經戴侍中。","將星臨迥夜，卿月丽層穹。","下令銷秦盜，高談破宋聾。","含霜太山竹，拂霧嶧陽桐。","乐道乾知退，當官蹇匪躬。","服箱青海马，入兆渭川熊。","固是符真宰，徒勞讓化工。","鳳池春瀲豔，雞樹晓曈曨。","願守三章約，還期九譯通。","薰琴調大舜，寶瑟和神農。","慷慨資元老，周旋值狡童。","仲尼羞问陣，魏絳喜和戎。","欵欵將除蠧，孜孜欲達聰。","所求因渭濁，安肯與雷同。","物議將調鼎，君恩忽賜弓。","开吳相上下，全蜀占西东。","銳卒鱼懸餌，豪胥鸟在籠。","疲民呼杜母，隣国仰羊公。","置驛推东道，安禪合北宗。","嘉賓增重價，上士悟真空。","扇舉遮王導，樽开见孔融。","煙飞愁舞罷，塵定惜歌終。","岸柳兼池綠，园花映燭紅。","未曾周顗醉，轉覺季之恭。","繫滯喧人望，便蕃屬聖衷。","天书何日降，庭燎幾时烘。","早歲乖投刺，今晨幸發蒙。","远途哀跛鼈，薄藝獎雕蟲。","故事曾尊隗，前修有薦雄。","終須煩刻畫，聊擬更磨礲。","蠻嶺晴留雪，巴江晚带楓。","營巢怜越燕，裂帛待燕鴻。","自苦誠先檗，长飄不後蓬。","容华雖少健，思緒即悲翁。","感激淮山館，優游碣石宮。","待公三入相，丕祚始無窮。"]', '诗', 'shi', '', NULL, '今月二日不自量度輒以詩一首四十韻干凟尊嚴伏蒙仁恩俯賜披覽獎踰其實情溢於辭顧惟疎蕪曷用酬戴輒復五言四十韻詩獻上亦詩人詠嘆不足之義也 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e21d335-a523-4b60-b2d4-6d198f86c88d', '驕兒詩', '驕兒诗', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["衮師我驕兒，美秀乃無匹。","文葆未周晬，固已知六七。","四歲知名姓，眼不視棃栗。","交朋頗窺觀，謂是丹穴物。","前朝尚器貌，流品方第一。","不然神仙姿，不爾燕鶴骨。","安得此相謂，欲慰衰朽質。","青春妍和月，朋戲渾甥姪。","繞堂復穿林，沸若金鼎溢。","門有長者來，造次請先出。","客前問所須，含意下吐實。","歸來學客面，䦱敗秉爺笏。","或謔張飛胡，或笑鄧艾吃。","豪鷹毛崱屴，猛馬氣佶傈。","截得青篔簹，騎走恣唐突。","忽復學參軍，按聲喚蒼鶻。","又復紗燈旁，稽首禮夜佛。","仰鞭罥蛛網，俯首飲花蜜。","欲爭蛺蝶輕，未謝柳絮疾。","階前逢阿姊，六甲頗輸失。","凝走弄香奩，拔脫金屈[戌]。","抱持多反側，威怒不可律。","曲躬牽牕網，衉唾拭琴漆。","有時看臨書，挺立不動膝。","古錦請裁衣，玉軸亦欲乞。","請爺書春勝，春勝宜春日。","芭蕉斜卷箋，辛夷低過筆。","爺昔好讀書，懇苦自著述。","顦顇欲四十，無肉畏蚤虱。","兒慎勿學爺，讀書求甲乙。","穰苴司馬法，張良黃石術。","便爲帝王師，不假更纖悉。","況今西與北，羌戎正狂悖。","誅赦兩未成，將養如痼疾。","兒當速成大，探雛入虎穴。","當爲萬戶侯，勿守一經帙。"]', '["衮師我驕兒，美秀乃無匹。","文葆未周晬，固已知六七。","四歲知名姓，眼不視棃栗。","交朋頗窺观，謂是丹穴物。","前朝尚器貌，流品方第一。","不然神仙姿，不爾燕鹤骨。","安得此相謂，欲慰衰朽質。","青春妍和月，朋戲渾甥姪。","繞堂复穿林，沸若金鼎溢。","门有长者来，造次請先出。","客前问所須，含意下吐實。","归来学客面，䦱敗秉爺笏。","或謔張飞胡，或笑鄧艾吃。","豪鷹毛崱屴，猛马氣佶傈。","截得青篔簹，騎走恣唐突。","忽复学參軍，按声喚蒼鶻。","又复紗灯旁，稽首禮夜佛。","仰鞭罥蛛網，俯首饮花蜜。","欲爭蛺蝶轻，未謝柳絮疾。","階前逢阿姊，六甲頗輸失。","凝走弄香奩，拔脫金屈[戌]。","抱持多反側，威怒不可律。","曲躬牽牕網，衉唾拭琴漆。","有时看臨书，挺立不动膝。","古錦請裁衣，玉軸亦欲乞。","請爺书春勝，春勝宜春日。","芭蕉斜卷箋，辛夷低過笔。","爺昔好读书，懇苦自著述。","顦顇欲四十，無肉畏蚤虱。","兒慎勿学爺，读书求甲乙。","穰苴司马法，張良黄石術。","便爲帝王師，不假更纖悉。","況今西與北，羌戎正狂悖。","誅赦兩未成，將養如痼疾。","兒當速成大，探雛入虎穴。","當爲万戶侯，勿守一經帙。"]', '诗', 'shi', '', NULL, '驕兒詩 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ba27c8-91e7-4d58-b85a-99cd049552a8', '行次西郊作一百韻', '行次西郊作一百韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蛇年建午月，我自梁還秦。","南下大散關，北濟渭之濱。","草木半舒坼，不類冰雪晨。","又若夏苦熱，燋卷無芳津。","高田長檞櫪，下田長荆榛。","農具棄道旁，饑牛死空墩。","依依過村落，十室無一存。","存者皆面啼，無衣可迎賓。","始若畏人問，及門還具陳。","右輔田疇薄，斯民常苦貧。","伊昔稱樂土，所賴牧伯仁。","官清若冰玉，吏善如六親。","生兒不遠征，生女事四隣。","濁酒盈瓦缶，爛穀堆荆囷。","健兒庇旁婦，衰翁舐童孫。","況自貞觀後，命官多儒臣。","例以賢牧伯，徵人司陶鈞。","降及開元中，姦邪撓經綸。","晉公忌此事，多録邊將勳。","因令猛毅輩，雜牧升平民。","中原遂多故，除授非至尊。","或出倖臣輩，或由帝戚恩。","中原困屠解，奴隸厭肥豚。","皇子棄不乳，椒房抱羌渾。","重賜竭中國，強兵臨北邊。","控弦二十萬，長臂皆如猿。","皇都三千里，來往同雕鳶。","五里一換馬，十里一開筵。","指顧動白日，煖熱迴蒼旻。","公卿辱嘲叱，唾棄如糞丸。","大朝會萬方，天子正臨軒。","綵旂轉初旭，玉座當祥煙。","金障既特設，珠簾亦高褰。","捋須蹇不顧，坐在御榻前。","忤者死艱屨，附之升頂顛。","華侈矜遞衒，豪俊相併吞。","因失生惠養，漸見徵求頻。","奚寇西北來，揮霍如天翻。","是時正忘戰，重兵多在邊。","列城遶長河，平明插旗旛。","但聞虜騎入，不見漢兵屯。","大婦抱兒哭，小婦攀車轓。","生小太平年，不識夜閉門。","少壯盡點行，疲老守空村。","生分作死誓，揮淚連秋雲。","廷臣例麞怯，諸將如羸奔。","爲賊掃上陽，捉人送潼關。","玉輦望南斗，未知何日旋。","誠知開闢久，遘此雲雷屯。","送者問鼎大，存者要高官。","搶攘互間諜，孰辨梟與鸞。","千馬無返轡，萬車無還轅。","城空鼠雀死，人去豺狼喧。","南資竭吳越，西費失河源。","因令左藏庫，摧毀惟空垣。","如人當一身，有左無右邊。","筋體半痿痺，肘腋生臊膻。","列聖蒙此恥，含懷不能宣。","謀臣拱手立，相戒無敢先。","萬國困杼軸，內庫無金錢。","健兒立霜雪，腹歉衣裳單。","饋餉多過時，高估銅與鉛。","山東望河北，爨煙猶相聯。","朝廷不暇給，辛苦無半年。","行人搉行資，居者稅屋椽。","中間遂作梗，狼籍用戈鋋。","臨門送節制，以錫通天班。","破者以族滅，存者尚遷延。","禮數異君父，羈糜如羌零。","直求輸赤誠，所望大體全。","巍巍政事堂，宰相厭八珍。","敢問下執事，今誰掌其權。","瘡疽幾十載，不敢扶其根。","國蹙賦更重，人稀役彌繁。","近年牛醫兒，城社更扳援。","盲目把大斾，處此京西藩。","樂禍忘怨敵，樹黨多狂狷。","生爲人所憚，死非人所憐。","快刀斷其頭，列若猪牛懸。","鳳翔三百里，兵馬如黃巾。","夜半軍牒來，屯兵萬五千。","鄉里駭供億，老少相扳牽。","兒孫生未孩，棄之無慘顏。","不復議所適，但欲死山間。","爾來又三歲，甘澤不及春。","盜賊亭午起，問誰多窮民。","節使殺亭吏，捕之恐無因。","咫尺不相見，旱久多黃塵。","官健腰佩弓，自言爲官巡。","常恐值荒迥，此輩還射人。","媿客問本末，願客無因循。","郿塢抵陳倉，此地忌黃昏。","我聽此言罷，冤憤如相焚。","昔聞舉一會，羣盜爲之奔。","又聞理與亂，在人不在天。","我願爲此事，君前剖心肝。","叩頭出鮮血，滂沱污紫宸。","九重黯已隔，涕泗空沾脣。","使典作尚書，廝養爲將軍。","慎勿道此言，此言未忍聞。"]', '["蛇年建午月，我自梁還秦。","南下大散关，北濟渭之濱。","草木半舒坼，不類冰雪晨。","又若夏苦熱，燋卷無芳津。","高田长檞櫪，下田长荆榛。","農具棄道旁，饑牛死空墩。","依依過村落，十室無一存。","存者皆面啼，無衣可迎賓。","始若畏人问，及门還具陳。","右輔田疇薄，斯民常苦貧。","伊昔稱乐土，所賴牧伯仁。","官清若冰玉，吏善如六親。","生兒不远征，生女事四隣。","濁酒盈瓦缶，爛穀堆荆囷。","健兒庇旁婦，衰翁舐童孫。","況自貞观後，命官多儒臣。","例以賢牧伯，徵人司陶鈞。","降及开元中，姦邪撓經綸。","晉公忌此事，多録邊將勳。","因令猛毅輩，杂牧升平民。","中原遂多故，除授非至尊。","或出倖臣輩，或由帝戚恩。","中原困屠解，奴隸厭肥豚。","皇子棄不乳，椒房抱羌渾。","重賜竭中国，強兵臨北邊。","控弦二十万，长臂皆如猿。","皇都三千里，来往同雕鳶。","五里一換马，十里一开筵。","指顧动白日，煖熱迴蒼旻。","公卿辱嘲叱，唾棄如糞丸。","大朝會万方，天子正臨軒。","綵旂轉初旭，玉座當祥煙。","金障既特設，珠簾亦高褰。","捋須蹇不顧，坐在御榻前。","忤者死艱屨，附之升頂顛。","华侈矜遞衒，豪俊相併吞。","因失生惠養，漸见徵求頻。","奚寇西北来，揮霍如天翻。","是时正忘戰，重兵多在邊。","列城遶长河，平明插旗旛。","但闻虜騎入，不见漢兵屯。","大婦抱兒哭，小婦攀车轓。","生小太平年，不識夜閉门。","少壯尽点行，疲老守空村。","生分作死誓，揮泪連秋云。","廷臣例麞怯，諸將如羸奔。","爲賊掃上陽，捉人送潼关。","玉輦望南斗，未知何日旋。","誠知开闢久，遘此云雷屯。","送者问鼎大，存者要高官。","搶攘互间諜，孰辨梟與鸾。","千马無返轡，万车無還轅。","城空鼠雀死，人去豺狼喧。","南資竭吳越，西費失河源。","因令左藏庫，摧毀惟空垣。","如人當一身，有左無右邊。","筋體半痿痺，肘腋生臊膻。","列聖蒙此恥，含懷不能宣。","謀臣拱手立，相戒無敢先。","万国困杼軸，內庫無金錢。","健兒立霜雪，腹歉衣裳單。","饋餉多過时，高估銅與鉛。","山东望河北，爨煙猶相聯。","朝廷不暇給，辛苦無半年。","行人搉行資，居者稅屋椽。","中间遂作梗，狼籍用戈鋋。","臨门送節制，以錫通天班。","破者以族滅，存者尚遷延。","禮數異君父，羈糜如羌零。","直求輸赤誠，所望大體全。","巍巍政事堂，宰相厭八珍。","敢问下執事，今誰掌其權。","瘡疽幾十載，不敢扶其根。","国蹙賦更重，人稀役彌繁。","近年牛醫兒，城社更扳援。","盲目把大斾，处此京西藩。","乐禍忘怨敵，樹黨多狂狷。","生爲人所憚，死非人所怜。","快刀斷其头，列若猪牛懸。","鳳翔三百里，兵马如黄巾。","夜半軍牒来，屯兵万五千。","乡里駭供億，老少相扳牽。","兒孫生未孩，棄之無慘顏。","不复議所適，但欲死山间。","爾来又三歲，甘澤不及春。","盜賊亭午起，问誰多窮民。","節使殺亭吏，捕之恐無因。","咫尺不相见，旱久多黄塵。","官健腰佩弓，自言爲官巡。","常恐值荒迥，此輩還射人。","媿客问本末，願客無因循。","郿塢抵陳倉，此地忌黄昏。","我听此言罷，冤憤如相焚。","昔闻舉一會，羣盜爲之奔。","又闻理與亂，在人不在天。","我願爲此事，君前剖心肝。","叩头出鲜血，滂沱污紫宸。","九重黯已隔，涕泗空沾脣。","使典作尚书，廝養爲將軍。","慎勿道此言，此言未忍闻。"]', '诗', 'shi', '', NULL, '行次西郊作一百韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac05039-922b-4847-85d5-2fc051753b30', '井泥四十韻', '井泥四十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["皇都依仁里，西北有高齋。","昨日主人氏，治井堂西陲。","工人三五輩，輦出土與泥。","到水不數尺，積共庭樹齊。","他日井甃畢，用土益作堤。","曲隨林掩映，繚以池周迴。","下去冥寞穴，上承雨露滋。","寄辭別地脉，因言謝泉扉。","升騰不自意，疇昔忽已乖。","伊余掉行鞅，行行來自西。","一日下馬到，此時芳草萋。","四面多好樹，旦暮雲霞姿。","晚落花滿地，幽鳥鳴何枝。","蘿幄既已薦，山樽亦可開。","待得孤月上，如與佳人來。","因茲感物理，惻愴平生懷。","茫茫此羣品，不定輪與蹄。","喜得舜可禪，不以瞽瞍疑。","禹竟代舜立，其父吁咈哉。","嬴氏幷六合，所來因不韋。","漢祖把左契，自言一布衣。","當塗佩國璽，本乃黃門攜。","長戟亂中原，何妨起戎氐。","不獨帝王耳，臣下亦如斯。","伊尹佐興王，不藉漢父資。","蟠溪老釣叟，坐爲周之師。","屠狗興販繒，突起定傾危。","長沙啓封土，豈是出程姬。","帝問主人翁，有自賣珠兒。","武昌昔男子，老苦爲人妻。","蜀王有遺魄，今在林中啼。","淮南雞舐藥，翻向雲中飛。","大鈞運羣有，難以一理推。","顧於冥冥內，爲問秉者誰。","我恐更萬世，此事愈云爲。","猛虎與雙翅，更以角副之。","鳳凰不五色，聯翼上雞棲。","我欲秉鈞者，朅來與我偕。","浮雲不相顧，寥泬誰爲梯。","悒怏夜將半，但歌井中泥。"]', '["皇都依仁里，西北有高斋。","昨日主人氏，治井堂西陲。","工人三五輩，輦出土與泥。","到水不數尺，積共庭樹齊。","他日井甃畢，用土益作堤。","曲隨林掩映，繚以池周迴。","下去冥寞穴，上承雨露滋。","寄辞別地脉，因言謝泉扉。","升腾不自意，疇昔忽已乖。","伊余掉行鞅，行行来自西。","一日下马到，此时芳草萋。","四面多好樹，旦暮云霞姿。","晚落花满地，幽鸟鳴何枝。","蘿幄既已薦，山樽亦可开。","待得孤月上，如與佳人来。","因茲感物理，惻愴平生懷。","茫茫此羣品，不定輪與蹄。","喜得舜可禪，不以瞽瞍疑。","禹竟代舜立，其父吁咈哉。","嬴氏幷六合，所来因不韋。","漢祖把左契，自言一布衣。","當塗佩国璽，本乃黄门携。","长戟亂中原，何妨起戎氐。","不独帝王耳，臣下亦如斯。","伊尹佐兴王，不藉漢父資。","蟠溪老釣叟，坐爲周之師。","屠狗兴販繒，突起定傾危。","长沙啓封土，豈是出程姬。","帝问主人翁，有自賣珠兒。","武昌昔男子，老苦爲人妻。","蜀王有遺魄，今在林中啼。","淮南雞舐藥，翻向云中飞。","大鈞運羣有，难以一理推。","顧於冥冥內，爲问秉者誰。","我恐更万世，此事愈云爲。","猛虎與雙翅，更以角副之。","鳳凰不五色，聯翼上雞棲。","我欲秉鈞者，朅来與我偕。","浮云不相顧，寥泬誰爲梯。","悒怏夜將半，但歌井中泥。"]', '诗', 'shi', '', NULL, '井泥四十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd263b00-f520-4266-8d16-5e0e19d8160d', '夜思', '夜思', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["銀箭耿寒漏，金釭凝夜光。","綵鸞空自舞，別燕不相將。","寄恨一尺素，含情雙玉璫。","會前猶月在，去後始宵長。","往事經春物，前期託報章。","永令虛粲枕，長不掩蘭房。","覺動迎猜影，疑來浪認香。","鶴應聞露警，蜂亦爲花忙。","古有陽臺夢，今多下蔡倡。","何爲薄冰雪，消瘦滯非鄉。"]', '["銀箭耿寒漏，金釭凝夜光。","綵鸾空自舞，別燕不相將。","寄恨一尺素，含情雙玉璫。","會前猶月在，去後始宵长。","往事經春物，前期託報章。","永令虛粲枕，长不掩蘭房。","覺动迎猜影，疑来浪認香。","鹤應闻露警，蜂亦爲花忙。","古有陽台梦，今多下蔡倡。","何爲薄冰雪，消瘦滯非乡。"]', '诗', 'shi', '', NULL, '夜思 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b33f8ef9-fbf0-492f-8437-88ed7d4b5e44', '思賢頓', '思賢頓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["內殿張弦管，中原絕鼓鼙。","舞成青海馬，鬬殺汝南雞。","不見華胥夢，空聞下蔡迷。","宸襟他日淚，薄暮望賢西。"]', '["內殿張弦管，中原絕鼓鼙。","舞成青海马，鬬殺汝南雞。","不见华胥梦，空闻下蔡迷。","宸襟他日泪，薄暮望賢西。"]', '诗', 'shi', '', NULL, '思賢頓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dffd98b-0cfe-4376-9ece-658a111877a7', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萬里風波一葉舟，憶歸初罷更夷猶。","碧江地沒元相引，黃鶴沙邊亦少留。","益德冤魂終報主，阿童高義鎮橫秋。","人生豈得長無謂，懷古思鄉共白頭。"]', '["万里风波一葉舟，憶归初罷更夷猶。","碧江地沒元相引，黄鹤沙邊亦少留。","益德冤魂終報主，阿童高義鎮橫秋。","人生豈得长無謂，懷古思乡共白头。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2e28da-a8d4-4f75-9d5d-b3a3beddb628', '有懷在蒙飛卿', '有懷在蒙飞卿', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["薄宦頻移疾，當年久索居。","哀同庚開府，瘦極沈尚書。","城綠新陰遠，江清返照虛。","所思惟翰墨，從古待雙魚。"]', '["薄宦頻移疾，當年久索居。","哀同庚开府，瘦極沈尚书。","城綠新陰远，江清返照虛。","所思惟翰墨，從古待雙鱼。"]', '诗', 'shi', '', NULL, '有懷在蒙飛卿 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4f0808-2ef3-4917-a41c-e78808ed69f6', '春深脫衣', '春深脫衣', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["睥睨江鴉集，堂皇海燕過。","減衣憐蕙若，展帳動煙波。","日烈憂花甚，風長奈柳何。","陳遵容易學，身世醉時多。"]', '["睥睨江鴉集，堂皇海燕過。","減衣怜蕙若，展帳动煙波。","日烈憂花甚，风长奈柳何。","陳遵容易学，身世醉时多。"]', '诗', 'shi', '', NULL, '春深脫衣 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32f5a08-5e49-4772-a0fa-3a674e74d406', '懷求古翁', '懷求古翁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["何時粉署仙，傲兀逐戎旃。","關塞猶傳箭，江湖莫繫船。","欲收棊子醉，竟把釣車眠。","謝朓真堪憶，多才不忌前。"]', '["何时粉署仙，傲兀逐戎旃。","关塞猶傳箭，江湖莫繫船。","欲收棊子醉，竟把釣车眠。","謝朓真堪憶，多才不忌前。"]', '诗', 'shi', '', NULL, '懷求古翁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431a83cf-ac5f-4faf-8e21-ef3e486e69e2', '五月六日夜憶往歲秋與徹師同宿', '五月六日夜憶往歲秋與徹師同宿', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紫閣相逢處，丹巖議宿時。","墮蟬翻敗葉，棲鳥定寒枝。","萬里飄流遠，三年問訊遲。","炎方憶初地，頻夢碧琉璃。"]', '["紫閣相逢处，丹巖議宿时。","墮蟬翻敗葉，棲鸟定寒枝。","万里飄流远，三年问訊遲。","炎方憶初地，頻梦碧琉璃。"]', '诗', 'shi', '', NULL, '五月六日夜憶往歲秋與徹師同宿 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd807c4-684b-47c2-b53e-e5e3f394ec0f', '城上', '城上', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["有客虛投筆，無憀獨上城。","沙禽失侶遠，江樹著陰輕。","邊遽稽天討，軍須竭地征。","賈生游刃極，作賦又論兵。"]', '["有客虛投笔，無憀独上城。","沙禽失侶远，江樹著陰轻。","邊遽稽天討，軍須竭地征。","賈生游刃極，作賦又論兵。"]', '诗', 'shi', '', NULL, '城上 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ee948c-da09-4249-8e0d-669cad8206c0', '如有', '如有', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["如有瑤臺客，相難復索歸。","芭蕉開綠扇，菡萏薦紅衣。","浦外傳光遠，煙中結響微。","良宵一寸焰，回首是重幃。"]', '["如有瑤台客，相难复索归。","芭蕉开綠扇，菡萏薦紅衣。","浦外傳光远，煙中結响微。","良宵一寸焰，回首是重幃。"]', '诗', 'shi', '', NULL, '如有 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7b2dae-0164-4177-8bcc-c648dc17f470', '朱槿花二首 一', '朱槿花二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蓮後紅何患，梅先白莫誇。","纔飛建章火，又落赤城霞。","不卷錦步障，未登油壁車。","日西相對罷，休澣向天涯。"]', '["蓮後紅何患，梅先白莫誇。","纔飞建章火，又落赤城霞。","不卷錦步障，未登油壁车。","日西相对罷，休澣向天涯。"]', '诗', 'shi', '', NULL, '朱槿花二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d792bdc2-3729-4337-9adb-c0a6cabaf833', '朱槿花二首 二', '朱槿花二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["勇多侵路去，恨有礙燈還。","嗅自微微白，看成沓沓殷。","坐疑忘物外，歸去有簾間。","君問傷春句，千辭不可刪。"]', '["勇多侵路去，恨有礙灯還。","嗅自微微白，看成沓沓殷。","坐疑忘物外，归去有簾间。","君问傷春句，千辞不可刪。"]', '诗', 'shi', '', NULL, '朱槿花二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa83495-341c-4eb8-82b1-a4b52710d331', '寓懷', '寓懷', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["綵鸞餐顥氣，威鳳入卿雲。","長養三清境，追隨五帝君。","煙波遺汲汲，矰繳任云云。","下界圍黃道，前程合紫氛。","金書惟是見，玉管不勝聞。","草爲迴生種，香緣却死熏。","海明三島見，天迥九江分。","搴樹無勞援，神禾豈用耘。","鬬龍風結陣，惱鶴露成文。","漢嶺霜何早，秦宮日易曛。","星機拋密緒，月杵散靈氛。","陽鳥西南下，相思不及羣。"]', '["綵鸾餐顥氣，威鳳入卿云。","长養三清境，追隨五帝君。","煙波遺汲汲，矰繳任云云。","下界圍黄道，前程合紫氛。","金书惟是见，玉管不勝闻。","草爲迴生種，香緣却死熏。","海明三島见，天迥九江分。","搴樹無勞援，神禾豈用耘。","鬬龙风結陣，惱鹤露成文。","漢嶺霜何早，秦宮日易曛。","星機拋密緒，月杵散靈氛。","陽鸟西南下，相思不及羣。"]', '诗', 'shi', '', NULL, '寓懷 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b5e021-5de9-4133-8e51-f36db9874431', '木蘭', '木蘭', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["二月二十二，木蘭開坼初。","初當新病酒，復自久離居。","愁絕更傾國，驚新聞遠書。","紫絲何日障，油壁幾時車。","弄粉知傷重，調紅或有餘。","波痕空映襪，煙態不勝裾。","桂嶺含芳遠，蓮塘屬意疎。","瑤姬與神女，長短定何如。"]', '["二月二十二，木蘭开坼初。","初當新病酒，复自久離居。","愁絕更傾国，驚新闻远书。","紫絲何日障，油壁幾时车。","弄粉知傷重，調紅或有餘。","波痕空映襪，煙態不勝裾。","桂嶺含芳远，蓮塘屬意疎。","瑤姬與神女，长短定何如。"]', '诗', 'shi', '', NULL, '木蘭 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59643cd3-cf82-453a-a932-cf793f8dc196', '細雨成詠獻尚書河東公', '細雨成詠獻尚书河东公', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["灑砌聽來響，卷簾看已迷。","江間風暫定，雲外日應西。","稍稍落蝶粉，班班融燕泥。","颭萍初過沼，重柳更緣堤。","必擬和殘漏，寧無晦暝鼙。","半將花漠漠，全共草萋萋。","猿別方長嘯，鳥驚始獨棲。","府公能八詠，聊且續新題。"]', '["灑砌听来响，卷簾看已迷。","江间风暫定，云外日應西。","稍稍落蝶粉，班班融燕泥。","颭萍初過沼，重柳更緣堤。","必擬和殘漏，寧無晦暝鼙。","半將花漠漠，全共草萋萋。","猿別方长嘯，鸟驚始独棲。","府公能八詠，聊且續新題。"]', '诗', 'shi', '', NULL, '細雨成詠獻尚書河東公 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622626e1-e3ff-4450-b14a-cb5ead3f5954', '病中聞河東公樂營置酒口占寄上', '病中闻河东公乐營置酒口占寄上', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["聞駐行春斾，中途賞物華。","緣憂武昌柳，遂憶洛陽花。","嵇鶴元無對，荀龍不在誇。","只將滄海月，長壓赤城霞。","興欲傾燕館，歡終到習家。","風長應側帽，路隘豈容車。","樓迥波窺錦，窗虛日弄紗。","鎖門金了鳥，展障玉鴉叉。","舞妙從兼楚，歌能莫雜巴。","必投潘岳果，誰摻禰衡撾。","刻燭當時忝，傳杯此夕賒。","可憐漳浦臥，愁緒獨如麻。"]', '["闻駐行春斾，中途賞物华。","緣憂武昌柳，遂憶洛陽花。","嵇鹤元無对，荀龙不在誇。","只將滄海月，长壓赤城霞。","兴欲傾燕館，歡終到習家。","风长應側帽，路隘豈容车。","楼迥波窺錦，窗虛日弄紗。","鎖门金了鸟，展障玉鴉叉。","舞妙從兼楚，歌能莫杂巴。","必投潘岳果，誰摻禰衡撾。","刻燭當时忝，傳杯此夕賒。","可怜漳浦臥，愁緒独如麻。"]', '诗', 'shi', '', NULL, '病中聞河東公樂營置酒口占寄上 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24bec9f3-8073-4343-a5d1-37781d4c3aad', '回中牡丹爲雨所敗二首 一', '回中牡丹爲雨所敗二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["下苑他年未可追，西州今日忽相期。","水亭暮雨寒猶在，羅薦春香暖不知。","舞蝶殷勤收落蘂，佳人惆悵臥遙帷。","章臺街裏芳菲伴，且問宮腰損幾枝。"]', '["下苑他年未可追，西州今日忽相期。","水亭暮雨寒猶在，羅薦春香暖不知。","舞蝶殷勤收落蘂，佳人惆悵臥遙帷。","章台街裏芳菲伴，且问宮腰損幾枝。"]', '诗', 'shi', '', NULL, '回中牡丹爲雨所敗二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e04b3e9-ca54-4939-abb4-acf10c3e8ea6', '回中牡丹爲雨所敗二首 二', '回中牡丹爲雨所敗二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["浪笑榴花不及春，先期零落更愁人。","玉盤迸淚傷心數，錦瑟驚絃破夢頻。","萬里重陰非舊圃，一年生意屬流塵。","前溪舞罷君迴顧，併覺今朝粉態新。"]', '["浪笑榴花不及春，先期零落更愁人。","玉盤迸泪傷心數，錦瑟驚絃破梦頻。","万里重陰非旧圃，一年生意屬流塵。","前溪舞罷君迴顧，併覺今朝粉態新。"]', '诗', 'shi', '', NULL, '回中牡丹爲雨所敗二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a7e5bf-e4f3-49b5-a134-9d59c4451f50', '擬意', '擬意', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["悵望逢張女，遲迴送阿侯。","空看小垂手，忍問大刀頭。","妙選茱萸帳，平居翡翠樓。","雲屏不取暖，月扇未遮羞。","上掌真何有，傾城豈自由。","楚妃交薦枕，漢后共藏𩰘。","夫向羊車覓，男從鳳穴求。","書成祓禊帖，唱殺畔牢愁。","夜杵鳴江練，春刀解若榴。","象牀穿幰網，犀帖釘窗油。","仁壽遺明鏡，陳倉拂綵毬。","真防舞如意，佯蓋臥箜篌。","濯錦桃花水，濺裙杜若洲。","魚兒懸寶劒，燕子合金甌。","銀箭催搖落，華筵慘去留。","幾時銷薄怒，從此抱離憂。","帆落啼猿峽，樽開畫鷁舟。","急絃腸對斷，翦蠟淚爭流。","璧馬誰能帶，金蟲不復收。","銀河撲醉眼，珠串咽歌喉。","去夢隨川后，來風貯石郵。","蘭叢銜露重，榆莢點星稠。","解佩無遺迹，凌波有舊游。","曾來十九首，私讖詠牽牛。"]', '["悵望逢張女，遲迴送阿侯。","空看小垂手，忍问大刀头。","妙選茱萸帳，平居翡翠楼。","云屏不取暖，月扇未遮羞。","上掌真何有，傾城豈自由。","楚妃交薦枕，漢后共藏𩰘。","夫向羊车覓，男從鳳穴求。","书成祓禊帖，唱殺畔牢愁。","夜杵鳴江練，春刀解若榴。","象牀穿幰網，犀帖釘窗油。","仁壽遺明镜，陳倉拂綵毬。","真防舞如意，佯蓋臥箜篌。","濯錦桃花水，濺裙杜若洲。","鱼兒懸寶劒，燕子合金甌。","銀箭催搖落，华筵慘去留。","幾时銷薄怒，從此抱離憂。","帆落啼猿峽，樽开畫鷁舟。","急絃腸对斷，翦蠟泪爭流。","璧马誰能带，金蟲不复收。","銀河撲醉眼，珠串咽歌喉。","去梦隨川后，来风貯石郵。","蘭叢銜露重，榆莢点星稠。","解佩無遺迹，凌波有旧游。","曾来十九首，私讖詠牽牛。"]', '诗', 'shi', '', NULL, '擬意 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea04b546-f35e-4b21-a63d-052a966af2fd', '謝往桂林至彤庭竊詠', '謝往桂林至彤庭竊詠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["辰象森羅正，句陳翊衛寬。","魚龍排百戲，劍佩儼千官。","城禁將開晚，宮深欲曙難。","月輸移枍詣，仙路下欄干。","共賀高禖應，將陳壽酒歡。","金星壓芒角，銀漢轉波瀾。","王母來空闊，羲和上屈盤。","鳳皇傳詔旨，獬廌冠朝端。","造化中台座，威風上將壇。","甘泉猶望幸，早晚冠呼韓。"]', '["辰象森羅正，句陳翊衛寬。","鱼龙排百戲，劍佩儼千官。","城禁將开晚，宮深欲曙难。","月輸移枍詣，仙路下欄干。","共賀高禖應，將陳壽酒歡。","金星壓芒角，銀漢轉波瀾。","王母来空闊，羲和上屈盤。","鳳皇傳詔旨，獬廌冠朝端。","造化中台座，威风上將壇。","甘泉猶望幸，早晚冠呼韓。"]', '诗', 'shi', '', NULL, '謝往桂林至彤庭竊詠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7fcd168-6de6-45a1-a1a4-e11d7ff5a345', '燒香曲', '燒香曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鈿雲蟠蟠牙比魚，孔雀翅尾蛟龍鬚。","漳宮舊樣博山鑪，楚嬌捧笑開芙蕖。","八蠶繭緜小分炷，獸燄微紅隔雲母。","白天月澤寒未冰，金虎含秋向東吐。","玉佩呵光銅照昏，簾波日暮衝斜門。","西來欲上茂陵樹，柏梁已失栽桃魂。","露庭月井大紅氣，輕衫薄細當君意。","蜀殿瓊人伴夜深，金鑾不問殘燈事。","何當巧吹君懷度，襟灰爲土填清露。"]', '["鈿云蟠蟠牙比鱼，孔雀翅尾蛟龙鬚。","漳宮旧樣博山鑪，楚嬌捧笑开芙蕖。","八蠶繭緜小分炷，獸燄微紅隔云母。","白天月澤寒未冰，金虎含秋向东吐。","玉佩呵光銅照昏，簾波日暮衝斜门。","西来欲上茂陵樹，柏梁已失栽桃魂。","露庭月井大紅氣，轻衫薄細當君意。","蜀殿瓊人伴夜深，金鑾不问殘灯事。","何當巧吹君懷度，襟灰爲土填清露。"]', '诗', 'shi', '', NULL, '燒香曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ae2b00-1de4-4748-a751-7db2bd520450', '送從翁東川弘農尚書幕', '送從翁东川弘農尚书幕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昔帝迴沖眷，維皇惻上仁。","三靈迷赤氣，萬彙呌蒼旻。","刊木方隆禹，陞陑始創殷。","夏臺曾圮閉，汜水敢逡巡。","拯溺休規步，防虞要徙薪。","蒸黎今得請，宇宙昨還淳。","纘祖功宜急，貽孫計甚勤。","降災雖代有，稔惡不無因。","宮掖方爲蠱，邊隅忽遘迍。","獻書秦逐客，間諜漢名臣。","北伐將誰使，南征決此辰。","中原重板蕩，玄象失鉤陳。","詰旦違清道，銜枚別紫宸。","茲行殊厭勝，故老遂分新。","去異封於鞏，來寧避處豳。","永嘉幾失墜，宣政遽酸辛。","元子當傳啓，皇孫合授詢。","時非三揖讓，表請再陶鈞。","舊好盟還在，中樞策屢遵。","蒼黃傳國璽，違遠屬車塵。","雛虎如憑怒，漦龍性漫馴。","封崇自何等，流落乃斯民。","逗撓官軍亂，優容敗將頻。","早朝披草莽，夜縋達絲綸。","忘戰追無及，長驅氣益振。","婦言終未易，廟算況非神。","日馭難淹蜀，星旄要定秦。","人心誠未去，天道亦無親。","錦水湔雲浪，黃山掃地春。","斯文虛夢鳥，吾道欲悲麟。","斷續殊鄉淚，存亡滿席珍。","魂銷季羔竇，衣化子張紳。","建議庸何所，通班昔濫臻。","浮生見開泰，獨得詠汀蘋。"]', '["昔帝迴沖眷，維皇惻上仁。","三靈迷赤氣，万彙呌蒼旻。","刊木方隆禹，陞陑始創殷。","夏台曾圮閉，汜水敢逡巡。","拯溺休規步，防虞要徙薪。","蒸黎今得請，宇宙昨還淳。","纘祖功宜急，貽孫計甚勤。","降災雖代有，稔惡不無因。","宮掖方爲蠱，邊隅忽遘迍。","獻书秦逐客，间諜漢名臣。","北伐將誰使，南征決此辰。","中原重板蕩，玄象失鉤陳。","詰旦違清道，銜枚別紫宸。","茲行殊厭勝，故老遂分新。","去異封於鞏，来寧避处豳。","永嘉幾失墜，宣政遽酸辛。","元子當傳啓，皇孫合授詢。","时非三揖讓，表請再陶鈞。","旧好盟還在，中樞策屢遵。","蒼黄傳国璽，違远屬车塵。","雛虎如憑怒，漦龙性漫馴。","封崇自何等，流落乃斯民。","逗撓官軍亂，優容敗將頻。","早朝披草莽，夜縋達絲綸。","忘戰追無及，长驱氣益振。","婦言終未易，廟算況非神。","日馭难淹蜀，星旄要定秦。","人心誠未去，天道亦無親。","錦水湔云浪，黄山掃地春。","斯文虛梦鸟，吾道欲悲麟。","斷續殊乡泪，存亡满席珍。","魂銷季羔竇，衣化子張紳。","建議庸何所，通班昔濫臻。","浮生见开泰，独得詠汀蘋。"]', '诗', 'shi', '', NULL, '送從翁東川弘農尚書幕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b731f233-722f-407b-8754-6a8d84575a04', '晉昌晚歸馬上贈', '晉昌晚归马上贈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["西北朝天路，登臨思上才。","城閑煙草遍，村暗雨雲回。","人豈無端別，猨應有意哀。","征南予更遠，吟斷望鄉臺。"]', '["西北朝天路，登臨思上才。","城闲煙草遍，村暗雨云回。","人豈無端別，猨應有意哀。","征南予更远，吟斷望乡台。"]', '诗', 'shi', '', NULL, '晉昌晚歸馬上贈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9dce4c-57b9-4431-92a2-47166fc5a016', '哭虔州楊侍郎', '哭虔州楊侍郎', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["漢網疎仍漏，齊民困未蘇。","如何大丞相，翻作弛刑徒。","中憲方外易，尹京終就拘。","本矜能弭謗，先議取非辜。","巧有凝脂密，功無一柱扶。","深知獄吏貴，幾迫季冬誅。","呌帝青天闊，辭家白日晡。","流亡誠不弔，神理若爲誣。","在昔恩知忝，諸生禮秩殊。","入韓非劒客，過趙受鉗奴。","楚水招魂遠，邙山卜宅孤。","甘心親垤蟻，旋踵戮城狐。","陰騭今如此，天災未可無。","莫憑牲玉請，便望救焦枯。"]', '["漢網疎仍漏，齊民困未蘇。","如何大丞相，翻作弛刑徒。","中憲方外易，尹京終就拘。","本矜能弭謗，先議取非辜。","巧有凝脂密，功無一柱扶。","深知獄吏貴，幾迫季冬誅。","呌帝青天闊，辞家白日晡。","流亡誠不弔，神理若爲誣。","在昔恩知忝，諸生禮秩殊。","入韓非劒客，過趙受鉗奴。","楚水招魂远，邙山卜宅孤。","甘心親垤蟻，旋踵戮城狐。","陰騭今如此，天災未可無。","莫憑牲玉請，便望救焦枯。"]', '诗', 'shi', '', NULL, '哭虔州楊侍郎 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb698f4-f471-40fb-91b9-de88d62e4b26', '寄太原盧司空三十韻', '寄太原盧司空三十韻', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["隋艦臨淮甸，唐旗出井陘。","斷鰲搘四柱，卓馬濟三靈。","祖業隆盤古，孫謀復大庭。","從來師俊傑，可以煥丹青。","舊族開東岳，雄圖奮北溟。","邪同獬廌觸，樂伴鳳凰聽。","酣戰仍揮日，降妖亦鬬霆。","將軍功不伐，叔舅德惟馨。","雞塞誰生事，狼煙不暫停。","擬填滄海鳥，敢競太陽螢。","內草纔傳詔，前茅已勒銘。","那勞出師表，盡入大荒經。","德水縈長帶，陰山繞畫屏。","秖憂非綮肯，未覺有膻腥。","保佐資沖漠，扶持在杳冥。","乃心防暗室，華髪稱明廷。","按甲神初靜，揮戈思欲醒。","羲之當妙選，孝若近歸寧。","月色來侵幌，詩成有轉櫺。","羅含黃菊宅，柳惲白蘋汀。","神物龜酬孔，僊才鶴姓丁。","西山童子藥，南極老人星。","自頃徒窺管，於今媿挈瓶。","何由叨末席，還得叩玄扃。","莊叟虛悲雁，終童漫識艇。","幕中雖策畫，劒外且伶俜。","俁俁行忘止，鰥鰥臥不瞑。","身應瘠於魯，淚欲溢爲榮。","禹貢思金鼎，堯圖憶土鉶。","公乎來入相，王欲駕云亭。"]', '["隋艦臨淮甸，唐旗出井陘。","斷鰲搘四柱，卓马濟三靈。","祖業隆盤古，孫謀复大庭。","從来師俊傑，可以煥丹青。","旧族开东岳，雄圖奮北溟。","邪同獬廌觸，乐伴鳳凰听。","酣戰仍揮日，降妖亦鬬霆。","將軍功不伐，叔舅德惟馨。","雞塞誰生事，狼煙不暫停。","擬填滄海鸟，敢競太陽螢。","內草纔傳詔，前茅已勒銘。","那勞出師表，尽入大荒經。","德水縈长带，陰山繞畫屏。","秖憂非綮肯，未覺有膻腥。","保佐資沖漠，扶持在杳冥。","乃心防暗室，华髪稱明廷。","按甲神初静，揮戈思欲醒。","羲之當妙選，孝若近归寧。","月色来侵幌，诗成有轉櫺。","羅含黄菊宅，柳惲白蘋汀。","神物龟酬孔，僊才鹤姓丁。","西山童子藥，南極老人星。","自頃徒窺管，於今媿挈瓶。","何由叨末席，還得叩玄扃。","莊叟虛悲雁，終童漫識艇。","幕中雖策畫，劒外且伶俜。","俁俁行忘止，鰥鰥臥不瞑。","身應瘠於魯，泪欲溢爲榮。","禹貢思金鼎，堯圖憶土鉶。","公乎来入相，王欲駕云亭。"]', '诗', 'shi', '', NULL, '寄太原盧司空三十韻 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('410b6c68-3226-47ea-a83c-c93f648d5213', '安平公詩', '安平公诗', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["丈人博陵王名家，憐我總角稱才華。","華州留語曉至暮，高聲喝吏放兩衙。","明朝騎馬出城外，送我習業南山阿。","仲子延岳年十六，面如白玉欹烏紗。","其弟炳章猶兩丱，瑤林瓊樹含奇花。","陳留阮家諸侄秀，邐迤出拜何駢羅。","府中從事杜與李，麟角虎翅相過摩。","清詞孤韻有歌響，擊觸鐘磬鳴環珂。","三月石堤凍銷釋，東風開花滿陽坡。","時禽得伴戲新木，其聲尖咽如鳴梭。","公時載酒領從事，踴躍鞍馬來相過。","仰看樓殿撮清漢，坐視世界如恒沙。","面熱脚掉互登陟，青雲表柱白雲崖。","一百八句在貝葉，三十三天長雨花。","長者子來輒獻蓋，辟支佛去空留鞾。","公時受詔鎮東魯，遣我草詔隨車牙。","顧我下筆即千字，疑我讀書傾五車。","嗚嘑大賢苦不壽，時世方士無靈砂。","五月至止六月病，遽頹泰山驚逝波。","明年徒步弔京國，宅破子毀哀如何。","西風衝戶捲素帳，隟光斜照舊燕窠。","古人常歎知己少，況我淪賤艱虞多。","如公之德世一二，豈得無淚如黃河。","瀝膽咒願天有眼，君子之澤方滂沱。"]', '["丈人博陵王名家，怜我總角稱才华。","华州留語晓至暮，高声喝吏放兩衙。","明朝騎马出城外，送我習業南山阿。","仲子延岳年十六，面如白玉欹烏紗。","其弟炳章猶兩丱，瑤林瓊樹含奇花。","陳留阮家諸侄秀，邐迤出拜何駢羅。","府中從事杜與李，麟角虎翅相過摩。","清词孤韻有歌响，擊觸鐘磬鳴环珂。","三月石堤凍銷釋，东风开花满陽坡。","时禽得伴戲新木，其声尖咽如鳴梭。","公时載酒領從事，踴躍鞍马来相過。","仰看楼殿撮清漢，坐視世界如恒沙。","面熱脚掉互登陟，青云表柱白云崖。","一百八句在貝葉，三十三天长雨花。","长者子来輒獻蓋，辟支佛去空留鞾。","公时受詔鎮东魯，遣我草詔隨车牙。","顧我下笔即千字，疑我读书傾五车。","嗚嘑大賢苦不壽，时世方士無靈砂。","五月至止六月病，遽頹泰山驚逝波。","明年徒步弔京国，宅破子毀哀如何。","西风衝戶捲素帳，隟光斜照旧燕窠。","古人常歎知己少，況我淪賤艱虞多。","如公之德世一二，豈得無泪如黄河。","瀝膽咒願天有眼，君子之澤方滂沱。"]', '诗', 'shi', '', NULL, '安平公詩 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae660471-84bc-4a58-a438-005b8a99c3c1', '赤壁', '赤壁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["折戟沈沙鐵未銷，自將磨洗認前朝。","東風不與周郎便，銅雀春深鎖二喬。"]', '["折戟沈沙鐵未銷，自將磨洗認前朝。","东风不與周郎便，銅雀春深鎖二喬。"]', '诗', 'shi', '', NULL, '赤壁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10256150-7be8-4da3-8292-82e61ac918a2', '垂柳', '垂柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["垂柳碧鬅茸，樓昏雨帶容。","思量成夜夢，束久廢春慵。","梳洗憑張敞，乘騎笑稚恭。","碧虛隨轉笠，紅燭近高舂。","怨目明秋水，愁眉淡遠峰。","小闌花盡蝶，靜院醉醒蛩。","舊作琴臺鳳，今爲藥店龍。","寶匳拋擲久，一任景陽鐘。"]', '["垂柳碧鬅茸，楼昏雨带容。","思量成夜梦，束久廢春慵。","梳洗憑張敞，乘騎笑稚恭。","碧虛隨轉笠，紅燭近高舂。","怨目明秋水，愁眉淡远峰。","小闌花尽蝶，静院醉醒蛩。","旧作琴台鳳，今爲藥店龙。","寶匳拋擲久，一任景陽鐘。"]', '诗', 'shi', '', NULL, '垂柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56b89f1-347a-417f-853e-7721520942ee', '清夜怨', '清夜怨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["含淚坐春宵，聞君欲度遼。","綠池荷葉嫩，紅砌杏花嬌。","曙月當窗滿，征雲出塞遙。","畫樓終日閉，清管爲誰調。"]', '["含泪坐春宵，闻君欲度遼。","綠池荷葉嫩，紅砌杏花嬌。","曙月當窗满，征云出塞遙。","畫楼終日閉，清管爲誰調。"]', '诗', 'shi', '', NULL, '清夜怨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc85917d-d8b9-4e69-a8bf-891edf86f3fe', '定子', '定子', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["檀槽一抹廣陵春，定子初開睡臉新。","卻笑喫虛隋煬帝，破家亡國爲何人。"]', '["檀槽一抹廣陵春，定子初开睡臉新。","卻笑喫虛隋煬帝，破家亡国爲何人。"]', '诗', 'shi', '', NULL, '定子 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c95929-ff50-40f7-8447-2b2603f8b551', '木蘭花', '木蘭花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["洞庭波冷曉侵雲，日日征帆送遠人。","幾度木蘭舟上望，不知元是此花身。"]', '["洞庭波冷晓侵云，日日征帆送远人。","幾度木蘭舟上望，不知元是此花身。"]', '诗', 'shi', '', NULL, '木蘭花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a7f056-71e6-4ccf-abe1-711ccedef0be', '遊靈伽寺', '游靈伽寺', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["碧煙秋寺汎湖來，水打城根古堞摧。","盡日傷心人不見，石榴花滿舊琴臺。"]', '["碧煙秋寺汎湖来，水打城根古堞摧。","尽日傷心人不见，石榴花满旧琴台。"]', '诗', 'shi', '', NULL, '遊靈伽寺 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0abe360d-128c-446d-a27b-62371e6bbc04', '龍丘途中 一', '龙丘途中 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["漢苑殘花別，吳江盛夏來。","惟看萬樹谷，不見一枝開。"]', '["漢苑殘花別，吳江盛夏来。","惟看万樹谷，不见一枝开。"]', '诗', 'shi', '', NULL, '龍丘途中 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131b9bdc-8df2-4dd9-aa38-db6c73284606', '龍丘途中 二', '龙丘途中 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["水色饒湘浦，灘聲怯建溪。","淚流迴月上，可得更猨蹄。"]', '["水色饒湘浦，灘声怯建溪。","泪流迴月上，可得更猨蹄。"]', '诗', 'shi', '', NULL, '龍丘途中 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aeef785-6d02-4199-b259-175b136a977c', '句', '句', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蘭膏爇處心猶淺，銀燭燒殘焰不馨。","好向書生窗畔種，免教辛苦更囊螢。","遙想故園陌，桃李正酣酣。","頭上金雀釵，腰珮翠琅玕。","蘆洲客雁報春來。"]', '["蘭膏爇处心猶淺，銀燭燒殘焰不馨。","好向书生窗畔種，免教辛苦更囊螢。","遙想故园陌，桃李正酣酣。","头上金雀釵，腰珮翠琅玕。","蘆洲客雁報春来。"]', '诗', 'shi', '', NULL, '句 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c568d2b8-c691-490c-acab-58ebc366db47', '送友人歸宜春', '送友人归宜春', '17804760-71f0-43fa-9f26-90d70ce9d001', '唐', '["落花兼柳絮，無處不紛紛。","遠道空歸去，流鶯獨自聞。","墅橋喧碓水，山郭入樓雲。","故里南陔曲，秋期欲送君。"]', '["落花兼柳絮，無处不紛紛。","远道空归去，流鶯独自闻。","墅橋喧碓水，山郭入楼云。","故里南陔曲，秋期欲送君。"]', '诗', 'shi', '', NULL, '送友人歸宜春 紀唐夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea96e47-9117-4909-bf90-9394890b87d7', '驄馬曲', '驄马曲', '17804760-71f0-43fa-9f26-90d70ce9d001', '唐', '["連錢出塞蹋沙蓬，豈比當時御史驄。","逐北自諳深磧路，連嘶誰念靜邊功。","登山每與青雲合，弄影應知碧草同。","今日虜平將換妾，不如羅袖舞春風。"]', '["連錢出塞蹋沙蓬，豈比當时御史驄。","逐北自諳深磧路，連嘶誰念静邊功。","登山每與青云合，弄影應知碧草同。","今日虜平將換妾，不如羅袖舞春风。"]', '诗', 'shi', '', NULL, '驄馬曲 紀唐夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4fc4ed-9623-4cef-a0de-1a270effc21c', '送溫庭筠尉方城', '送溫庭筠尉方城', '17804760-71f0-43fa-9f26-90d70ce9d001', '唐', '["何事明時泣玉頻，長安不見杏園春。","鳳皇詔下雖霑命，鸚鵡才高却累身。","且盡綠醽銷積恨，莫辭黃綬拂行塵。","方城若比長沙路，猶隔千山與萬津。"]', '["何事明时泣玉頻，长安不见杏园春。","鳳皇詔下雖霑命，鸚鵡才高却累身。","且尽綠醽銷積恨，莫辞黄綬拂行塵。","方城若比长沙路，猶隔千山與万津。"]', '诗', 'shi', '', NULL, '送溫庭筠尉方城 紀唐夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2997f5a6-5f48-411b-a445-e21d865db136', '及第後宿平康里', '及第後宿平康里', 'b36b3904-f260-4853-b75a-4baa38a2a2e4', '唐', '["銀缸斜背解鳴璫，小語偷聲賀玉郎。","從此不知蘭麝貴，夜來新染桂枝香。"]', '["銀缸斜背解鳴璫，小語偷声賀玉郎。","從此不知蘭麝貴，夜来新染桂枝香。"]', '诗', 'shi', '', NULL, '及第後宿平康里 裴思謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55cbce85-fcf0-4d3a-8141-a0357f2e70d7', '都堂試貢士日慶春雪', '都堂試貢士日慶春雪', 'd3fcbf79-7425-48ea-9b79-4264f1cf4da3', '唐', '["錫瑞來豐歲，旌賢入貢辰。","輕搖梅共笑，飛褭柳知春。","遶砌封瓊屑，依階噴玉塵。","蜉蝣吟更古，科斗映還新。","鶴毳迷難辨，冰壺鑒易真。","因歌大君德，率舞詠陶鈞。"]', '["錫瑞来豐歲，旌賢入貢辰。","轻搖梅共笑，飞褭柳知春。","遶砌封瓊屑，依階噴玉塵。","蜉蝣吟更古，科斗映還新。","鹤毳迷难辨，冰壺鑒易真。","因歌大君德，率舞詠陶鈞。"]', '诗', 'shi', '', NULL, '都堂試貢士日慶春雪 李衢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d45b8ef-2cc2-49da-8ae7-3246fdb817f6', '都堂試貢士日慶春雪', '都堂試貢士日慶春雪', 'ec14ddee-7bd2-405b-a95a-58584edc900b', '唐', '["春雪晝悠颺，飄飛試士場。","綴毫疑起草，霑字共成章。","匝地如鋪練，凝階似截肪。","鵝毛縈樹合，柳絮帶風狂。","息疫方殊慶，豐年已報祥。","應知郢上曲，高唱出東堂。"]', '["春雪晝悠颺，飄飞試士場。","綴毫疑起草，霑字共成章。","匝地如鋪練，凝階似截肪。","鵝毛縈樹合，柳絮带风狂。","息疫方殊慶，豐年已報祥。","應知郢上曲，高唱出东堂。"]', '诗', 'shi', '', NULL, '都堂試貢士日慶春雪 李損之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04881b67-c09f-4fcb-b935-a2591cde6430', '除夜長安作', '除夜长安作', 'baed03c4-776c-4495-b3a9-abb906dcdb6c', '唐', '["長安朔風起，窮巷掩雙扉。","新歲明朝是，故鄉何路歸。","鬢絲饒鏡色，隟雪奪燈輝。","却羨秦州鴈，逢春盡北飛。"]', '["长安朔风起，窮巷掩雙扉。","新歲明朝是，故乡何路归。","鬢絲饒镜色，隟雪奪灯輝。","却羨秦州鴈，逢春尽北飞。"]', '诗', 'shi', '', NULL, '除夜長安作 李景 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c567ce-5fb0-40d9-a00a-bca0d94b3643', '都堂試貢士日慶春雪', '都堂試貢士日慶春雪', 'baed03c4-776c-4495-b3a9-abb906dcdb6c', '唐', '["密雪分天路，羣才坐粉廊。","靄空迷晝景，臨宇借寒光。","似暖花消地，無聲玉滿堂。","灑池偏誤曲，留硯忽因方。","幾處曹風比，何人謝賦長。","春暉早相照，莫滯九衢芳。"]', '["密雪分天路，羣才坐粉廊。","靄空迷晝景，臨宇借寒光。","似暖花消地，無声玉满堂。","灑池偏誤曲，留硯忽因方。","幾处曹风比，何人謝賦长。","春暉早相照，莫滯九衢芳。"]', '诗', 'shi', '', NULL, '都堂試貢士日慶春雪 李景 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed1a4a7-2786-4d40-adab-6d8e9ca7bae7', '登景雲寺閣', '登景云寺閣', 'aa34d01b-da79-411e-b7fb-e46d3cf59189', '唐', '["胡馬飲河洛，我家從此遷。","今來獨垂淚，三十六峰前。"]', '["胡马饮河洛，我家從此遷。","今来独垂泪，三十六峰前。"]', '诗', 'shi', '', NULL, '登景雲寺閣 張元宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38f9d8f-3a9f-4c1b-8c53-ece13e3b47b5', '望終南山', '望終南山', 'aa34d01b-da79-411e-b7fb-e46d3cf59189', '唐', '["紅塵白日長安路，馬足車輪不暫閑。","唯有茂陵多病客，每來高處望南山。"]', '["紅塵白日长安路，马足车輪不暫闲。","唯有茂陵多病客，每来高处望南山。"]', '诗', 'shi', '', NULL, '望終南山 張元宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342fab30-f025-454a-a63d-4c3e1ef4e633', '省試霓裳羽衣曲', '省試霓裳羽衣曲', '1286a029-a867-421e-957b-420faebff10b', '唐', '["開元太平時，萬國賀豐歲。","梨園獻舊曲，玉座流新製。","鳳管遞參差，霞衣競搖曳。","醼罷水殿空，輦餘春草細。","蓬壺事已久，仙樂功無替。","詎肯聽遺音，聖明知善繼。"]', '["开元太平时，万国賀豐歲。","梨园獻旧曲，玉座流新製。","鳳管遞參差，霞衣競搖曳。","醼罷水殿空，輦餘春草細。","蓬壺事已久，仙乐功無替。","詎肯听遺音，聖明知善繼。"]', '诗', 'shi', '', NULL, '省試霓裳羽衣曲 李肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20980d9a-874a-48f8-af29-0ea529c7eb3d', '句', '句', '1286a029-a867-421e-957b-420faebff10b', '唐', '["水光先見月，露氣早知秋。"]', '["水光先见月，露氣早知秋。"]', '诗', 'shi', '', NULL, '句 李肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132d0b6a-2bc0-4385-84fa-9b415f305243', '永州送姪歸宜春', '永州送姪归宜春', '3126498e-d914-4eea-8df1-c876b6bdedb7', '唐', '["宋玉正秋悲，那堪更別離。","從來襟上淚，盡作鬢邊絲。","永水清如此，袁江色可知。","到家黃菊坼，亦莫怪歸遲。"]', '["宋玉正秋悲，那堪更別離。","從来襟上泪，尽作鬢邊絲。","永水清如此，袁江色可知。","到家黄菊坼，亦莫怪归遲。"]', '诗', 'shi', '', NULL, '永州送姪歸宜春 鄭史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceba570e-3e0b-4a9c-b521-9c25b1e1e102', '秋日零陵與幕下諸賓遊河夜飲', '秋日零陵與幕下諸賓游河夜饮', '3126498e-d914-4eea-8df1-c876b6bdedb7', '唐', '["湘月蘋風乍暢襟，燭前江水練千尋。","新秋宋玉能爲賦，永夕袁安好共吟。","輦下翠蛾須強展，尊中綠蟻且徐斟。","汀沙漸有珠凝露，緩棹蘭橈任夜深。"]', '["湘月蘋风乍暢襟，燭前江水練千尋。","新秋宋玉能爲賦，永夕袁安好共吟。","輦下翠蛾須強展，尊中綠蟻且徐斟。","汀沙漸有珠凝露，緩棹蘭橈任夜深。"]', '诗', 'shi', '', NULL, '秋日零陵與幕下諸賓遊河夜飲 鄭史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bc7049-60da-49f1-8f5d-794947993563', '贈妓行雲詩', '贈妓行云诗', '3126498e-d914-4eea-8df1-c876b6bdedb7', '唐', '["最愛鉛華薄薄妝，更兼衣著又鵝黃。","從來南國名佳麗，何事今朝在北行。"]', '["最愛鉛华薄薄妝，更兼衣著又鵝黄。","從来南国名佳丽，何事今朝在北行。"]', '诗', 'shi', '', NULL, '贈妓行雲詩 鄭史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f845e50b-8b2b-466b-bdc4-73ae4502f2ff', '紀夢', '紀梦', '9adcd903-1582-44c6-83a6-a6e701e99d85', '唐', '["曉入瑤臺露氣清，天風飛下步虛聲。","塵心未盡俗緣在，十里下山空月明。"]', '["晓入瑤台露氣清，天风飞下步虛声。","塵心未尽俗緣在，十里下山空月明。"]', '诗', 'shi', '', NULL, '紀夢 許瀍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a443d900-8747-454f-bafc-1c59dc0615d1', '題朝陽巖', '題朝陽巖', '68175e56-f9ad-4170-bfd4-4cfe78df3696', '唐', '["躡石攀蘿路不迷，曉天風好浪花低。","洞名獨占朝陽號，應有梧桐待鳳棲。"]', '["躡石攀蘿路不迷，晓天风好浪花低。","洞名独占朝陽號，應有梧桐待鳳棲。"]', '诗', 'shi', '', NULL, '題朝陽巖 牛叢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c074d22-f8fb-48e7-8790-39751e272622', '咸陽有懷', '咸陽有懷', '6dc635eb-d100-4f90-a697-ad935556d559', '唐', '["山連河水碧氛氳，瑞氣東移擁聖君。","秦苑有花空笑日，漢陵無主自侵雲。","古槐堤上鶯千囀，遠渚沙中鷺一羣。","賴與淵明同把菊，煙郊西望夕陽曛。"]', '["山連河水碧氛氳，瑞氣东移擁聖君。","秦苑有花空笑日，漢陵無主自侵云。","古槐堤上鶯千囀，远渚沙中鷺一羣。","賴與淵明同把菊，煙郊西望夕陽曛。"]', '诗', 'shi', '', NULL, '咸陽有懷 陳上美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38fa500d-186d-44b1-adea-0fa43230fa4d', '晴望九華山', '晴望九华山', 'eb21dafa-9d32-4981-ae1f-670482569cb1', '唐', '["九華閑望簇清虛，氣象羣峰盡不如。","惆悵都南挂冠吏，無人解向此山居。"]', '["九华闲望簇清虛，氣象羣峰尽不如。","惆悵都南挂冠吏，無人解向此山居。"]', '诗', 'shi', '', NULL, '晴望九華山 楊鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5524ba0b-6cfa-499e-9032-6d8460523264', '正月', '正月', 'af3be6c3-d696-439c-a8b2-645fd1962b79', '唐', '["正月今朝半，陽臺信未迴。","水芹寒不食，山杏雨應開。","世網留三宿，真源寄一杯。","因聲謝猨鳥，歲[晏]會歸來。"]', '["正月今朝半，陽台信未迴。","水芹寒不食，山杏雨應开。","世網留三宿，真源寄一杯。","因声謝猨鸟，歲[晏]會归来。"]', '诗', 'shi', '', NULL, '正月 趙璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483c8965-6078-49ba-b9e7-e31cde55e2b8', '七夕詩', '七夕诗', 'af3be6c3-d696-439c-a8b2-645fd1962b79', '唐', '["烏鵲橋頭雙扇開，年年一度過河來。","莫嫌天上稀相見，猶勝人間去不迴。","欲減煙花饒俗世，暫煩雲月掩樓臺。","別時舊路長清淺，豈肯離情似死灰。"]', '["烏鵲橋头雙扇开，年年一度過河来。","莫嫌天上稀相见，猶勝人间去不迴。","欲減煙花饒俗世，暫煩云月掩楼台。","別时旧路长清淺，豈肯離情似死灰。"]', '诗', 'shi', '', NULL, '七夕詩 趙璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea6636e-71e3-4270-b496-32ddcd871c93', '曲江上巳', '曲江上巳', 'af3be6c3-d696-439c-a8b2-645fd1962b79', '唐', '["長隄十里轉香車，兩岸煙花錦不如。","欲問神仙在何處，紫雲樓閣向空虛。"]', '["长隄十里轉香车，兩岸煙花錦不如。","欲问神仙在何处，紫云楼閣向空虛。"]', '诗', 'shi', '', NULL, '曲江上巳 趙璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2cc9a0-fb5a-4d7e-adef-c5659ba33d8e', '題七夕圖', '題七夕圖', 'af3be6c3-d696-439c-a8b2-645fd1962b79', '唐', '["帝子吹簫上翠微，秋風一曲鳳皇歸。","明年七月重相見，依舊高懸織女機。"]', '["帝子吹簫上翠微，秋风一曲鳳皇归。","明年七月重相见，依旧高懸织女機。"]', '诗', 'shi', '', NULL, '題七夕圖 趙璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e5216a-6ba3-4f7c-a037-1be2a09e958d', '登明戍堡', '登明戍堡', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["來經古城上，極目思無窮。","寇盡煙蘿外，人歸蔓草中。","峰巒當闕古，堞壘對雲空。","不見昔名將，徒稱有戰功。"]', '["来經古城上，極目思無窮。","寇尽煙蘿外，人归蔓草中。","峰巒當闕古，堞壘对云空。","不见昔名將，徒稱有戰功。"]', '诗', 'shi', '', NULL, '登明戍堡 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50fa4a0e-6c9c-4636-8b98-01509255d3de', '送陳明府之任', '送陳明府之任', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["客見天台縣，閭閻樹色間。","驂回幾臨水，帶緩獨開山。","吏散落花盡，人居遠島閑。","過於老萊子，端簡獨承顏。"]', '["客见天台縣，閭閻樹色间。","驂回幾臨水，带緩独开山。","吏散落花尽，人居远島闲。","過於老萊子，端簡独承顏。"]', '诗', 'shi', '', NULL, '送陳明府之任 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4870297-447a-47e1-b3c4-adbb19519bd9', '長安春暮', '长安春暮', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["客在關西春暮夜，還同江外已清明。","三更獨立看花月，惟欠子規啼一聲。"]', '["客在关西春暮夜，還同江外已清明。","三更独立看花月，惟欠子規啼一声。"]', '诗', 'shi', '', NULL, '長安春暮 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8557154-1783-4d3c-b8e2-cb793c40e509', '舟行', '舟行', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["平沙極浦無人度，獨繫孤舟寒草西。","半夜起看潮上月，萬山中有一猨啼。"]', '["平沙極浦無人度，独繫孤舟寒草西。","半夜起看潮上月，万山中有一猨啼。"]', '诗', 'shi', '', NULL, '舟行 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118df0b5-8bf6-41c2-a95f-67531ac766f0', '送僧', '送僧', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["闕下僧歸山頂寺，却看朝日下方明。","莫道野人尋不見，半天雲裏有鐘聲。"]', '["闕下僧归山頂寺，却看朝日下方明。","莫道野人尋不见，半天云裏有鐘声。"]', '诗', 'shi', '', NULL, '送僧 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25da8d3-1c5a-453f-b82b-214db39e0fe5', '句', '句', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["棧踏猨聲暮，江看劍影秋。","僧老白雲上，磬寒高鳥邊。","心已同猨狖，不聞人是非。","行人渡流水，白馬入前山。","秋深雪滿黃金塞，夜夜鴻聲入漢陽。"]', '["棧踏猨声暮，江看劍影秋。","僧老白云上，磬寒高鸟邊。","心已同猨狖，不闻人是非。","行人渡流水，白马入前山。","秋深雪满黄金塞，夜夜鴻声入漢陽。"]', '诗', 'shi', '', NULL, '句 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33916556-2066-498e-a2ae-0e35f03f3589', '秋晚同友人閑步', '秋晚同友人闲步', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["藉草與行莎，相看日未斜。","斷崖分鳥道，疎樹見人家。","望遠臨孤石，吟餘落片霞。","野情看不足，歸路思猶賒。"]', '["藉草與行莎，相看日未斜。","斷崖分鸟道，疎樹见人家。","望远臨孤石，吟餘落片霞。","野情看不足，归路思猶賒。"]', '诗', 'shi', '', NULL, '秋晚同友人閑步 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b28029-af0b-410b-adca-7e93a044b043', '宿仙都觀陰王二君修道處', '宿仙都观陰王二君修道处', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["十載別仙峰，峰前千古蹤。","陰王修道處，雲雪滿高松。","洞口風雷異，池心星漢重。","明朝下山去，片月落殘鐘。"]', '["十載別仙峰，峰前千古蹤。","陰王修道处，云雪满高松。","洞口风雷異，池心星漢重。","明朝下山去，片月落殘鐘。"]', '诗', 'shi', '', NULL, '宿仙都觀陰王二君修道處 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2b8cec-3afd-4eb5-8d05-b7e692753748', '宿東巖寺曉起', '宿东巖寺晓起', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["野寺寒塘曉，遊人一夢分。","鐘殘數樹月，僧起半巖雲。","宿鳥驚初見，幽泉落不聞。","吟餘憑前檻，紅葉下紛紛。"]', '["野寺寒塘晓，游人一梦分。","鐘殘數樹月，僧起半巖云。","宿鸟驚初见，幽泉落不闻。","吟餘憑前檻，紅葉下紛紛。"]', '诗', 'shi', '', NULL, '宿東巖寺曉起 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a7d82c-47ae-41e3-862c-e61ea8f65494', '秋日湖上', '秋日湖上', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["落日五湖遊，煙波處處愁。","沈浮千古事，誰與問東流。"]', '["落日五湖游，煙波处处愁。","沈浮千古事，誰與问东流。"]', '诗', 'shi', '', NULL, '秋日湖上 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff24370c-4941-4ce7-b424-b484367a0aba', '江山閑望', '江山闲望', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["渺渺無窮盡，風濤幾日平。","年光與人事，東去一聲聲。"]', '["渺渺無窮尽，风濤幾日平。","年光與人事，东去一声声。"]', '诗', 'shi', '', NULL, '江山閑望 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e020e986-d544-401d-95ee-f9d8ae0adb74', '訪武陵道者不遇', '訪武陵道者不遇', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["花發鳥仍啼，行行路欲迷。","二真無問處，虛度武陵溪。"]', '["花發鸟仍啼，行行路欲迷。","二真無问处，虛度武陵溪。"]', '诗', 'shi', '', NULL, '訪武陵道者不遇 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdcdfd98-1a2f-4cc4-94f2-9179fd13ca70', '寄舊山隱侶', '寄旧山隐侶', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["舊山諸隱淪，身在苦無身。","莫鎖白雲路，白雲多悞人。"]', '["旧山諸隐淪，身在苦無身。","莫鎖白云路，白云多悞人。"]', '诗', 'shi', '', NULL, '寄舊山隱侶 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da552079-89c8-48ec-a913-710125e257e7', '羨僧', '羨僧', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["處世曾無著，生前事盡非。","一缾兼一衲，南北去如歸。"]', '["处世曾無著，生前事尽非。","一缾兼一衲，南北去如归。"]', '诗', 'shi', '', NULL, '羨僧 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ca7ff8-c8b5-4b33-a191-4ada8ce9e86f', '錦', '錦', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["軋軋弄寒機，功多力漸微。","惟憂機上錦，不稱舞人衣。"]', '["軋軋弄寒機，功多力漸微。","惟憂機上錦，不稱舞人衣。"]', '诗', 'shi', '', NULL, '錦 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('634aa7c8-8cf7-4519-88fa-57ff5d91ba03', '中秋月', '中秋月', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["三十六旬盈復缺，百年堪喜又堪傷。","勸君莫惜登樓望，雲放嬋娟不久長。"]', '["三十六旬盈复缺，百年堪喜又堪傷。","勸君莫惜登楼望，云放嬋娟不久长。"]', '诗', 'shi', '', NULL, '中秋月 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a95b90-85f2-43d9-adbd-ac98573860d3', '句', '句', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["單棹橫疎雨，江灘秋泊時。","花留身住越，月遞夢還秦。"]', '["單棹橫疎雨，江灘秋泊时。","花留身住越，月遞梦還秦。"]', '诗', 'shi', '', NULL, '句 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6071988-def8-4a18-a925-66ef3ef61b70', '贈毛仙翁', '贈毛仙翁', '56f2a8d4-e384-41d5-bad4-742bf9f2c48b', '唐', '["莫將凡聖比雲泥，椿菌之年本不齊。","度世無勞大稻米，昇天只用半刀圭。","人間嗟對黃昏槿，海上閑聽碧落雞。","旌節行中令引道，便從塵外踏丹梯。"]', '["莫將凡聖比云泥，椿菌之年本不齊。","度世無勞大稻米，昇天只用半刀圭。","人间嗟对黄昏槿，海上闲听碧落雞。","旌節行中令引道，便從塵外踏丹梯。"]', '诗', 'shi', '', NULL, '贈毛仙翁 崔元略 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f41270-eebd-4809-b0f5-0f687bbf629c', '太學創置石經', '太学創置石經', '1640fde6-f594-49c7-a342-4aa5a673fddf', '唐', '["聖唐復古制，德義功無替。","奧旨悅詩書，遺文分篆隸。","銀鉤互交映，石壁靡塵翳。","永與乾坤期，不逐日月逝。","儒林道益廣，學者心彌銳。","從此理化成，恩光遍遐裔。"]', '["聖唐复古制，德義功無替。","奧旨悅诗书，遺文分篆隸。","銀鉤互交映，石壁靡塵翳。","永與乾坤期，不逐日月逝。","儒林道益廣，学者心彌銳。","從此理化成，恩光遍遐裔。"]', '诗', 'shi', '', NULL, '太學創置石經 馮涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d235b6d6-20e0-44fd-a924-5b4841822972', '贈李商隱', '贈李商隐', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["羽翼恣摶扶，山河使筆驅。","月疎吟夜桂，龍失詠春珠。","草細盤金勒，花繁倒玉壺。","徒嗟好章句，無力致前途。"]', '["羽翼恣摶扶，山河使笔驱。","月疎吟夜桂，龙失詠春珠。","草細盤金勒，花繁倒玉壺。","徒嗟好章句，無力致前途。"]', '诗', 'shi', '', NULL, '贈李商隱 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98690cc8-65fe-492c-96c7-eda3c902d84d', '元日即事', '元日即事', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["斂板賀交親，稱觴詎有巡。","年光悲擲舊，景色喜呈新。","水柳煙中重，山梅雪後真。","不知將白髮，何以度青春。"]', '["斂板賀交親，稱觴詎有巡。","年光悲擲旧，景色喜呈新。","水柳煙中重，山梅雪後真。","不知將白髮，何以度青春。"]', '诗', 'shi', '', NULL, '元日即事 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('511d4d29-fcfb-40af-86d1-a5a66dd82825', '送賈島往金州謁姚員外', '送賈島往金州謁姚員外', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["山光與水色，獨往此中深。","溪瀝椒花氣，巖盤漆葉陰。","瀟湘終共去，巫峽羨先尋。","幾夕江樓月，玄暉伴靜吟。"]', '["山光與水色，独往此中深。","溪瀝椒花氣，巖盤漆葉陰。","瀟湘終共去，巫峽羨先尋。","幾夕江楼月，玄暉伴静吟。"]', '诗', 'shi', '', NULL, '送賈島往金州謁姚員外 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d49db0-d027-4a09-82a3-4e73d65b1ddb', '送友人罷舉歸蜀', '送友人罷舉归蜀', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["憔悴滿衣塵，風光豈屬身。","賣琴紅粟貴，看鏡白髭新。","棧畔誰高步，巴邊自問津。","悽然莫滴血，杜宇正哀春。"]', '["憔悴满衣塵，风光豈屬身。","賣琴紅粟貴，看镜白髭新。","棧畔誰高步，巴邊自问津。","悽然莫滴血，杜宇正哀春。"]', '诗', 'shi', '', NULL, '送友人罷舉歸蜀 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b392b79-2a3a-49f3-bd7d-a3c5528cba5f', '送衛尉之延陵', '送衛尉之延陵', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["草木正花時，交親觸雨辭。","一官之任遠，盡室出城遲。","乳滴茅君洞，鴉鳴季子祠。","想知佐理暇，日有詠懷詩。"]', '["草木正花时，交親觸雨辞。","一官之任远，尽室出城遲。","乳滴茅君洞，鴉鳴季子祠。","想知佐理暇，日有詠懷诗。"]', '诗', 'shi', '', NULL, '送衛尉之延陵 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915fdfc5-575f-4cfe-a4b9-07eb5b6a2258', '送越州高錄事', '送越州高錄事', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["官曹權紀綱，行李半舟航。","浦溆潮來廣，川源鳥去長。","筍成稽嶺岸，蓮發鏡湖香。","澤國還之任，鱸魚浪得嘗。"]', '["官曹權紀綱，行李半舟航。","浦溆潮来廣，川源鸟去长。","筍成稽嶺岸，蓮發镜湖香。","澤国還之任，鱸鱼浪得嘗。"]', '诗', 'shi', '', NULL, '送越州高錄事 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e3b4e7-8e36-498f-b304-01b2d0ac88b0', '送潘咸', '送潘咸', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["時時齎破囊，訪我息閑坊。","煮雪問茶味，當風看鴈行。","心齊山鹿逸，句敵柳花狂。","堅苦今如此，前程豈渺茫。"]', '["时时齎破囊，訪我息闲坊。","煮雪问茶味，當风看鴈行。","心齊山鹿逸，句敵柳花狂。","堅苦今如此，前程豈渺茫。"]', '诗', 'shi', '', NULL, '送潘咸 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850eb99d-8e71-4d28-a138-f2d828a1a792', '送友人下第歸寧', '送友人下第归寧', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["紫閣雪未盡，杏園花亦寒。","灞西辭舊友，楚外憶新安。","細雨猨啼枿，微陽鷺起灘。","旋應赴秋貢，詎得久承歡。"]', '["紫閣雪未尽，杏园花亦寒。","灞西辞旧友，楚外憶新安。","細雨猨啼枿，微陽鷺起灘。","旋應赴秋貢，詎得久承歡。"]', '诗', 'shi', '', NULL, '送友人下第歸寧 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0987c6db-16dc-418e-81a9-00263a8c3fd0', '游北山寺', '游北山寺', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["煙岡影畔寺，游步此時孤。","庭靜衆藥在，鶴閑雙檜枯。","藍峰露秋院，灞水入春廚。","便可棲心跡，如何返舊途。"]', '["煙岡影畔寺，游步此时孤。","庭静衆藥在，鹤闲雙檜枯。","藍峰露秋院，灞水入春廚。","便可棲心跡，如何返旧途。"]', '诗', 'shi', '', NULL, '游北山寺 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82aa7717-7a23-471c-a650-c263244f4044', '冬日題無可上人院', '冬日題無可上人院', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["入戶道心生，茶間踏葉行。","瀉風瓶水澀，承露鶴巢輕。","閣北長河氣，窗東一檜聲。","詩言與禪味，語默此皆清。"]', '["入戶道心生，茶间踏葉行。","瀉风瓶水澀，承露鹤巢轻。","閣北长河氣，窗东一檜声。","诗言與禪味，語默此皆清。"]', '诗', 'shi', '', NULL, '冬日題無可上人院 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a19ba3e6-c35f-41bf-a5fc-cf0cdbffe7ae', '游雲際寺', '游云際寺', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["澗壑吼風雷，香門絕頂開。","閣寒僧不下，鐘定虎常來。","鳥啄林稍菓，鼯跳竹裏苔。","心源無一事，塵界擬休回。"]', '["澗壑吼风雷，香门絕頂开。","閣寒僧不下，鐘定虎常来。","鸟啄林稍菓，鼯跳竹裏苔。","心源無一事，塵界擬休回。"]', '诗', 'shi', '', NULL, '游雲際寺 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6480be6-096b-4c28-a2ef-231691fc73b2', '題翠微寺', '題翠微寺', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["沿溪又涉巔，始喜入前軒。","鐘度鳥沈壑，殿扃雲濕幡。","涼泉墮衆石，古木徹疎猨。","月上僧階近，斯遊豈易言。"]', '["沿溪又涉巔，始喜入前軒。","鐘度鸟沈壑，殿扃云濕幡。","涼泉墮衆石，古木徹疎猨。","月上僧階近，斯游豈易言。"]', '诗', 'shi', '', NULL, '題翠微寺 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e30a1d04-8a64-4d91-9749-a94785424ed1', '廣德官舍二松', '廣德官舍二松', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["楊公休簿領，二木日堅牢。","直甚彰吾節，清終庇爾曹。","幽陰月裏細，冷樹雪中高。","誰見干霄後，枝飄白鶴毛。"]', '["楊公休簿領，二木日堅牢。","直甚彰吾節，清終庇爾曹。","幽陰月裏細，冷樹雪中高。","誰见干霄後，枝飄白鹤毛。"]', '诗', 'shi', '', NULL, '廣德官舍二松 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('689ccdb3-04b3-4669-84d9-8c4fc9f9c03f', '浴馬', '浴马', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["解控復收鞭，長津動細漣。","空蹄沈綠玉，闊臆沒連錢。","沫漩橋聲下，嘶盤柳影邊。","常聞畯龍性，固與白波便。"]', '["解控复收鞭，长津动細漣。","空蹄沈綠玉，闊臆沒連錢。","沫漩橋声下，嘶盤柳影邊。","常闻畯龙性，固與白波便。"]', '诗', 'shi', '', NULL, '浴馬 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb1a9b4-e2a1-4cdb-b4a4-4b31d767b9a9', '和段學士南亭春日對雨', '和段学士南亭春日对雨', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["晨飛晚未休，蘭閣客吟愁。","蕭颯柳邊挂，縈紆花底流。","聲繁乍離籟，灑急不成漚。","經夕江湖思，煙波一釣舟。"]', '["晨飞晚未休，蘭閣客吟愁。","蕭颯柳邊挂，縈紆花底流。","声繁乍離籟，灑急不成漚。","經夕江湖思，煙波一釣舟。"]', '诗', 'shi', '', NULL, '和段學士南亭春日對雨 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11019324-2d71-40a7-8b63-ae45da9c35a2', '書懷', '书懷', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["秖是守琴書，僧中獨寓居。","心唯務鶴靜，分合與名疎。","暮雨啼螿次，涼風落木初。","家山太湖淥，歸去復何如。"]', '["秖是守琴书，僧中独寓居。","心唯務鹤静，分合與名疎。","暮雨啼螿次，涼风落木初。","家山太湖淥，归去复何如。"]', '诗', 'shi', '', NULL, '書懷 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c88c9816-8f77-4d64-9ed2-49ded4293ddf', '一公房', '一公房', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["幽深誰掩關，清淨自多閑。","一雨收衆木，孤雲生遠山。","花萎綠苔上，鴿乳翠樓間。","嵐靄燃香夕，容聽半偈還。"]', '["幽深誰掩关，清淨自多闲。","一雨收衆木，孤云生远山。","花萎綠苔上，鴿乳翠楼间。","嵐靄燃香夕，容听半偈還。"]', '诗', 'shi', '', NULL, '一公房 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e60559-18ed-4ef8-b25a-810f2870905b', '晚次臨涇', '晚次臨涇', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["路入犬羊群，城寒雉堞曛。","居人秖尚武，過客謾投文。","馬怯奔渾水，鵰沈莽蒼雲。","沙田積蒿艾，竟夕見燒焚。"]', '["路入犬羊群，城寒雉堞曛。","居人秖尚武，過客謾投文。","马怯奔渾水，鵰沈莽蒼云。","沙田積蒿艾，竟夕见燒焚。"]', '诗', 'shi', '', NULL, '晚次臨涇 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('229d0658-f8bf-4d95-81dd-8d32ffa488a3', '王母祠前寫望', '王母祠前寫望', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["雲霞千古事，桃李舊花顏。","芳信沈青鳥，空祠掩暮山。","香傳一座暗，柳匝萬家閑。","那復傷神所，河昏落日間。"]', '["云霞千古事，桃李旧花顏。","芳信沈青鸟，空祠掩暮山。","香傳一座暗，柳匝万家闲。","那复傷神所，河昏落日间。"]', '诗', 'shi', '', NULL, '王母祠前寫望 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec9055aa-cee0-401e-b541-09d4f5273981', '遊暖泉精舍', '游暖泉精舍', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["塢木殿前空，山河澤國同。","鳥閑沙影上，泉落樹陰中。","纜舸蒲花水，縈幡柳絮風。","翛然方寸地，何事更悲蓬。"]', '["塢木殿前空，山河澤国同。","鸟闲沙影上，泉落樹陰中。","纜舸蒲花水，縈幡柳絮风。","翛然方寸地，何事更悲蓬。"]', '诗', 'shi', '', NULL, '遊暖泉精舍 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16fde343-ca5b-4c39-8c78-415f168206ea', '懷鄉', '懷乡', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["秋風江上家，釣艇泊蘆花。","斷岸綠楊蔭，疎籬紅槿遮。","鼉鳴積雨窟，鶴步夕陽沙。","抱疾僧窗夜，歸心過月斜。"]', '["秋风江上家，釣艇泊蘆花。","斷岸綠楊蔭，疎籬紅槿遮。","鼉鳴積雨窟，鹤步夕陽沙。","抱疾僧窗夜，归心過月斜。"]', '诗', 'shi', '', NULL, '懷鄉 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2258cfa-0427-4fa7-b26d-6816c1e22b96', '岫禪師南溪蘭若', '岫禪師南溪蘭若', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["錫影配瓶光，孤溪照草堂。","水懸青石磴，鐘動白雲牀。","樹色含殘雨，河流帶夕陽。","唯應無月夜，瞑目見他方。"]', '["錫影配瓶光，孤溪照草堂。","水懸青石磴，鐘动白云牀。","樹色含殘雨，河流带夕陽。","唯應無月夜，瞑目见他方。"]', '诗', 'shi', '', NULL, '岫禪師南溪蘭若 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fde34ab-2f79-43e0-997d-3f75722068a9', '龍翔寺寄李頻', '龙翔寺寄李頻', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["鐘聲南北寺，不道往來遙。","人事因循過，時光荏苒銷。","懸燈灑砌雨，上閣遶雲鵰。","即是洲中柳，嘶蟬急暮條。"]', '["鐘声南北寺，不道往来遙。","人事因循過，时光荏苒銷。","懸灯灑砌雨，上閣遶云鵰。","即是洲中柳，嘶蟬急暮條。"]', '诗', 'shi', '', NULL, '龍翔寺寄李頻 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6bb71f-ad93-4d03-85ba-ce9c7fab240d', '送武瑴之邠寧', '送武瑴之邠寧', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["戍路少人蹤，邊煙澹復濃。","詩寧寫別恨，酒不上離容。","燕拂沙河柳，鵶高石窟鐘。","悠然一暌阻，山疊虜雲重。"]', '["戍路少人蹤，邊煙澹复濃。","诗寧寫別恨，酒不上離容。","燕拂沙河柳，鵶高石窟鐘。","悠然一暌阻，山叠虜云重。"]', '诗', 'shi', '', NULL, '送武瑴之邠寧 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23437ce-78a0-4748-8169-310d097a3d77', '夏日題岫禪師房', '夏日題岫禪師房', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["朝朝聲磬罷，童子掃藤陰。","花過少游客，日長無事心。","迴山閉院直，落水下橋深。","安得開方便，容身老此林。"]', '["朝朝声磬罷，童子掃藤陰。","花過少游客，日长無事心。","迴山閉院直，落水下橋深。","安得开方便，容身老此林。"]', '诗', 'shi', '', NULL, '夏日題岫禪師房 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c503cfd-d02a-42a6-9001-88b0a6d8cc07', '夏日因懷陽羨舊遊寄裴書記', '夏日因懷陽羨旧游寄裴书記', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["落日太湖西，波涵萬象低。","藕花熏浦溆，菱蔓匿鳧鷖。","樹及長橋盡，灘迴七里迷。","還應坐籌暇，時一夢荆溪。"]', '["落日太湖西，波涵万象低。","藕花熏浦溆，菱蔓匿鳧鷖。","樹及长橋尽，灘迴七里迷。","還應坐籌暇，时一梦荆溪。"]', '诗', 'shi', '', NULL, '夏日因懷陽羨舊遊寄裴書記 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c313e45-0757-47d9-abeb-bddd4a4596d1', '呈薛博士', '呈薛博士', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["辛勤長在學，一室少曾開。","時憶暮山寺，獨登衰草臺。","名期五字立，迹媿九年來。","此意今聊寫，還希君子哀。"]', '["辛勤长在学，一室少曾开。","时憶暮山寺，独登衰草台。","名期五字立，迹媿九年来。","此意今聊寫，還希君子哀。"]', '诗', 'shi', '', NULL, '呈薛博士 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba029c7-be9f-40e0-81bf-a3fefd3cb75b', '即事', '即事', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["抱杖立溪口，迎秋看塞門。","連山互蒼翠，二水各清渾。","笛發孤煙戍，鵶歸夕照村。","萋萋芳草色，終是憶王孫。"]', '["抱杖立溪口，迎秋看塞门。","連山互蒼翠，二水各清渾。","笛發孤煙戍，鵶归夕照村。","萋萋芳草色，終是憶王孫。"]', '诗', 'shi', '', NULL, '即事 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf3f45d-1866-4c5f-afe3-0a2025fc04f3', '龍翔寺閣夜懷渭南張少府', '龙翔寺閣夜懷渭南張少府', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["春城帶病別，秋塞見除書。","況是神仙吏，仍非塵土居。","河風吹鳥迥，嶽雨滴桐疎。","坐閣馳思夕，沙東涼月虛。"]', '["春城带病別，秋塞见除书。","況是神仙吏，仍非塵土居。","河风吹鸟迥，嶽雨滴桐疎。","坐閣驰思夕，沙东涼月虛。"]', '诗', 'shi', '', NULL, '龍翔寺閣夜懷渭南張少府 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba261c33-9ac6-4b4a-9ef8-d3f1c46e6b66', '夏日龍翔寺居即事寄崔侍御', '夏日龙翔寺居即事寄崔侍御', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["古剎一幡斜，吹門水過沙。","數聲鐘裏飯，雙影樹間茶。","落日窮荒雨，微風古塹花。","何當戴豸客，復此問生涯。"]', '["古剎一幡斜，吹门水過沙。","數声鐘裏飯，雙影樹间茶。","落日窮荒雨，微风古塹花。","何當戴豸客，复此问生涯。"]', '诗', 'shi', '', NULL, '夏日龍翔寺居即事寄崔侍御 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2e2859-7c3f-4065-b9a9-ee6253ca3679', '龍翔寺居喜胡權見訪因宿', '龙翔寺居喜胡權见訪因宿', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["林棲無異歡，煮茗就花欄。","雀啅北岡曉，僧開西閣寒。","衝橋二水急，扣月一鐘殘。","明發還分手，徒悲行路難。"]', '["林棲無異歡，煮茗就花欄。","雀啅北岡晓，僧开西閣寒。","衝橋二水急，扣月一鐘殘。","明發還分手，徒悲行路难。"]', '诗', 'shi', '', NULL, '龍翔寺居喜胡權見訪因宿 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5f6b748-3e06-4e2a-9778-6b5b3e315737', '宿石窟寺', '宿石窟寺', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["一剎古岡南，孤鐘撼夕嵐。","客閑明月閣，僧閉白雲菴。","野鶴立枯枿，天龍吟淨潭。","因知不生理，合自此中探。"]', '["一剎古岡南，孤鐘撼夕嵐。","客闲明月閣，僧閉白云菴。","野鹤立枯枿，天龙吟淨潭。","因知不生理，合自此中探。"]', '诗', 'shi', '', NULL, '宿石窟寺 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ee7094-c667-40c0-a923-b9cb9988df60', '夏日龍翔寺寄張侍御', '夏日龙翔寺寄張侍御', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["沙西林杪寺，殿倚石稜開。","曉月僧汲井，殘陽鐘殷臺。","河衝綠野去，鳥背白雲來。","日夕唯增思，京關未想迴。"]', '["沙西林杪寺，殿倚石稜开。","晓月僧汲井，殘陽鐘殷台。","河衝綠野去，鸟背白云来。","日夕唯增思，京关未想迴。"]', '诗', 'shi', '', NULL, '夏日龍翔寺寄張侍御 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f90ade9-bf36-46e6-b89d-f7f4d1386f2e', '秋日將歸長安留別王尚書', '秋日將归长安留別王尚书', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["朔漠正秋霖，西風傳夕砧。","滄洲未歸迹，華髪受恩心。","露色岡莎冷，蟬聲塢木深。","清晨鈇鉞內，只獻白雲吟。"]', '["朔漠正秋霖，西风傳夕砧。","滄洲未归迹，华髪受恩心。","露色岡莎冷，蟬声塢木深。","清晨鈇鉞內，只獻白云吟。"]', '诗', 'shi', '', NULL, '秋日將歸長安留別王尚書 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854cbca4-e192-405c-92cf-c402bc2126fc', '龍翔寺言懷', '龙翔寺言懷', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["眠雲喜道存，讀易過朝昏。","喬木青連郭，長河白瀉門。","鐘沈殘月塢，鳥去夕陽村。","搜此成閑句，期逢作者論。"]', '["眠云喜道存，读易過朝昏。","喬木青連郭，长河白瀉门。","鐘沈殘月塢，鸟去夕陽村。","搜此成闲句，期逢作者論。"]', '诗', 'shi', '', NULL, '龍翔寺言懷 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14592c94-949d-4adb-8e5c-834ccf0bc08b', '龍翔寺居夏日寄獻王尚書', '龙翔寺居夏日寄獻王尚书', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["那期高斾下，得遇重臣知。","泉石容居止，風沙免路岐。","河兼落下望，句入大荒思。","無復愁煩暑，迴山翠閣危。"]', '["那期高斾下，得遇重臣知。","泉石容居止，风沙免路岐。","河兼落下望，句入大荒思。","無复愁煩暑，迴山翠閣危。"]', '诗', 'shi', '', NULL, '龍翔寺居夏日寄獻王尚書 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62884693-ae3c-4a9e-a0fc-1595fb2c3ab6', '題弘濟寺不出院僧', '題弘濟寺不出院僧', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["楚鞋應此世，祇遶砌苔休。","色相栽花視，身心坐石修。","聲寒通節院，城黑見烽樓。","欲取閑雲並，閑雲有去留。"]', '["楚鞋應此世，祇遶砌苔休。","色相栽花視，身心坐石修。","声寒通節院，城黑见烽楼。","欲取闲云並，闲云有去留。"]', '诗', 'shi', '', NULL, '題弘濟寺不出院僧 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5127db9b-4afa-4697-8b2c-d4d560bc9c71', '寄劉錄事', '寄劉錄事', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["城西青島寺，累夏漱寒泉。","今在提綱所，應難掃石眠。","風沙榆塞迥，波浪橘洲偏。","重整瀟湘棹，心期更幾年。"]', '["城西青島寺，累夏漱寒泉。","今在提綱所，應难掃石眠。","风沙榆塞迥，波浪橘洲偏。","重整瀟湘棹，心期更幾年。"]', '诗', 'shi', '', NULL, '寄劉錄事 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90be1917-c155-4ef7-8fe8-6584c1a45137', '酬王檀見寄', '酬王檀见寄', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["馳心棲杳冥，何物比清冷。","夜月照巫峽，秋風吹洞庭。","酬難塵鬢皓，坐久壁燈青。","竟晚蒼山詠，喬枝有鶴聽。"]', '["驰心棲杳冥，何物比清冷。","夜月照巫峽，秋风吹洞庭。","酬难塵鬢皓，坐久壁灯青。","竟晚蒼山詠，喬枝有鹤听。"]', '诗', 'shi', '', NULL, '酬王檀見寄 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d07f5b-2e76-4874-8ad2-aa27a1c0f464', '寺居秋日對雨有懷', '寺居秋日对雨有懷', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["修修復雭雭，黃葉此時飛。","隱几客吟斷，鄰房僧話稀。","鴿寒棲樹定，螢濕在窗微。","即事瀟湘渚，漁翁披草衣。"]', '["修修复雭雭，黄葉此时飞。","隐几客吟斷，鄰房僧話稀。","鴿寒棲樹定，螢濕在窗微。","即事瀟湘渚，漁翁披草衣。"]', '诗', 'shi', '', NULL, '寺居秋日對雨有懷 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc41b8f-f284-403a-bd48-06765f526724', '答劉錄事夜月懷湘西友人見寄', '答劉錄事夜月懷湘西友人见寄', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["相逢仍朔漠，相問即波濤。","江思葦花折，笛聲關月高。","簿書君閱倦，章句我吟勞。","竟夕空凭閣，長河漴石壕。"]', '["相逢仍朔漠，相问即波濤。","江思葦花折，笛声关月高。","簿书君閱倦，章句我吟勞。","竟夕空凭閣，长河漴石壕。"]', '诗', 'shi', '', NULL, '答劉錄事夜月懷湘西友人見寄 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a750206e-ee88-4e0b-9bc3-4fc745032274', '上高侍御', '上高侍御', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["舊隱白雲峰，生涯落葉同。","關河一棲旅，楊柳十東風。","迹處龍鍾內，聲居汩沒中。","酬恩若有地，寧止殺微躬。"]', '["旧隐白云峰，生涯落葉同。","关河一棲旅，楊柳十东风。","迹处龙鍾內，声居汩沒中。","酬恩若有地，寧止殺微躬。"]', '诗', 'shi', '', NULL, '上高侍御 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e56a5e4-4d13-47b1-837d-39fe1676f20d', '冬日寄友人', '冬日寄友人', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["空爲梁甫吟，誰竟是知音。","風雪坐閑夜，鄉園來舊心。","滄江孤棹迥，落日一鐘深。","君子久忘我，此誠甘自沈。"]', '["空爲梁甫吟，誰竟是知音。","风雪坐闲夜，乡园来旧心。","滄江孤棹迥，落日一鐘深。","君子久忘我，此誠甘自沈。"]', '诗', 'shi', '', NULL, '冬日寄友人 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337e9742-7a04-42c4-82d0-cfea2c2a95b3', '冬夜宿余正字靜恭里閑居', '冬夜宿余正字静恭里闲居', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["每來多便宿，不負白雲言。","古木朔風動，寒城疎雪翻。","微燈懸刻漏，舊夢返湘沅。","先是琴邊起，知爲閣務繁。"]', '["每来多便宿，不負白云言。","古木朔风动，寒城疎雪翻。","微灯懸刻漏，旧梦返湘沅。","先是琴邊起，知爲閣務繁。"]', '诗', 'shi', '', NULL, '冬夜宿余正字靜恭里閑居 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e51284-1ded-45d7-8444-fee7da266d28', '得子姪書', '得子姪书', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["遠書來阮巷，闕下見江東。","不得經史力，枉拋耕稼功。","鴈天霞脚雨，漁夜葦條風。","無復琴桮興，開懷向爾同。"]', '["远书来阮巷，闕下见江东。","不得經史力，枉拋耕稼功。","鴈天霞脚雨，漁夜葦條风。","無复琴桮兴，开懷向爾同。"]', '诗', 'shi', '', NULL, '得子姪書 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de19af25-fc83-42bd-a05b-38c4cfea9796', '獻知己', '獻知己', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["亦忝受恩身，當殊投刺新。","竟蒙分玉石，終不離埃塵。","大谷非無暖，幽枝自未春。","昏昏過朝夕，應念苦吟人。"]', '["亦忝受恩身，當殊投刺新。","竟蒙分玉石，終不離埃塵。","大谷非無暖，幽枝自未春。","昏昏過朝夕，應念苦吟人。"]', '诗', 'shi', '', NULL, '獻知己 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4a385c-778a-42b9-92c9-2e6294d5e302', '贈張濆處士', '贈張濆处士', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["露白覆棋宵，林青讀易朝。","道高天子問，名重四方招。","許鶴歸華頂，期僧過石橋。","雖然在京國，心跡自逍遙。"]', '["露白覆棋宵，林青读易朝。","道高天子问，名重四方招。","許鹤归华頂，期僧過石橋。","雖然在京国，心跡自逍遙。"]', '诗', 'shi', '', NULL, '贈張濆處士 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b268a5ae-de77-43f2-9f61-22ad746a3f3f', '早秋寺居酬張侍御六韻見寄', '早秋寺居酬張侍御六韻见寄', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["六十上清冥，曉緘東越藤。","山光紫衣陟，寺影白雲凝。","濕葉起寒鳥，深林驚古僧。","微風窗靜展，細雨閣吟登。","清韻嶽磬遠，佳音湖水澄。","却思前所獻，何以豸冠稱。"]', '["六十上清冥，晓緘东越藤。","山光紫衣陟，寺影白云凝。","濕葉起寒鸟，深林驚古僧。","微风窗静展，細雨閣吟登。","清韻嶽磬远，佳音湖水澄。","却思前所獻，何以豸冠稱。"]', '诗', 'shi', '', NULL, '早秋寺居酬張侍御六韻見寄 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588b124d-9213-448e-9875-bffd63febf7e', '和段學士對雪', '和段学士对雪', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["盈尺知豐稔，開窗對酒壺。","飄當大野匝，灑到急流無。","密際西風盡，凝間朔氣扶。","乾摧鳥棲枿，冷射夜殘罏。","贊月澄斜漢，兼沙攪北湖。","慙於郢客坐，一此調巴歈。"]', '["盈尺知豐稔，开窗对酒壺。","飄當大野匝，灑到急流無。","密際西风尽，凝间朔氣扶。","乾摧鸟棲枿，冷射夜殘罏。","贊月澄斜漢，兼沙攪北湖。","慙於郢客坐，一此調巴歈。"]', '诗', 'shi', '', NULL, '和段學士對雪 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a880973-a905-4a16-8127-6d6a1348c8a2', '監試夜雨滴空堦', '監試夜雨滴空堦', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["霎霎復淒淒，飄松又灑槐。","氣濛蛛網檻，聲疊蘚花堦。","古壁青燈動，深庭濕葉埋。","徐垂舊夗瓦，競歷小茅齋。","冷與陰蟲間，清將玉漏諧。","病身唯展轉，誰見此時懷。"]', '["霎霎复淒淒，飄松又灑槐。","氣濛蛛網檻，声叠蘚花堦。","古壁青灯动，深庭濕葉埋。","徐垂旧夗瓦，競歷小茅斋。","冷與陰蟲间，清將玉漏諧。","病身唯展轉，誰见此时懷。"]', '诗', 'shi', '', NULL, '監試夜雨滴空堦 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87acee2c-c3bc-4d63-8b68-4c79cea0fdbe', '春雨如膏', '春雨如膏', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["冪冪斂輕塵，濛濛濕野春。","細光添柳重，幽點濺花勻。","慘淡游絲景，陰沈落絮辰。","迴低飛蝶翅，寒滴語禽身。","灑岳摧餘雪，吹江疊遠蘋。","東城與西陌，晴後趣何新。"]', '["冪冪斂轻塵，濛濛濕野春。","細光添柳重，幽点濺花勻。","慘淡游絲景，陰沈落絮辰。","迴低飞蝶翅，寒滴語禽身。","灑岳摧餘雪，吹江叠远蘋。","东城與西陌，晴後趣何新。"]', '诗', 'shi', '', NULL, '春雨如膏 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144e5455-814b-4c56-bd48-47f598aba26b', '送友人南中訪舊知', '送友人南中訪旧知', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["春盡大方遊，思君便白頭。","地蒸川有毒，天暖樹無秋。","水急三巴險，猨分五嶺愁。","爲緣知己分，南國必淹留。"]', '["春尽大方游，思君便白头。","地蒸川有毒，天暖樹無秋。","水急三巴險，猨分五嶺愁。","爲緣知己分，南国必淹留。"]', '诗', 'shi', '', NULL, '送友人南中訪舊知 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8437a0b-6675-4d49-829a-08d9a543c90d', '玄都觀李尊師', '玄都观李尊師', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["蘚幘翠髯公，存思古觀空。","曉壇檉葉露，晴圃柳花風。","壽已將椿並，碁難見局終。","何當與高鶴，飛去海光中。"]', '["蘚幘翠髯公，存思古观空。","晓壇檉葉露，晴圃柳花风。","壽已將椿並，碁难见局終。","何當與高鹤，飞去海光中。"]', '诗', 'shi', '', NULL, '玄都觀李尊師 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bace5027-79a4-46a3-b6b2-ac15930c5c3e', '送石賁歸吳興', '送石賁归吳兴', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["同志幸同年，高堂君獨還。","齊榮恩未報，共隱事皆閑。","訪寺臨河岸，開樓見海山。","洛中推二陸，莫久戀鄉關。"]', '["同志幸同年，高堂君独還。","齊榮恩未報，共隐事皆闲。","訪寺臨河岸，开楼见海山。","洛中推二陸，莫久戀乡关。"]', '诗', 'shi', '', NULL, '送石賁歸吳興 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b773ff0-e4d4-46bd-b85b-c4a2db753c84', '感遇', '感遇', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["江鄉十年別，京國累日同。","在客幾多事，俱付酒杯中。"]', '["江乡十年別，京国累日同。","在客幾多事，俱付酒杯中。"]', '诗', 'shi', '', NULL, '感遇 喻鳧 shi');
